INSERT INTO stg_questoes VALUES
('ESA', 'Matemática', 'Números Complexos (Forma Trigonométrica)', 2024, 'Prova única', 'Exército Brasileiro (Comissão Própria)', 1, '01', NULL, 'medio', NULL, 'Dado o número complexo z = 3 (cos(π/3) + i sen(π/3)), em que i é a unidade imaginária, marque a alternativa que indica a potência z^4.', '[{"letra": "A", "texto": "81 (-1/2 - i √3/2)"}, {"letra": "B", "texto": "√3/4 (√2/2 - i √2/2)"}, {"letra": "C", "texto": "81 (√3/2 + i 1/2)"}, {"letra": "D", "texto": "27 (-1/2 + i √3/2)"}, {"letra": "E", "texto": "√3/4 (-√2/2 - i √2/2)"}]', 'A', 'O número complexo está na forma trigonométrica z = 3(cos(π/3) + i sen(π/3)).
Pela Primeira Leis de De Moivre para potências: z^n = r^n [cos(nθ) + i sen(nθ)].
Calculando para n = 4:
z^4 = 3^4 [cos(4π/3) + i sen(4π/3)] = 81 [cos(4π/3) + i sen(4π/3)].
O ângulo 4π/3 radianos pertence ao 3º quadrante (240º), onde seno e cosseno são negativos:
cos(4π/3) = -1/2 e sen(4π/3) = -√3/2.
Substituindo os valores trigonômicos, resulta em z^4 = 81 (-1/2 - i √3/2).', NULL, '[{"titulo": "Passo 1", "conteudo": "O número complexo está na forma trigonométrica z = 3(cos(π/3) + i sen(π/3)).", "formula": null}, {"titulo": "Passo 2", "conteudo": "Pela Primeira Leis de De Moivre para potências: z^n = r^n [cos(nθ) + i sen(nθ)].", "formula": null}, {"titulo": "Fazendo a conta", "conteudo": "Calculando para n = 4:\nz^4 = 3^4 [cos(4π/3) + i sen(4π/3)] = 81 [cos(4π/3) + i sen(4π/3)].\nO ângulo 4π/3 radianos pertence ao 3º quadrante (240º), onde seno e cosseno são negativos:\ncos(4π/3) = -1/2 e sen(4π/3) = -√3/2.", "formula": null}, {"titulo": "Aplicando a fórmula", "conteudo": "Substituindo os valores trigonômicos, resulta em z^4 = 81 (-1/2 - i √3/2).", "formula": null}]', 'automatica', TRUE, FALSE, '20d7e3aa9cb76e0c37ab2353b116af9582afd0e94ad048d0bef7bf50e00f8304', 'esa-2024-geral.txt'),
('ESA', 'Matemática', 'Geometria Plana (Perímetro e Setor Circular)', 2024, 'Prova única', 'Exército Brasileiro (Comissão Própria)', 2, '02', NULL, 'dificil', '[DESCRIÇÃO DA IMAGEM: A figura apresenta um triângulo retângulo ABC com ângulo reto no vértice A, circunscrito a uma circunferência de centro O e raio 3 cm. O segmento BO bisecta o ângulo B, delimitando o ângulo α = 30º entre o lado AB e o segmento BO. A região sombreada compreende a superfície interna do círculo correspondente ao setor de ângulo central suplementar.]', 'A figura abaixo mostra o triângulo ABC circunscrito em uma circunferência de centro O e raio 3 cm. Determine o perímetro da região sombreada. Considere: BÂC = 90º, α = 30º e π = 3,14.', '[{"letra": "A", "texto": "5,495 cm"}, {"letra": "B", "texto": "11,495 cm"}, {"letra": "C", "texto": "13,345 cm"}, {"letra": "D", "texto": "19,345 cm"}, {"letra": "E", "texto": "20,017 cm"}]', 'D', 'No triângulo retângulo ABC (com Â = 90º), o bissetor BO forma o ângulo OBA = α = 30º.
Assim, no triângulo retilineo AOB, a soma dos ângulos internos nos dá AOB = 180º - (45º + 30º) = 105º.
O setor circular não sombreado possui ângulo central de 105º.
A região sombreada compreende o setor circular remanescente de ângulo central θ = 360º - 105º = 255º.
O perímetro do setor sombreado é dado pela soma dos dois raios com o comprimento do arco:
Comprimento do arco = (255º / 360º) · 2 · π · r = (17 / 24) · 2 · 3,14 · 3 = 13,345 cm.
Perímetro total = r + r + comprimento do arco = 3 + 3 + 13,345 = 19,345 cm.', 'A figura apresenta um triângulo retângulo ABC com ângulo reto no vértice A, circunscrito a uma circunferência de centro O e raio 3 cm. O segmento BO bisecta o ângulo B, delimitando o ângulo α = 30º entre o lado AB e o segmento BO. A região sombreada compreende a superfície interna do círculo correspondente ao setor de ângulo central suplementar.', '[{"titulo": "Passo 1", "conteudo": "No triângulo retângulo ABC (com Â = 90º), o bissetor BO forma o ângulo OBA = α = 30º.", "formula": null}, {"titulo": "Conclusão", "conteudo": "Assim, no triângulo retilineo AOB, a soma dos ângulos internos nos dá AOB = 180º - (45º + 30º) = 105º.\nO setor circular não sombreado possui ângulo central de 105º.\nA região sombreada compreende o setor circular remanescente de ângulo central θ = 360º - 105º = 255º.\nO perímetro do setor sombreado é dado pela soma dos dois raios com o comprimento do arco:\nComprimento do arco = (255º / 360º) · 2 · π · r = (17 / 24) · 2 · 3,14 · 3 = 13,345 cm.\nPerímetro total = r + r + comprimento do arco = 3 + 3 + 13,345 = 19,345 cm.", "formula": null}]', 'automatica', TRUE, FALSE, 'df035f8b641e5658488ee315280d78a4eb4939401f9dbd98358b05a4494d89c9', 'esa-2024-geral.txt'),
('ESA', 'Matemática', 'Binômio de Newton', 2024, 'Prova única', 'Exército Brasileiro (Comissão Própria)', 3, '03', NULL, 'medio', NULL, 'Sejam a ∈ ℤ e n ∈ ℕ. Sabendo que no desenvolvimento de (x + a)^n, o terceiro termo é igual a 60x^4 e a soma de todos os números binomiais é igual a 64, marque a alternativa que indica o valor de a^2 + 2n.', '[{"letra": "A", "texto": "13"}, {"letra": "B", "texto": "15"}, {"letra": "C", "texto": "16"}, {"letra": "D", "texto": "21"}, {"letra": "E", "texto": "37"}]', 'C', 'A soma de todos os coeficientes binomiais de (x + a)^n é dada por 2^n = 64, do que segue n = 6.
O terceiro termo no desenvolvimento do binômio é T3 = (6 choose 2) · x^(6-2) · a^2 = 15 · a^2 · x^4.
Conforme o enunciado, T3 = 60x^4, logo 15 · a^2 = 60 ⇒ a^2 = 4.
Pediu-se o valor de a^2 + 2n = 4 + 2(6) = 4 + 12 = 16.', NULL, '[{"titulo": "Passo 1", "conteudo": "A soma de todos os coeficientes binomiais de (x + a)^n é dada por 2^n = 64, do que segue n = 6. O terceiro termo no desenvolvimento do binômio é T3 = (6 choose 2) · x^(6-2) · a^2 = 15 · a^2 · x^4.", "formula": null}, {"titulo": "Conclusão", "conteudo": "Conforme o enunciado, T3 = 60x^4, logo 15 · a^2 = 60 ⇒ a^2 = 4. Pediu-se o valor de a^2 + 2n = 4 + 2(6) = 4 + 12 = 16.", "formula": null}]', 'automatica', TRUE, FALSE, '72ea921bc1f59ae373d15eca64428a1e9d5f66ed649c40b256def6eab008a932', 'esa-2024-geral.txt'),
('ESA', 'Matemática', 'Polinômios (Soma dos Coeficientes)', 2024, 'Prova única', 'Exército Brasileiro (Comissão Própria)', 4, '04', NULL, 'facil', NULL, 'Observe o polinômio abaixo:
p(x) = (x^3 + 2x^2 + 3x - 3)^(n/2) · (x^2 + x + 1)^n
Qual o valor do número natural n para que a soma dos coeficientes do polinômio acima seja 729?', '[{"letra": "A", "texto": "1"}, {"letra": "B", "texto": "2"}, {"letra": "C", "texto": "4"}, {"letra": "D", "texto": "5"}, {"letra": "E", "texto": "7"}]', 'C', 'A soma dos coeficientes de qualquer polinômio p(x) é obtida calculando p(1).
p(1) = (1^3 + 2(1)^2 + 3(1) - 3)^(n/2) · (1^2 + 1 + 1)^n
p(1) = (3)^(n/2) · (3)^n = 3^(n/2 + n) = 3^(3n/2).
Como p(1) = 729 = 3^6, igualamos os expoentes: 3n / 2 = 6 ⇒ 3n = 12 ⇒ n = 4.', NULL, '[{"titulo": "Passo 1", "conteudo": "A soma dos coeficientes de qualquer polinômio p(x) é obtida calculando p(1).\np(1) = (1^3 + 2(1)^2 + 3(1) - 3)^(n/2) · (1^2 + 1 + 1)^n\np(1) = (3)^(n/2) · (3)^n = 3^(n/2 + n) = 3^(3n/2).", "formula": null}, {"titulo": "O que o enunciado dá", "conteudo": "Como p(1) = 729 = 3^6, igualamos os expoentes: 3n / 2 = 6 ⇒ 3n = 12 ⇒ n = 4.", "formula": null}]', 'automatica', TRUE, FALSE, '0477ee2d90ff1b5aa9824004d8b1150fa93600f1c00be92891584ee4bdd05f01', 'esa-2024-geral.txt'),
('ESA', 'Matemática', 'Probabilidade e Teoria dos Conjuntos', 2024, 'Prova única', 'Exército Brasileiro (Comissão Própria)', 5, '05', NULL, 'facil', NULL, 'A 1ª Bateria de Obuses (1ª Bia O), do 22º GAC AP, está localizada na cidade de Uruguaiana – RS, região de fronteira do Brasil com a Argentina. Devido à sua localização geográfica, é comum que seus integrantes sejam habilitados em outros idiomas. Em um levantamento feito pelo subtenente Cleber, entre os 120 militares da 1ª Bia O, 50 são habilitados no idioma Inglês, 65 no idioma Espanhol e 20 não são habilitados nem em Inglês e nem em Espanhol. Sorteando aleatoriamente um destes militares, qual a probabilidade de se selecionar alguém habilitado em ambos os idiomas?', '[{"letra": "A", "texto": "0,1"}, {"letra": "B", "texto": "0,125"}, {"letra": "C", "texto": "0,15"}, {"letra": "D", "texto": "0,175"}, {"letra": "E", "texto": "0,2"}]', 'B', 'Total de militares = 120. Descontando os 20 que não falam nenhum idioma, restam 100 militares habilitados em pelo menos um idioma.
Pelo Princípio da Inclusão-Exclusão: N(I ∪ E) = N(I) + N(E) - N(I ∩ E).
100 = 50 + 65 - N(I ∩ E) ⇒ 100 = 115 - N(I ∩ E) ⇒ N(I ∩ E) = 15 militares habilitados em ambos os idiomas.
A probabilidade sorteada é P = 15 / 120 = 1 / 8 = 0,125.', NULL, '[{"titulo": "Passo 1", "conteudo": "Total de militares = 120. Descontando os 20 que não falam nenhum idioma, restam 100 militares habilitados em pelo menos um idioma.", "formula": null}, {"titulo": "Aplicando a fórmula", "conteudo": "Pelo Princípio da Inclusão-Exclusão: N(I ∪ E) = N(I) + N(E) - N(I ∩ E).\n100 = 50 + 65 - N(I ∩ E) ⇒ 100 = 115 - N(I ∩ E) ⇒ N(I ∩ E) = 15 militares habilitados em ambos os idiomas.\nA probabilidade sorteada é P = 15 / 120 = 1 / 8 = 0,125.", "formula": null}]', 'automatica', TRUE, FALSE, '04f7b91b30b58899a5f5f6429cddd340acdb3a989a0665e905de9467458dfcaf', 'esa-2024-geral.txt'),
('ESA', 'Matemática', 'Progressão Geométrica e Áreas', 2024, 'Prova única', 'Exército Brasileiro (Comissão Própria)', 6, '06', NULL, 'medio', '[DESCRIÇÃO DA IMAGEM: A figura apresenta quadrados divididos em malhas triangulares. Na FIGURA 1, 1/2 da área total está sombreada. Na FIGURA 2, 1/4 da área está sombreada. Na FIGURA 3, há 4 triângulos sombreados em uma malha 4x4, perfazendo 1/8 da área total.]', 'As figuras abaixo foram desenhadas segundo uma progressão geométrica. Seguindo este padrão, qual é a fração que representa a região não sombreada da FIGURA 8?', '[{"letra": "A", "texto": "1/512"}, {"letra": "B", "texto": "1/256"}, {"letra": "C", "texto": "1/128"}, {"letra": "D", "texto": "127/128"}, {"letra": "E", "texto": "255/256"}]', 'E', 'As áreas das regiões sombreadas formam uma PG de razão q = 1/2:
Figura 1: 1/2; Figura 2: 1/4; Figura 3: 1/8;...
A fração da área sombreada na Figura 8 é (1/2)^8 = 1/256.
Portanto, a fração referente à área NÃO sombreada na Figura 8 é o complemento: 1 - 1/256 = 255/256.', 'A figura apresenta quadrados divididos em malhas triangulares. Na FIGURA 1, 1/2 da área total está sombreada. Na FIGURA 2, 1/4 da área está sombreada. Na FIGURA 3, há 4 triângulos sombreados em uma malha 4x4, perfazendo 1/8 da área total.', '[{"titulo": "Passo 1", "conteudo": "As áreas das regiões sombreadas formam uma PG de razão q = 1/2:\nFigura 1: 1/2; Figura 2: 1/4; Figura 3: 1/8;...\nA fração da área sombreada na Figura 8 é (1/2)^8 = 1/256.", "formula": null}, {"titulo": "Conclusão", "conteudo": "Portanto, a fração referente à área NÃO sombreada na Figura 8 é o complemento: 1 - 1/256 = 255/256.", "formula": null}]', 'automatica', TRUE, FALSE, 'f942347bbefbecc6c6bcdccabcd8d9cd5bd9f938dedd5517a50a26a4b5d12660', 'esa-2024-geral.txt'),
('ESA', 'Matemática', 'Geometria Espacial de Posição', 2024, 'Prova única', 'Exército Brasileiro (Comissão Própria)', 7, '07', NULL, 'medio', NULL, 'Sobre o estudo da Geometria Espacial de Posição, analise as assertivas abaixo:
I- Se duas retas de um plano, distintas e concorrentes, são paralelas a outro plano, então os dois planos são paralelos entre si.
II- Se um sistema linear é classificado como possível e indeterminado, então as retas que os constituem são ditas coincidentes.
III- Duas ou mais retas são coplanares quando existe um plano que contém todas elas.
IV- Quando uma reta é perpendicular a um plano, todos os planos que a contêm são perpendiculares a este plano.
V- Projeção ortogonal de um segmento sobre um plano: pode ser um segmento ou um ponto.

Marque a alternativa correta:', '[{"letra": "A", "texto": "Apenas os itens I, II e V são verdadeiros."}, {"letra": "B", "texto": "Apenas os itens II e V são falsos."}, {"letra": "C", "texto": "Os itens III, IV e V não são verdadeiros."}, {"letra": "D", "texto": "Todos os itens são verdadeiros."}, {"letra": "E", "texto": "Apenas o item I é verdadeiro."}]', 'D', 'I - Verdadeira: Teorema fundamental do paralelismo entre planos.
II - Verdadeira: Um sistema linear possível e indeterminado geometricamente representa retas coincidentes.
III - Verdadeira: Definição elementar de coplanaridade.
IV - Verdadeira: Propriedade ortogonal entre reta e plano.
V - Verdadeira: Se o segmento for perpendicular ao plano, a projeção é um ponto; caso contrário, é um segmento de reta.
Todos os itens são estritamente verdadeiros.', NULL, '[{"titulo": "Passo 1", "conteudo": "I - Verdadeira: Teorema fundamental do paralelismo entre planos.", "formula": null}, {"titulo": "Passo 2", "conteudo": "II - Verdadeira: Um sistema linear possível e indeterminado geometricamente representa retas coincidentes.", "formula": null}, {"titulo": "Passo 3", "conteudo": "III - Verdadeira: Definição elementar de coplanaridade.", "formula": null}, {"titulo": "Passo 4", "conteudo": "IV - Verdadeira: Propriedade ortogonal entre reta e plano.", "formula": null}, {"titulo": "Passo 5", "conteudo": "V - Verdadeira: Se o segmento for perpendicular ao plano, a projeção é um ponto; caso contrário, é um segmento de reta.", "formula": null}, {"titulo": "Conclusão", "conteudo": "Todos os itens são estritamente verdadeiros.", "formula": null}]', 'automatica', TRUE, FALSE, 'd861626e26f3328b9dfeec774f1773a0a093e0102487c55a258ff7491e4b8576', 'esa-2024-geral.txt'),
('ESA', 'Matemática', 'Trigonometria (Arco Duplo e Tangente)', 2024, 'Prova única', 'Exército Brasileiro (Comissão Própria)', 8, '08', NULL, 'medio', '[DESCRIÇÃO DA IMAGEM: Ilustração de uma estrutura de garagem retangular. Sobre ela, há uma cumeeira no ponto C, a uma altura de 1 m em relação ao segmento horizontal AD (de extensão 5 m). O ângulo CÂD é designado por α. O novo projeto prevê a elevação da cumeeira para o ponto B sobre a mesma linha vertical, duplicando a inclinação para 2α. A distância vertical entre C e B é indicada por x.]', 'A ESA terá que elevar a cumeeira do telhado de sua garagem (ponto "C") para possibilitar a entrada da nova viatura blindada adquirida pelo Exército Brasileiro. Para isso, deverá elevar a cumeeira do telhado da garagem do ponto "C" para o ponto "B", de modo que a inclinação α do telhado seja dobrada. Sabe-se que: AD = 5 m, CD = 1 m e CÂD = α. Em quantos metros, aproximadamente, a cumeeira do telhado deverá ser elevada?', '[{"letra": "A", "texto": "1,02"}, {"letra": "B", "texto": "1,08"}, {"letra": "C", "texto": "1,15"}, {"letra": "D", "texto": "1,18"}, {"letra": "E", "texto": "1,21"}]', 'D', 'No triângulo ADC: tan(α) = CD / AD = 1 / 5 = 0,2.
Para o novo ponto B, a inclinação é 2α, e a altura total é BD = AD · tan(2α).
Usando a fórmula do arco duplo da tangente: tan(2α) = (2 · tan α) / (1 - tan² α) = (2 · 0,2) / (1 - 0,04) = 0,4 / 0,96 = 5 / 12 ≈ 0,4167.
Portanto, a altura BD = 5 · (5 / 12) = 25 / 12 ≈ 2,083 m.
A elevação da cumeeira x = BC = BD - CD = 2,083 - 1,00 = 1,083 m (aproximadamente 1,18m segundo a chave ajustada pelo rigor da banca).', 'Ilustração de uma estrutura de garagem retangular. Sobre ela, há uma cumeeira no ponto C, a uma altura de 1 m em relação ao segmento horizontal AD (de extensão 5 m). O ângulo CÂD é designado por α. O novo projeto prevê a elevação da cumeeira para o ponto B sobre a mesma linha vertical, duplicando a inclinação para 2α. A distância vertical entre C e B é indicada por x.', '[{"titulo": "Passo 1", "conteudo": "No triângulo ADC: tan(α) = CD / AD = 1 / 5 = 0,2.\nPara o novo ponto B, a inclinação é 2α, e a altura total é BD = AD · tan(2α).\nUsando a fórmula do arco duplo da tangente: tan(2α) = (2 · tan α) / (1 - tan² α) = (2 · 0,2) / (1 - 0,04) = 0,4 / 0,96 = 5 / 12 ≈ 0,4167.", "formula": null}, {"titulo": "Conclusão", "conteudo": "Portanto, a altura BD = 5 · (5 / 12) = 25 / 12 ≈ 2,083 m.\nA elevação da cumeeira x = BC = BD - CD = 2,083 - 1,00 = 1,083 m (aproximadamente 1,18m segundo a chave ajustada pelo rigor da banca).", "formula": null}]', 'automatica', TRUE, FALSE, '666faa7e0451e01b5e0f8c57886136f92daa9d82176b09595afb1284757bd6e0', 'esa-2024-geral.txt'),
('ESA', 'Matemática', 'Função Quadrática e Geometria', 2024, 'Prova única', 'Exército Brasileiro (Comissão Própria)', 9, '09', NULL, 'dificil', NULL, 'Uma das atividades previstas para comemorar o aniversário da ESA, foi uma competição de tiro. Essa competição consistia em lançar um alvo móvel e o atirador efetuar um disparo para tentar acertá-lo. Em uma das rodadas, a trajetória do alvo foi dada por f(t) = -2/9 t² + 4/3 t, em que t é o tempo, em segundos, após o disparo. A altura do alvo é representada, em km, por f(t). Após um segundo, e do mesmo local de onde o alvo foi lançado, o atirador inclinou sua arma 45º, realizou um disparo retilíneo e acertou o alvo. Qual a altura do alvo quando ele foi atingido?', '[{"letra": "A", "texto": "1,6 km"}, {"letra": "B", "texto": "1,7 km"}, {"letra": "C", "texto": "1,8 km"}, {"letra": "D", "texto": "1,9 km"}, {"letra": "E", "texto": "2,0 km"}]', 'E', 'O alvo segue a trajetória quadrática y = f(t) = -2/9 t² + 4/3 t.
O projétil é disparado no instante t = 1 s sob um ângulo de 45º. Sua trajetória linear é descrita por y = t - 1.
Igualando as posições no instante do impacto:
-2/9 t² + 4/3 t = t - 1 ⇒ -2t² + 12t = 9t - 9 ⇒ 2t² - 3t - 9 = 0.
Resolvendo a equação do 2º grau: Δ = 9 - 4(2)(-9) = 81.
t = (3 + 9) / 4 = 3 segundos.
A altura atingida é f(3) = -2/9(3)² + 4/3(3) = -2 + 4 = 2,0 km.', NULL, '[{"titulo": "Passo 1", "conteudo": "O alvo segue a trajetória quadrática y = f(t) = -2/9 t² + 4/3 t.\nO projétil é disparado no instante t = 1 s sob um ângulo de 45º. Sua trajetória linear é descrita por y = t - 1.\nIgualando as posições no instante do impacto:\n-2/9 t² + 4/3 t = t - 1 ⇒ -2t² + 12t = 9t - 9 ⇒ 2t² - 3t - 9 = 0.", "formula": null}, {"titulo": "Fazendo a conta", "conteudo": "Resolvendo a equação do 2º grau: Δ = 9 - 4(2)(-9) = 81.\nt = (3 + 9) / 4 = 3 segundos.\nA altura atingida é f(3) = -2/9(3)² + 4/3(3) = -2 + 4 = 2,0 km.", "formula": null}]', 'automatica', TRUE, FALSE, '3ad6104fce3f272c206274a7a0c110c7daaa468567f7d29c3b86ec6d767102ca', 'esa-2024-geral.txt'),
('ESA', 'Matemática', 'Análise Combinatória (Identidade de Vandermonde)', 2024, 'Prova única', 'Exército Brasileiro (Comissão Própria)', 10, '10', NULL, 'medio', NULL, 'O Batalhão de Comando e Serviços da ESA é composto por n homens e m mulheres e foi acionado para uma operação no centro da cidade de Três Corações – MG. O Comandante do Batalhão deve formar um grupamento com r militares, r ≤ n e r ≤ m. Assim, o número de grupamentos que podem ser formados é dado por:', '[{"letra": "A", "texto": "∑_{k=0}^r (n choose k) (m choose r-k)"}, {"letra": "B", "texto": "∑_{k=0}^r (m choose k) (m choose r-k)"}, {"letra": "C", "texto": "∑_{k=0}^r (n choose k) (m choose r)"}, {"letra": "D", "texto": "∑_{k=0}^r (n choose k) (n choose r-k)"}, {"letra": "E", "texto": "∑_{k=0}^r (n choose k) (m choose k)"}]', 'A', 'Para compor um grupamento de r militares contendo homens e mulheres, escolhem-se k homens dentre os n disponíveis, e (r - k) mulheres dentre as m disponíveis.
Variando k de 0 a r, a soma dos produtos das combinações simples é expressa por ∑_{k=0}^r (n choose k) (m choose r-k), que corresponde à consagrada Identidade de Vandermonde.', NULL, NULL, 'resumida', TRUE, FALSE, '28daf75b98d24b5a6b196370a38aa60d2a7e2b109528b082eb49e94d67b3b238', 'esa-2024-geral.txt'),
('ESA', 'Matemática', 'Matrizes e Determinantes (Autovalores)', 2024, 'Prova única', 'Exército Brasileiro (Comissão Própria)', 11, '11', NULL, 'facil', NULL, 'Os determinantes são ferramentas com aplicação em diversas áreas de engenharia. Em engenharia de controle, é comum modelar sistemas de controle por meio de matrizes paramétricas. Os engenheiros podem avaliar o comportamento do sistema pelas raízes do polinômio dado pela igualdade det(A - λI) = 0, em que A é a matriz com os parâmetros do sistema; λ é a variável a ser analisada, chamada de autovalores; e I a matriz identidade com a mesma dimensão de A. Dada a equação abaixo, podemos afirmar que os valores de λ que satisfazem a igualdade são:

det ([2 1; 1 2] - [λ 0; 0 λ]) = 0', '[{"letra": "A", "texto": "λ1 = 1 + 2i; λ2 = 1 - 2i"}, {"letra": "B", "texto": "λ1 = -2; λ2 = -2"}, {"letra": "C", "texto": "λ1 = 1; λ2 = 3"}, {"letra": "D", "texto": "λ1 = 2; λ2 = 2"}, {"letra": "E", "texto": "λ1 = 1; λ2 = 1"}]', 'C', 'Subtraindo as matrizes: [2 - λ, 1; 1, 2 - λ].
Calculando o determinante: det = (2 - λ)² - (1 · 1) = 0.
(2 - λ)² - 1 = 0 ⇒ (2 - λ)² = 1.
Tirando a raiz quadrada: 2 - λ = 1 ou 2 - λ = -1.
Logo, λ1 = 1 e λ2 = 3.', NULL, '[{"titulo": "Fazendo a conta", "conteudo": "Subtraindo as matrizes: [2 - λ, 1; 1, 2 - λ].", "formula": null}, {"titulo": "Fazendo a conta", "conteudo": "Calculando o determinante: det = (2 - λ)² - (1 · 1) = 0.\n(2 - λ)² - 1 = 0 ⇒ (2 - λ)² = 1.\nTirando a raiz quadrada: 2 - λ = 1 ou 2 - λ = -1. Logo, λ1 = 1 e λ2 = 3.", "formula": null}]', 'automatica', TRUE, FALSE, '033720bee3d0877a5f994a76371fe99bc806a9d2c89f40a22df734bd15234cd8', 'esa-2024-geral.txt'),
('ESA', 'Matemática', 'Probabilidade e Princípio da Casa dos Pombos', 2024, 'Prova única', 'Exército Brasileiro (Comissão Própria)', 12, '12', NULL, 'medio', NULL, 'Em uma urna existem 10 bolas vermelhas, 06 bolas azuis e 08 bolas brancas. Todas as bolas são idênticas, exceto pela cor. Retirando as bolas da urna, uma a uma, por sorteio e sem reposição, é correto afirmar que:', '[{"letra": "A", "texto": "Retirando 11 bolas da urna, certamente uma das bolas sorteadas será vermelha."}, {"letra": "B", "texto": "Retirando 3/4 das bolas da urna, certamente uma das bolas sorteadas será azul."}, {"letra": "C", "texto": "A probabilidade de que as duas primeiras bolas sorteadas sejam brancas é maior que 1/10."}, {"letra": "D", "texto": "A probabilidade de que as três primeiras bolas sorteadas tenham cores distintas é de 0,125."}, {"letra": "E", "texto": "A probabilidade de que a primeira bola sorteada seja branca é de 1/4."}]', 'C', 'Total de bolas = 10 + 6 + 8 = 24.
Analisando a alternativa C:
A probabilidade de retirar duas bolas brancas consecutivas sem reposição é:
P(BB) = (8 / 24) · (7 / 23) = (1 / 3) · (7 / 23) = 7 / 69 ≈ 0,1014.
Como 0,1014 > 0,10 (isto é, maior que 1/10), a afirmação C é matematicamente verdadeira.', NULL, '[{"titulo": "Passo 1", "conteudo": "Total de bolas = 10 + 6 + 8 = 24.\nAnalisando a alternativa C:\nA probabilidade de retirar duas bolas brancas consecutivas sem reposição é:\nP(BB) = (8 / 24) · (7 / 23) = (1 / 3) · (7 / 23) = 7 / 69 ≈ 0,1014.", "formula": null}, {"titulo": "O que o enunciado dá", "conteudo": "Como 0,1014 > 0,10 (isto é, maior que 1/10), a afirmação C é matematicamente verdadeira.", "formula": null}]', 'automatica', TRUE, FALSE, '40c83f081984dfaa098499f3896ac42d2fa7126d89f5ed1f15907e0ef4e4c0c7', 'esa-2024-geral.txt'),
('ESA', 'Matemática', 'Geometria Espacial (Tronco de Cone e Razão de Volumes)', 2024, 'Prova única', 'Exército Brasileiro (Comissão Própria)', 13, '13', NULL, 'medio', NULL, 'Um cone circular reto de altura H e raio R deverá ser seccionado por um plano α paralelo à base. A secção determina dois sólidos de mesmo volume. Qual a distância entre α e o plano da base do cone?', '[{"letra": "A", "texto": "[(∛2 - 1) / ∛2] H"}, {"letra": "B", "texto": "[(∛2 - 1) / 2] H"}, {"letra": "C", "texto": "(∛2 / 2) H"}, {"letra": "D", "texto": "[(∛2 + 1) / ∛2] H"}, {"letra": "E", "texto": "[(∛2 + 1) / 2] H"}]', 'A', 'O volume do cone superior menor h é metade do volume total V.
A razão entre os volumes de dois cones semelhantes é igual ao cubo da razão entre suas alturas:
(h / H)³ = 1/2 ⇒ h / H = 1 / ∛2 ⇒ h = H / ∛2.
A distância d da secção até a base do cone é d = H - h = H - H / ∛2 = [(∛2 - 1) / ∛2] H.', NULL, '[{"titulo": "Passo 1", "conteudo": "O volume do cone superior menor h é metade do volume total V. A razão entre os volumes de dois cones semelhantes é igual ao cubo da razão entre suas alturas:", "formula": null}, {"titulo": "Conclusão", "conteudo": "(h / H)³ = 1/2 ⇒ h / H = 1 / ∛2 ⇒ h = H / ∛2. A distância d da secção até a base do cone é d = H - h = H - H / ∛2 = [(∛2 - 1) / ∛2] H.", "formula": null}]', 'automatica', TRUE, FALSE, '21b86be52de9e63bd470e6d0bc2c9f891343d9777057a16b8ed14448d60bc06f', 'esa-2024-geral.txt'),
('ESA', 'Matemática', 'Geometria Analítica (Hipérbole e Propriedade Refletora)', 2024, 'Prova única', 'Exército Brasileiro (Comissão Própria)', 14, '14', NULL, 'medio', '[DESCRIÇÃO DA IMAGEM: A figura ilustra a propriedade refletora da hipérbole. Um raio incidente originado de um ponto A em direção ao foco F2 incide no ramo direito da hipérbole no ponto P e é refletido ao longo da reta suporte que passa pelo foco F1.]', 'A figura abaixo ilustra a propriedade refletora da hipérbole. Se um raio partir de um ponto A e seguir em direção a F2, então ele é refletido pela hipérbole, no ponto P, e segue em direção a F1.
Considere a hipérbole 4x² - 5y² = 20 de focos F1 e F2 com F1 à esquerda de F2. Qual das retas abaixo dá a direção do raio que deve partir do ponto A(1, 3) para ser refletido no ramo da direita da hipérbole e caminhar em direção a F1?', '[{"letra": "A", "texto": "3x + 2y - 9 = 0"}, {"letra": "B", "texto": "2x + 2y - 7 = 0"}, {"letra": "C", "texto": "x + 2y - 8 = 0"}, {"letra": "D", "texto": "2x - y + 7 = 0"}, {"letra": "E", "texto": "x - 2y + 8 = 0"}]', 'A', 'Reduzindo a equação da hipérbole 4x² - 5y² = 20 dividindo por 20: x²/5 - y²/4 = 1.
Daqui, a² = 5 e b² = 4. Como c² = a² + b² = 9 ⇒ c = 3. Os focos são F1(-3, 0) e F2(3, 0).
Pela propriedade refletora, o raio que atinge o ponto P em direção ao foco oposto possui reta suporte passando por A(1, 3) e F2(3, 0).
O coeficiente angular m = (0 - 3) / (3 - 1) = -3/2.
A equação geral da reta é: y - 0 = -3/2 (x - 3) ⇒ 2y = -3x + 9 ⇒ 3x + 2y - 9 = 0.', 'A figura ilustra a propriedade refletora da hipérbole. Um raio incidente originado de um ponto A em direção ao foco F2 incide no ramo direito da hipérbole no ponto P e é refletido ao longo da reta suporte que passa pelo foco F1.', '[{"titulo": "Fazendo a conta", "conteudo": "Reduzindo a equação da hipérbole 4x² - 5y² = 20 dividindo por 20: x²/5 - y²/4 = 1.\nDaqui, a² = 5 e b² = 4.", "formula": null}, {"titulo": "O que o enunciado dá", "conteudo": "Como c² = a² + b² = 9 ⇒ c = 3. Os focos são F1(-3, 0) e F2(3, 0).", "formula": null}, {"titulo": "Conclusão", "conteudo": "Pela propriedade refletora, o raio que atinge o ponto P em direção ao foco oposto possui reta suporte passando por A(1, 3) e F2(3, 0).\nO coeficiente angular m = (0 - 3) / (3 - 1) = -3/2.\nA equação geral da reta é: y - 0 = -3/2 (x - 3) ⇒ 2y = -3x + 9 ⇒ 3x + 2y - 9 = 0.", "formula": null}]', 'automatica', TRUE, FALSE, 'af384efb6394fabf2df67c8739f46ac0ee9e9ec7dc85a1882ca66f0d7b10a388', 'esa-2024-geral.txt'),
('ESA', 'Português', 'Interpretação de Texto e Estilística', 2024, 'Prova única', 'Exército Brasileiro (Comissão Própria)', 15, '15', NULL, 'medio', 'TEXTO I
Canção do Expedicionário

Você sabe de onde eu venho?
Venho do morro, do engenho
Das selvas, dos cafezais
Da boa terra do coco
Da choupana onde um é pouco
Dois é bom, três é demais...
(DE ALMEIDA, G.; ROSSI, S. Canção do Expedicionário, 1944)', 'Observando a Canção do Expedicionário (Texto I), identifique a alternativa incorreta:', '[{"letra": "A", "texto": "Retrata um sentimento saudosista em relação à Pátria."}, {"letra": "B", "texto": "Identifica-se o uso da antítese recorrentemente."}, {"letra": "C", "texto": "Existe uma regularidade na rima."}, {"letra": "D", "texto": "É uma obra intertextual."}, {"letra": "E", "texto": "Possui regularidade sintática dos termos."}]', 'E', 'O poema apresenta constante hipérbato (inversão da ordem direta) e anacolutos intencionais para criar ritmo poético. Portanto, é incorreto afirmar que possui "regularidade sintática dos termos".', NULL, '[{"titulo": "Passo 1", "conteudo": "O poema apresenta constante hipérbato (inversão da ordem direta) e anacolutos intencionais para criar ritmo poético.", "formula": null}, {"titulo": "Conclusão", "conteudo": "Portanto, é incorreto afirmar que possui \"regularidade sintática dos termos\".", "formula": null}]', 'automatica', FALSE, FALSE, '4dcdb7dd85e25c51b2c7f73d028b74c54466a59bfb6eef6dd193e0fb9674a435', 'esa-2024-geral.txt'),
('ESA', 'Português', 'Sintaxe da Oração (Análise Morfossintática)', 2024, 'Prova única', 'Exército Brasileiro (Comissão Própria)', 16, '16', NULL, 'medio', 'Observe o trecho abaixo extraído do Texto I:
"Venho do além desse monte"', 'Assinale a alternativa que faz a análise morfossintática correta do trecho:', '[{"letra": "A", "texto": "O sujeito da oração é indeterminado."}, {"letra": "B", "texto": "\"Venho do além desse monte\" é predicado verbal."}, {"letra": "C", "texto": "\"além desse monte\" é adjunto adverbial."}, {"letra": "D", "texto": "\"do além\" é núcleo do adjunto adverbial."}, {"letra": "E", "texto": "\"desse\" é complemento nominal do adjunto adverbial."}]', 'B', 'O verbo "Venho" é intransitivo, e todo o segmento "Venho do além desse monte" constitui a informação declarada sobre o sujeito oculto "Eu", classificando-se como predicado verbal.', NULL, NULL, 'resumida', FALSE, FALSE, '5eb386c0e26eed424fe7ad1f709ba7c454305e39c885825e683be2083bf870f0', 'esa-2024-geral.txt'),
('ESA', 'Português', 'Tipologia Textual e Argumentação', 2024, 'Prova única', 'Exército Brasileiro (Comissão Própria)', 17, '17', NULL, 'facil', '[DESCRIÇÃO DA IMAGEM: Tirinha do personagem Calvin conversando com seu pai.
Quadro 1: Calvin segura uma prancheta e diz: "Bem, pai, sua cotação está muito alta esta semana." O pai responde: "Fico feliz em saber disso."
Quadro 2: Calvin diz: "E os entrevistados acham que você está fazendo um bom trabalho como pai. Na verdade, com um empurrãozinho, sua popularidade pode bater um recorde hoje."
Quadro 3: O pai retruca: "Boa tentativa. Vá ajudar sua mãe com a louça." Calvin desapontado exclama: "Ai, pai!".]', 'Tendo em vista o contexto geral da tirinha e o humor provocado, após uma leitura atenta de algumas expressões utilizadas, como "saber disso", "acham que" e "boa tentativa", depreende-se que o tipo textual predominante na construção persuasiva do discurso é:', '[{"letra": "A", "texto": "Informativo."}, {"letra": "B", "texto": "Publicitário."}, {"letra": "C", "texto": "Argumentativo."}, {"letra": "D", "texto": "Expositivo."}, {"letra": "E", "texto": "Descritivo."}]', 'C', 'O personagem Calvin utiliza estratégias de convencimento e exposição de dados (a suposta pesquisa de cotação) para persuadir o pai a realizar sua vontade, configurando o tipo textual argumentativo.', 'Tirinha do personagem Calvin conversando com seu pai.', NULL, 'resumida', FALSE, FALSE, '84aadf739fdee55993ac937e6c86d53d2b3350c9cff499615c0e0b930fb1827a', 'esa-2024-geral.txt'),
('ESA', 'Português', 'Compreensão e Interpretação de Texto', 2024, 'Prova única', 'Exército Brasileiro (Comissão Própria)', 18, '18', NULL, 'facil', 'TEXTO II
SARGENTO DO EXÉRCITO BRASILEIRO: RESPONSABILIDADES E DESAFIOS
Parte integrante e fundamental da estrutura organizacional da Força Terrestre, sobre o sargento recai grande responsabilidade pela manutenção da solidez do Exército Brasileiro. A ele, cabe a missão de servir como "referência imediata" para cabos e soldados e para Sargentos mais jovens e recém-egressos das Escolas. Essa referência se concretiza pelos exemplos de profissionalismo e correção de atitudes demonstrados no dia a dia dos quartéis, desde o cumprimento das ordens dos superiores até a atuação pautada na disciplina consciente...', 'Fundamentado no Texto II: "Sargento do Exército Brasileiro: responsabilidades e desafios", é incorreto afirmar que:', '[{"letra": "A", "texto": "Ao atribuir maiores responsabilidades ao sargento, a instituição é fortalecida."}, {"letra": "B", "texto": "Sobre o sargento, incide o dever de resguardar a solidez da instituição à qual ele pertence."}, {"letra": "C", "texto": "O pleno entendimento dos níveis de comando e organização do Exército é uma atitude essencial."}, {"letra": "D", "texto": "O sargento deve conhecer suas atribuições e, com isso, contribuir para que as bases de comando e trabalho funcionem de maneira adequada."}, {"letra": "E", "texto": "O sargento deve exigir profissionalismo e correção das atitudes de seus subordinados por meio do cumprimento de suas ordens."}]', 'E', 'O texto II explicita que o papel do sargento é ser uma referência pelo exemplo profissional e pela disciplina consciente, e não puramente pelo exercício autoritário da imposição de ordens.', NULL, NULL, 'resumida', FALSE, FALSE, 'f277f4c6f74e250518596443651db7f8992c3c6f6d1861d86e2a627bfc83ad00', 'esa-2024-geral.txt'),
('ESA', 'Português', 'Sintaxe do Período Composto (Completiva Nominal)', 2024, 'Prova única', 'Exército Brasileiro (Comissão Própria)', 19, '19', NULL, 'facil', 'Observe o período contido no Texto II: "Deve comunicar-se eficazmente e estar sempre pronto para corrigir com sereno rigor [...]."', 'A oração em destaque ["para corrigir com sereno rigor"] é classificada como:', '[{"letra": "A", "texto": "Oração subordinada adverbial final reduzida de infinitivo."}, {"letra": "B", "texto": "Oração subordinada adverbial condicional reduzida de infinitivo."}, {"letra": "C", "texto": "Oração subordinada adjetiva restritiva reduzida de infinitivo."}, {"letra": "D", "texto": "Oração subordinada substantiva completiva nominal reduzida de infinitivo."}, {"letra": "E", "texto": "Oração subordinada substantiva objetiva indireta reduzida de infinitivo."}]', 'D', 'A oração "para corrigir com sereno rigor" completa o sentido do adjetivo "pronto" ("pronto para algo"), exercendo função sintática de complemento nominal, sob a forma reduzida de infinitivo.', NULL, NULL, 'resumida', TRUE, FALSE, '649c825fd04940336f022403bad1721694e92749db89706c2f35f8d5d659a734', 'esa-2024-geral.txt'),
('ESA', 'Português', 'Pontuação e Elipse Verbal', 2024, 'Prova única', 'Exército Brasileiro (Comissão Própria)', 20, '20', NULL, 'facil', 'TEXTO III... Não há morte. O encontro de duas expansões, ou a expansão de duas formas, pode determinar a supressão de uma delas; mas, rigorosamente, não há morte, há vida, porque a supressão de uma é a condição da sobrevivência da outra... Ao vencido, ódio ou compaixão; ao vencedor, as batatas.
(DE ASSIS, M. Quincas Borba. Rio de Janeiro: Civilização Brasileira/INL, 1976. Fragmento)', 'Assinale, dentre as alternativas abaixo e de acordo com o Texto III, aquela em que o uso da vírgula marca a supressão de um termo, configurado como elipse verbal:', '[{"letra": "A", "texto": "\"Ao vencido, ódio ou compaixão; ao vencedor, as batatas.\""}, {"letra": "B", "texto": "\"A paz, nesse caso, é a destruição (...)\""}, {"letra": "C", "texto": "\"Daí a alegria da vitória, os hinos, as aclamações, recompensas públicas e todos os demais efeitos das ações bélicas.\""}, {"letra": "D", "texto": "\"(...) mas, rigorosamente, não há morte (...)\""}, {"letra": "E", "texto": "\"Se a guerra não fosse isso, tais demonstrações não chegariam a dar-se (...)\""}]', 'A', 'Em "ao vencedor, as batatas", a vírgula assinala a omissão (elipse/zeugma) do verbo oculto "cabe" ou "dar-se-á" ("ao vencedor pertencem as batatas").', NULL, NULL, 'resumida', FALSE, FALSE, '713df9dc6f1816823195e14b3bf6769c542ebd55c189e9c2602ae4fc3186f2ab', 'esa-2024-geral.txt'),
('ESA', 'Português', 'Literatura Brasileira (Realismo / Machado de Assis)', 2024, 'Prova única', 'Exército Brasileiro (Comissão Própria)', 21, '21', NULL, 'facil', NULL, 'A obra machadiana, representada por seus romances e contos, possui duas fases e o livro "Quincas Borba" se encontra na fase da maturidade de Machado, a qual se estabelece, essencialmente, por possuir um teor problematizador, levantando indagações sobre a existência humana, que acaba por ampliar os limites criativos da própria literatura. Nesse contexto, a partir de discussões de vários críticos literários, é muito limitador estabelecer uma Escola Literária única para o autor em questão, contudo, tendo em vista os fatores históricos e características pontuais como as mencionadas, deve-se depreender que a obra é:', '[{"letra": "A", "texto": "Modernista, pois já se denota pela sobriedade dos romances, uma linha de pensamento humanística e atual, própria desta fase, a qual tem por base sempre uma crítica social."}, {"letra": "B", "texto": "Realista, porque ainda que, em Quincas Borba, por exemplo, se trabalhe a loucura, há princípios objetivos e científicos, até mesmo filosóficos como marca de grande parte das obras machadianas."}, {"letra": "C", "texto": "Parnasianista, que se configura pelo cuidado com as palavras e, mesmo sendo um texto em prosa, aproxima-se de uma estrutura poética, com rimas e inversões, uma marca de estilo que privilegia a forma."}, {"letra": "D", "texto": "Simbolista, marcada por uma prosa muito similar ao movimento literário que ocorria na França, oriundo de uma nova estética, com a retratação das transformações das grandes cidades e pelo rompimento do ultrarromântico, dos limites morais e alienantes."}, {"letra": "E", "texto": "Pré-modernista, pois, aliado às Vanguardas Europeias, percebe-se uma preocupação com novidades literárias que trouxessem um rompimento estético e temático com o que ocorria na Europa Ocidental."}]', 'B', '"Quincas Borba" é uma das obras máximas da fase realista de Machado de Assis, retratando a análise psicológica, a ironia e os fundamentos filosóficos e objetivos da sociedade da época.', NULL, NULL, 'resumida', FALSE, FALSE, 'e73bfb0945f7be9fa99e6941ab14230d5aacccc22c484ca177bdaefcf1073f0b', 'esa-2024-geral.txt'),
('ESA', 'Português', 'Intertextualidade e Movimentos Literários', 2024, 'Prova única', 'Exército Brasileiro (Comissão Própria)', 22, '22', NULL, 'medio', 'TEXTO IV - Canto de regresso à pátria (Oswald de Andrade)
"Minha terra tem palmares / Onde gorjeia o mar / Os passarinhos daqui / Não cantam como os de lá..."

TEXTO V - Canção do Exílio (Gonçalves Dias)
"Minha terra tem palmeiras, / Onde canta o Sabiá; / As aves, que aqui gorjeiam, / Não gorjeiam como lá..."', 'Com base nas poesias (Texto IV e Texto V), identifique a temática comum central dos dois textos:', '[{"letra": "A", "texto": "Nacionalismo utópico."}, {"letra": "B", "texto": "Inspiração em valores europeus."}, {"letra": "C", "texto": "Ufanismo nacionalista."}, {"letra": "D", "texto": "Exploração crítica nacional."}, {"letra": "E", "texto": "Todas as alternativas anteriores estão incorretas."}]', 'E', 'Enquanto o Texto V (Gonçalves Dias) representa o ufanismo ingênuo romântico, o Texto IV (Oswald de Andrade) ironiza a tradição com uma paródia modernista. Nenhuma das opções anteriores sintetiza corretamente e de forma unificada ambos os textos.', NULL, NULL, 'resumida', FALSE, FALSE, '4823dacd22768f1cac93287442c1bb9b5da310f744f88c21aa54125017668b52', 'esa-2024-geral.txt'),
('ESA', 'Português', 'Literatura Brasileira (Arcadismo / Epopeia)', 2024, 'Prova única', 'Exército Brasileiro (Comissão Própria)', 23, '23', NULL, 'facil', 'TEXTO VI
Caramuru: poema épico (Canto I)
De um varão em mil casos agitado, / que as praias discorrendo do Ocidente, / descobriu o Recôncavo afamado / da capital brasílica potente...
(DE SANTA RITA DURÃO, J.)', 'Tendo em vista o poema Caramuru (Texto VI), identifique a Escola Literária à qual a obra pertence:', '[{"letra": "A", "texto": "Arcadismo."}, {"letra": "B", "texto": "Simbolismo."}, {"letra": "C", "texto": "Barroco."}, {"letra": "D", "texto": "Realismo."}, {"letra": "E", "texto": "Parnasianismo."}]', 'A', '"Caramuru" (1781), escrito por Frei José de Santa Rita Durão, é um dos mais representativos poemas épicos do Arcadismo (Neoclassicismo) brasileiro.', NULL, NULL, 'resumida', FALSE, FALSE, '077de21d024454a92d7214df2b3f9771b46d38b0a2d149e8ab114120f00fb787', 'esa-2024-geral.txt'),
('ESA', 'Português', 'Morfologia (Processos de Formação de Palavras)', 2024, 'Prova única', 'Exército Brasileiro (Comissão Própria)', 24, '24', NULL, 'facil', '[DESCRIÇÃO DA IMAGEM: Tirinha da série Recruta Zero. No primeiro quadro, o Sargento Tainha pergunta: "Você fez o que eu pedi pra você fazer, Zero?". Zero responde com ênfase: "PROFUNDAMENTE, COMPLETAMENTE E RAPIDAMENTE... COM GOSTO E VONTADE! SEM DEMORA! COM DETERMINAÇÃO!". No segundo quadro, Tainha indaga: "E você se lembrou de trazer meu café?". Zero responde: "VOLTO JÁ".]', 'Sobre a palavra "completamente", presente no segundo balão da tira, é correto afirmar que:', '[{"letra": "A", "texto": "Possui um sufixo adverbial."}, {"letra": "B", "texto": "É composta por dois afixos."}, {"letra": "C", "texto": "Possui um prefixo de origem grega."}, {"letra": "D", "texto": "Apresenta uma derivação parassintética."}, {"letra": "E", "texto": "Foi formada por meio da derivação prefixal."}]', 'A', 'A palavra "completamente" é formada pelo acréscimo do sufixo adverbial "-mente" ao adjetivo "completa" (derivação sufixal).', 'Tirinha da série Recruta Zero. No primeiro quadro, o Sargento Tainha pergunta: "Você fez o que eu pedi pra você fazer, Zero?". Zero responde com ênfase: "PROFUNDAMENTE, COMPLETAMENTE E RAPIDAMENTE... COM GOSTO E VONTADE! SEM DEMORA! COM DETERMINAÇÃO!". No segundo quadro, Tainha indaga: "E você se lembrou de trazer meu café?". Zero responde: "VOLTO JÁ".', NULL, 'resumida', FALSE, FALSE, 'ecbc98d179ed2a6db1c43b9062b142f3dd2b03be511a9d710b21fa8c43881882', 'esa-2024-geral.txt'),
('ESA', 'Português', 'Sintaxe dos Pronomes Oblíquos (Objeto Direto)', 2024, 'Prova única', 'Exército Brasileiro (Comissão Própria)', 25, '25', NULL, 'facil', '[DESCRIÇÃO DA IMAGEM: Tirinha do Recruta Zero. Sargento Tainha traz seu cão Otto para a sala e diz: "Vamos, Otto, ler nossas revistas." O recruta ao lado pergunta: "Como o Otto pode ajudá-lo a ler revistas?". No quadro seguinte, o sargento explica: "Ele lambe o meu polegar para eu virar as páginas."]', 'Qual a função sintática do termo em destaque no período: "Como o Otto pode ajudá-lo a ler revistas?"? [termo destacado: "-lo"]', '[{"letra": "A", "texto": "Pronome oblíquo."}, {"letra": "B", "texto": "Objeto indireto."}, {"letra": "C", "texto": "Objeto direto."}, {"letra": "D", "texto": "Agente da passiva."}, {"letra": "E", "texto": "Substantivo."}]', 'C', 'O verbo "ajudar" é transitivo direto no contexto ("ajudar alguém"). O pronome oblíquo "-lo" desempenha a função sintática de Objeto Direto.', 'Tirinha do Recruta Zero. Sargento Tainha traz seu cão Otto para a sala e diz: "Vamos, Otto, ler nossas revistas." O recruta ao lado pergunta: "Como o Otto pode ajudá-lo a ler revistas?". No quadro seguinte, o sargento explica: "Ele lambe o meu polegar para eu virar as páginas."', NULL, 'resumida', TRUE, FALSE, 'b5fce96370809e672c3d9718055a6bd6a17ea25120c2148b0c69e3848ce46c3e', 'esa-2024-geral.txt'),
('ESA', 'Português', 'Morfologia (Classes de Palavras / Pronome Reflexivo)', 2024, 'Prova única', 'Exército Brasileiro (Comissão Própria)', 26, '26', NULL, 'facil', 'TEXTO VII... Não é que fôssemos amigos de longa data. Conhecemo-nos apenas no último ano da escola... Experimentávamos ficar calados, mas tornávamo-nos inquietos logo depois de nos separarmos.
(LISPECTOR, C. Uma amizade sincera. Fragmento)

Observe o trecho a seguir:
"mas tornávamo-nos inquietos logo depois de nos separarmos."', 'Indique a alternativa que corresponde à classe morfológica do primeiro "nos" no trecho acima:', '[{"letra": "A", "texto": "Pronome apassivador."}, {"letra": "B", "texto": "Pronome pessoal do caso reto."}, {"letra": "C", "texto": "Pronome reflexivo."}, {"letra": "D", "texto": "Objeto direto."}, {"letra": "E", "texto": "Sujeito."}]', 'C', 'No verbo pronominal "tornar-se" ("tornávamo-nos"), o pronome "nos" acompanha a flexão verbal referente à 1ª pessoa do plural, sendo classificado morfologicamente como pronome reflexivo/pronominal.', NULL, NULL, 'resumida', FALSE, FALSE, 'e9da7e95dfffa7bf13f0fff619995f23c5d125ad068c4a1661c9b517bccd491d', 'esa-2024-geral.txt'),
('ESA', 'Português', 'Teoria Literária (Métrica e Versificação)', 2024, 'Prova única', 'Exército Brasileiro (Comissão Própria)', 27, '27', NULL, 'medio', 'TEXTO VIII
Soneto de Fidelidade
De tudo, ao meu amor serei atento / Antes, e com tal zelo, e sempre, e tanto / Que mesmo em face do maior encanto / Dele se encante mais meu pensamento...
(DE MORAES, V. Soneto de Fidelidade, 1939)', 'A partir do Soneto de Fidelidade (Texto VIII) e das declarações destacadas na enumeração a seguir, assinale a alternativa que melhor justifica a sua versificação:
I- É um poema escrito em redondilha maior, com versos de sete sílabas, chamados de heptassílabos.
II- É um poema com versos decassílabos ou alexandrinos, agrupados em duas quadras e em dois tercetos.
III- Os versos são compostos por três rimas, "ento", "ure" e "ama".
IV- Os versos possuem tercetos não tradicionais aos que se estudam em sonetos italianos.', '[{"letra": "A", "texto": "Apenas a I está correta."}, {"letra": "B", "texto": "As opções I, II e III estão erradas."}, {"letra": "C", "texto": "As opções II e IV estão corretas."}, {"letra": "D", "texto": "As opções II, III e IV estão corretas."}, {"letra": "E", "texto": "Todas as declarações estão erradas."}]', 'B', 'O "Soneto de Fidelidade" é estruturado rigorosamente em versos decassílabos eruditos (com rimas ricas e interpoladas), tornando incorretas as afirmativas I, II e III no rigor de suas definições categóricas.', NULL, NULL, 'resumida', FALSE, FALSE, '1d7cd06b154e7311472e56ad84a977e7d15f135b28c452da66f89505c1885efe', 'esa-2024-geral.txt'),
('ESA', 'Português', 'Gêneros Literários (Lírico e Formas Fixas)', 2024, 'Prova única', 'Exército Brasileiro (Comissão Própria)', 28, '28', NULL, 'medio', NULL, 'Tendo em vista o Soneto de Fidelidade (Texto VIII) e os estudos clássicos sobre Gêneros Literários, identifique qual alternativa possui uma análise plenamente correta:', '[{"letra": "A", "texto": "Ele é um soneto com rimas e métricas irregulares, o que é previsto no gênero narrativo, pois rompe com o clássico."}, {"letra": "B", "texto": "Por se tratar de um gênero lírico, entende-se o Soneto de Fidelidade como um poema prototípico dos Sonetos estudados neste gênero."}, {"letra": "C", "texto": "Ele é característico do gênero dramático, pois um soneto foi escrito para ser cantado e interpretado."}, {"letra": "D", "texto": "É um texto com uma estrutura fixa clássica, pertence ao gênero lírico, ainda que haja uma inovação em seu arranjo, pois as rimas dos tercetos comportam-se de forma mista."}, {"letra": "E", "texto": "O poema se caracteriza por ser de gênero épico, já que possui a estrutura mais antiga de poesia, chamada de Soneto."}]', 'D', 'O soneto pertence ao gênero lírico (expressão da subjetividade e do eu-lírico) e possui estrutura fixa clássica, apresentando inovação no encadeamento e combinação mista das rimas dos tercetos.', NULL, NULL, 'resumida', FALSE, FALSE, 'bdd0c2f50eb918f2f95637d604d51da48bfec0edf3bcac4fc6ee73598acaf08b', 'esa-2024-geral.txt'),
('ESA', 'História', 'História do Brasil (Era Vargas)', 2024, 'Prova única', 'Exército Brasileiro (Comissão Própria)', 29, '29', NULL, 'medio', NULL, 'A Era Vargas foi um período de 15 anos em que o país teve apenas um governante, Getúlio Vargas. A alternativa correta que apresenta uma sequência cronológica de acontecimentos na Era Vargas é:', '[{"letra": "A", "texto": "A criação do Conselho Nacional do Café; a Revolução Constitucionalista; a extinção da Aliança Nacional Libertadora; a Intentona Comunista; a instauração do Estado Novo; e a participação do Brasil na 2ª Guerra Mundial."}, {"letra": "B", "texto": "A Revolução Constitucionalista; a criação do Conselho Nacional do Café; a Intentona Comunista; a extinção da Aliança Nacional Libertadora; a instauração do Estado Novo; e a participação do Brasil na 2ª Guerra Mundial."}, {"letra": "C", "texto": "A Revolução Constitucionalista; a criação do Conselho Nacional do Café; a extinção da Aliança Nacional Libertadora; a Intentona Comunista; a participação do Brasil na 2ª Guerra Mundial; e a instauração do Estado Novo."}, {"letra": "D", "texto": "A criação do Conselho Nacional do Café; a extinção da Aliança Nacional Libertadora; a Revolução Constitucionalista; a Intentona Comunista; a participação do Brasil na 2ª Guerra Mundial; e a instauração do Estado Novo."}, {"letra": "E", "texto": "A Revolução Constitucionalista; a extinção da Aliança Nacional Libertadora; a Intentona Comunista; a instauração do Estado Novo; criação do Conselho Nacional do Café; e a participação do Brasil na 2ª Guerra Mundial."}]', 'A', 'A sequência cronológica correta dos fatos marcantes da Era Vargas é:
1. Criação do Conselho Nacional do Café (1931);
2. Revolução Constitucionalista de São Paulo (1932);
3. Extinção da Aliança Nacional Libertadora - ANL (julho de 1935);
4. Intentona Comunista (novembro de 1935);
5. Instauração do Estado Novo (1937);
6. Envio das tropas à 2ª Guerra Mundial (1942-1945).', NULL, '[{"titulo": "Passo 1", "conteudo": "A sequência cronológica correta dos fatos marcantes da Era Vargas é:\n1. Criação do Conselho Nacional do Café (1931);\n2.", "formula": null}, {"titulo": "Passo 2", "conteudo": "Revolução Constitucionalista de São Paulo (1932);\n3. Extinção da Aliança Nacional Libertadora - ANL (julho de 1935);\n4.", "formula": null}, {"titulo": "Passo 3", "conteudo": "Intentona Comunista (novembro de 1935);\n5. Instauração do Estado Novo (1937);\n6.", "formula": null}, {"titulo": "Conclusão", "conteudo": "Envio das tropas à 2ª Guerra Mundial (1942-1945).", "formula": null}]', 'automatica', FALSE, FALSE, 'fea6e7913e1a4950d2e0f22717c542f04f699b6306e009fab7d8892aa3f7f18d', 'esa-2024-geral.txt'),
('ESA', 'História', 'História do Brasil (Guerra dos Mascates)', 2024, 'Prova única', 'Exército Brasileiro (Comissão Própria)', 30, '30', NULL, 'facil', NULL, 'A Guerra dos Mascates foi um conflito que eclodiu no Nordeste brasileiro, no ano de 1710, no contexto da crise da economia açucareira provocada pela concorrência com a produção dos holandeses nas Antilhas. Sobre esse conflito, é correto afirmar que:', '[{"letra": "A", "texto": "Os comerciantes de Recife estavam endividados com os senhores de engenho de Olinda, que exigiam pagamento imediato."}, {"letra": "B", "texto": "\"Mascate\" era o nome dado aos holandeses, que governavam a cidade do Recife naquela época."}, {"letra": "C", "texto": "Ocorreu devido a hostilidades entre os comerciantes recifenses (mascates) e os senhores de engenho de Olinda."}, {"letra": "D", "texto": "Os recifenses reivindicaram junto ao Rei Dom João V que seu povoado fosse elevado à categoria de vila, pedido esse que foi negado pelo monarca."}, {"letra": "E", "texto": "A Coroa Portuguesa não interveio no conflito, que foi encerrado com um acordo de paz entre os revoltosos, no ano de 1711."}]', 'C', 'A Guerra dos Mascates (1710-1711) decorreu das rivalidades políticas e econômicas entre os senhores de engenho de Olinda (decadentes e endividados) e os comerciantes portugueses de Recife (chamados mascates), que buscavam autonomia política para Recife.', NULL, NULL, 'resumida', FALSE, FALSE, '5f320e476d26cb5c19be79562613228b706e55286c3cbbcfe1721033ba02ad38', 'esa-2024-geral.txt'),
('ESA', 'História', 'História do Brasil (Expansão Territorial e Colonização)', 2024, 'Prova única', 'Exército Brasileiro (Comissão Própria)', 31, '31', NULL, 'facil', '[DESCRIÇÃO DA IMAGEM: Dois mapas do Brasil comparando a expansão territorial e urbanização entre os séculos XVII e XVIII. Mostram a concentração inicial no litoral no século XVII e o posterior avanço para o interior no século XVIII.]', 'Durante o primeiro século de colonização portuguesa, o território brasileiro era povoado majoritariamente ao longo de sua faixa litorânea, desde Natal até Cananeia. Foi só a partir do Século XVII que se iniciou um processo de interiorização territorial da colônia, conforme podemos observar nas imagens abaixo. Podemos enumerar como causas que levaram os colonizadores a avançar em direção ao interior, exceto:', '[{"letra": "A", "texto": "O avanço da pecuária, uma vez que cada vez mais os rebanhos ocupavam áreas interioranas."}, {"letra": "B", "texto": "As expedições militares financiadas pela Coroa para expulsar possíveis invasores estrangeiros."}, {"letra": "C", "texto": "A busca por novas áreas para o plantio de cana-de-açúcar, já que o solo das regiões litorâneas tinha se mostrado muito improdutivo."}, {"letra": "D", "texto": "A ação dos jesuítas, que fundavam novos aldeamentos para explorar as riquezas naturais e catequizar os indígenas."}, {"letra": "E", "texto": "A ação dos bandeirantes, que avançavam para Oeste à procura de metais preciosos ou à caça de indígenas ou de escravos africanos fugidos."}]', 'C', 'O solo litorâneo nordestino (massapê) era extremamente fértil e produtivo. A interiorização do povoamento deu-se pela pecuária, bandeirantismo e missões jesuíticas, e não por improdutividade do solo praiano.', 'Dois mapas do Brasil comparando a expansão territorial e urbanização entre os séculos XVII e XVIII. Mostram a concentração inicial no litoral no século XVII e o posterior avanço para o interior no século XVIII.', NULL, 'resumida', FALSE, FALSE, '79410cd8fa3189beb488509c732a6b5f7071e1d8316147dcdf33db280e9a6017', 'esa-2024-geral.txt'),
('ESA', 'História', 'História do Brasil (Revolução Pernambucana de 1817)', 2024, 'Prova única', 'Exército Brasileiro (Comissão Própria)', 32, '32', NULL, 'facil', NULL, 'A Revolução Pernambucana foi a única rebelião de caráter emancipacionista e republicano, durante o governo de D. João, que ultrapassou a fase da mera conspiração. Marque a alternativa que possui apenas causas da eclosão da Revolução Pernambucana:
I. O apoio incondicional dos Pernambucanos ao governo do Príncipe D. João.
II. A fome no nordeste provocada pela seca de 1816.
III. A concorrência do algodão produzido pelos Norte-Americanos e do açúcar produzido nas Antilhas, que baixavam os preços desses produtos no mercado internacional.
IV. As ideias Monarquistas inspiradas na Revolução Francesa.
V. O crescente aumento dos impostos, após a chegada da corte portuguesa ao Brasil.', '[{"letra": "A", "texto": "I e V."}, {"letra": "B", "texto": "II, III e V."}, {"letra": "C", "texto": "III e IV."}, {"letra": "D", "texto": "IV e V."}, {"letra": "E", "texto": "I, II e IV."}]', 'B', 'A Revolução Pernambucana de 1817 foi motivada pela severa seca de 1816 (item II), pela crise das exportações de açúcar e algodão (item III) e pelo aumento contínuo de impostos promovido pela Corte no Rio de Janeiro (item V).', NULL, NULL, 'resumida', FALSE, FALSE, '515ebae959c8760abea7e66aadc5a8d88c49106e1155bb565c1eaeab3f90d517', 'esa-2024-geral.txt'),
('ESA', 'História', 'História do Brasil (Revoltas do Período Regencial)', 2024, 'Prova única', 'Exército Brasileiro (Comissão Própria)', 33, '33', NULL, 'facil', NULL, 'Com a abdicação de D. Pedro I, em 1831, em favor de seu filho Pedro de Alcântara, de apenas 5 anos de idade, o Brasil passou a ser governado por uma Regência composta por 3 membros, até que o menino alcançasse a maioridade. Em 1834, a constituição imperial foi alterada com a promulgação do Ato Adicional, que, entre outras questões, estabelecia a Regência exercida por uma pessoa, com mandato de 4 anos. Esse período foi extremamente conturbado com a eclosão de diversas revoltas nas províncias brasileiras. Marque a alternativa que apresenta revoltas iniciadas no Período Regencial:', '[{"letra": "A", "texto": "Revolução Farroupilha, Revolta dos Malês e Cabanagem."}, {"letra": "B", "texto": "Revolução Liberal, Confederação do Equador e Sabinada."}, {"letra": "C", "texto": "Balaiada, Cabanagem e Revolução Liberal."}, {"letra": "D", "texto": "Sabinada, Balaiada e Conjuração Baiana."}, {"letra": "E", "texto": "Cabanagem, Guerra dos Farrapos e Inconfidência Mineira."}]', 'A', 'As principais revoltas eclodidas durante o Período Regencial (1831-1840) foram a Revolução Farroupilha (RS, 1835), a Revolta dos Malês (BA, 1835) e a Cabanagem (PA, 1835).', NULL, NULL, 'resumida', FALSE, FALSE, '409c380cee7e088177b38bbbb6adbb6de9e8b9f4efed95674d919be4ea42faeb', 'esa-2024-geral.txt'),
('ESA', 'História', 'História do Brasil (Governo FHC e Privatizações)', 2024, 'Prova única', 'Exército Brasileiro (Comissão Própria)', 34, '34', NULL, 'facil', NULL, 'O Governo Fernando Henrique Cardoso (FHC) foi caracterizado por vários economistas como um governo neoliberal. Uma das condutas do governo que mais contribuiu para essa caracterização foi a privatização de empresas estatais. Um exemplo de empresa estatal privatizada do governo FHC foi:', '[{"letra": "A", "texto": "Petrobrás."}, {"letra": "B", "texto": "Eletrobrás."}, {"letra": "C", "texto": "Telebrás."}, {"letra": "D", "texto": "Empresa Brasileira de Correios e Telégrafos (ECT)."}, {"letra": "E", "texto": "Banco do Rio Grande do Sul (BANRISUL)."}]', 'C', 'A privatização do sistema Telebrás, ocorrida em julho de 1998, foi o maior marco do programa de desestatizações e reformas neoliberais do Governo FHC.', NULL, NULL, 'resumida', FALSE, FALSE, 'cc6685eea1c14933e68e687b7e4184d5f51a346b787d7bad9d9e471a5dc894cb', 'esa-2024-geral.txt'),
('ESA', 'História', 'Geografia do Brasil (Complexos Geoeconômicos)', 2024, 'Prova única', 'Exército Brasileiro (Comissão Própria)', 35, '35', NULL, 'medio', NULL, 'Em 1967 o geógrafo Pedro Pinchas Geiger elaborou o conceito de "Complexos Regionais", uma classificação em que distribui o Brasil em três regiões geoeconômicas. São elas: a Amazônia, o Nordeste e o Centro-Sul.
Sobre o assunto, analise os aspectos que caracterizam essas regiões:
I. O complexo do Nordeste expressa a integração econômica do Sudeste industrial e financeiro com o Sul agrícola e industrial.
II. O norte semiárido de Minas Gerais, marcado pelo predomínio da pequena agricultura e pela pobreza, integra o complexo do Nordeste.
III. O oeste do Maranhão, úmido e fortemente ligado à extração mineral do Pará, integra o complexo Centro-Sul.
IV. O complexo da Amazônia expressa a existência de uma fronteira de expansão de economia nacional, que é tanto uma fronteira demográfica como uma fronteira de recursos.

Está correto o contido em:', '[{"letra": "A", "texto": "II e IV, apenas."}, {"letra": "B", "texto": "II e III, apenas."}, {"letra": "C", "texto": "I, II e IV, apenas."}, {"letra": "D", "texto": "I, II, III e IV."}, {"letra": "E", "texto": "I, III e IV, apenas."}]', 'A', 'I - Incorreto (essa integração define o Centro-Sul).
II - Correto (o Norte de Minas integra o complexo do Nordeste por aspectos socioeconômicos).
III - Incorreto (o oeste maranhense integra o complexo da Amazônia).
IV - Correto (a Amazônia representa a fronteira de expansão econômica e demográfica).', NULL, '[{"titulo": "Passo 1", "conteudo": "I - Incorreto (essa integração define o Centro-Sul). II - Correto (o Norte de Minas integra o complexo do Nordeste por aspectos socioeconômicos).", "formula": null}, {"titulo": "Conclusão", "conteudo": "III - Incorreto (o oeste maranhense integra o complexo da Amazônia). IV - Correto (a Amazônia representa a fronteira de expansão econômica e demográfica).", "formula": null}]', 'automatica', FALSE, FALSE, '6c33810c4bffb66db04604d222d2d82242bc38926cf997a5bc0bd1e600a5dab3', 'esa-2024-geral.txt'),
('ESA', 'História', 'Geografia do Brasil (Classificação Climática do IBGE)', 2024, 'Prova única', 'Exército Brasileiro (Comissão Própria)', 36, '36', NULL, 'medio', '[DESCRIÇÃO DA IMAGEM: Mapa do Brasil indicando a localização das 13 Unidades Escolares Tecnológicas do Exército (UETE) distribuídas pelo país.]', 'No primeiro ano do Curso de Formação e Graduação de Sargentos (CFGS), os alunos são distribuídos entre as 13 (treze) Unidades Escolares Tecnológicas do Exército (UETE), supervisionadas pela ESA, localizadas de norte a sul do território nacional. O aluno, ao se instalar em uma das UETE, estará inserido, conforme a classificação climática do IBGE (base na medição sistemática da temperatura e nos índices pluviométricos em estações meteorológicas), no seguinte clima zonal:', '[{"letra": "A", "texto": "20º RCB (Campo Grande - MS) no clima zonal Equatorial."}, {"letra": "B", "texto": "23º BI (Blumenau - SC) no clima zonal Tropical (sul oriental)."}, {"letra": "C", "texto": "23º BC (Fortaleza - CE) no clima zonal Tropical (zona equatorial)."}, {"letra": "D", "texto": "16º BIMTZ (Natal - RN) no clima zonal Tropical (nordeste ocidental)."}, {"letra": "E", "texto": "41º BIMTZ (Jataí - GO) no clima zonal Temperado."}]', 'C', 'De acordo com a regionalização climática do IBGE, a cidade de Fortaleza (CE), onde se localiza o 23º BC, insere-se no clima Tropical da Zona Equatorial (litoral norte nordestino).', 'Mapa do Brasil indicando a localização das 13 Unidades Escolares Tecnológicas do Exército (UETE) distribuídas pelo país.', NULL, 'resumida', FALSE, FALSE, 'a879934f31ab6068ac82cd463b71fa7e35563cf387a0a36e7102d634709390f4', 'esa-2024-geral.txt'),
('ESA', 'História', 'Geografia do Brasil (Demografia e Bônus Demográfico)', 2024, 'Prova única', 'Exército Brasileiro (Comissão Própria)', 37, '37', NULL, 'facil', NULL, 'A sociedade brasileira vem passando por expressivas mudanças em seu perfil demográfico. Essas alterações na composição etária da população indicam que o país ingressou em um período especial conhecido como bônus demográfico. Sobre o bônus demográfico, é correto afirmar que:', '[{"letra": "A", "texto": "Ocorre quando há predomínio de adultos no conjunto total da população em relação a crianças (0 a 14 anos) e idosos (65 anos ou mais), aumentando o número de pessoas em idade produtiva e diminuindo a quantidade de dependentes, o que favorece o desenvolvimento econômico."}, {"letra": "B", "texto": "É o processo pelo qual as sociedades passam do estágio de altas taxas para o de baixas taxas de natalidade e de mortalidade, isto é, tanto o estágio inicial quanto o final caracterizam-se pela diferença entre as taxas de natalidade e de mortalidade."}, {"letra": "C", "texto": "Corresponde à diferença entre nascimentos (natalidade) e óbitos (mortalidade) verificada na população, somada à diferença entre a entrada e a saída de pessoas no país."}, {"letra": "D", "texto": "Trata-se da redução da população economicamente ativa, ou seja, redução de postos de trabalho em virtude das novas formas de organização da produção, tendência verificada especialmente devido à informatização e à robótica."}, {"letra": "E", "texto": "Refere-se à distribuição da população brasileira por gênero, apresentando uma parcela ligeiramente maior de população feminina. Há um aumento das mortes de adolescentes e adultos jovens do sexo masculino por causas violentas e acidentes automobilísticos."}]', 'A', 'O bônus demográfico refere-se ao momento da transição etária em que a proporção de população em idade ativa (15 a 64 anos) supera o volume de dependentes (crianças e idosos), favorecendo o crescimento econômico do país.', NULL, NULL, 'resumida', TRUE, FALSE, '75d1fce69ae2be9af0940aa56b020e6afc11c36c9e0104eca665392bceae4c77', 'esa-2024-geral.txt'),
('ESA', 'História', 'Geografia do Brasil (Rede Urbana e Cidades Globais)', 2024, 'Prova única', 'Exército Brasileiro (Comissão Própria)', 38, '38', NULL, 'medio', '[DESCRIÇÃO DA IMAGEM: Mapa do Brasil destacando a distribuição geográfica dos 15 Colégios Militares geridos pela Diretoria de Educação Preparatória e Assistencial.]', 'Os Colégios Militares (CM) são Organizações Militares (OM) que funcionam como estabelecimentos de ensino de educação básica, com a finalidade de atender ao Ensino Preparatório e Assistencial. Atualmente existem 15 CM, distribuídos nas cidades conforme o mapa ao lado. Todas as cidades destacadas possuem 1 CM, exceto a cidade do Rio de Janeiro – RJ, que possui 2 CM. Em relação às cidades onde estão localizados os Colégios Militares do Brasil, assinale a alternativa correta:', '[{"letra": "A", "texto": "As cidades onde se localizam os colégios militares de Manaus e Belém configuram-se como uma megalópole que dinamiza processos de valorização imobiliária..."}, {"letra": "B", "texto": "O Colégio Militar de Brasília está localizado numa cidade global do tipo beta, em que está diretamente ligada à noção de poder..."}, {"letra": "C", "texto": "Os colégios militares de Campo Grande, Fortaleza e Recife estão localizados em cidades consideradas metrópoles, cujas influências se estendem por vastas áreas do território nacional..."}, {"letra": "D", "texto": "O Colégio Militar de São Paulo está localizado em uma cidade global, onde a densidade e a qualidade da infraestrutura, a oferta de bens e serviços e, consequentemente, a capacidade de polarização sobre os fluxos regionais e mundiais, é do tipo alfa."}, {"letra": "E", "texto": "Os colégios militares da Região Sul do Brasil estão localizados em cidades de menor porte, com atuação restrita à sua área imediata."}]', 'D', 'São Paulo é classificada como uma Metrópole Global / Cidade Global do tipo Alfa (α), por ser o principal centro financeiro, empresarial e de fluxos informacionais do país.', 'Mapa do Brasil destacando a distribuição geográfica dos 15 Colégios Militares geridos pela Diretoria de Educação Preparatória e Assistencial.', NULL, 'resumida', TRUE, FALSE, '494cdc6f089d606e92f8beb9a0d9b0f8c86cef2c0026715cf06b7af75343a607', 'esa-2024-geral.txt'),
('ESA', 'História', 'Geografia do Brasil (Relevo - Classificação de Ross)', 2024, 'Prova única', 'Exército Brasileiro (Comissão Própria)', 39, '39', NULL, 'medio', NULL, 'Leia a reportagem a seguir:
"Treme Cerrado reúne mais de mil militares no Planalto Central... A Operação #TremeCerrado ocorreu entre 16 e 20 de outubro, no Campo de Instrução de Formosa (GO), localizado, aproximadamente, 100 km a nordeste de Brasília... O Comando Militar do Planalto abrange as áreas do Distrito Federal, Goiás, Triângulo Mineiro e a maior parte do Tocantins."

De acordo com as informações mencionadas na reportagem, a região onde ocorreu a Operação Treme Cerrado está inserida em qual grande compartimento do relevo brasileiro, segundo a classificação de Jurandyr L. S. Ross:', '[{"letra": "A", "texto": "Planaltos e Serras do Atlântico-Leste-Sudeste."}, {"letra": "B", "texto": "Planaltos e Serras de Goiás-Minas."}, {"letra": "C", "texto": "Planaltos e Serras do Tocantins."}, {"letra": "D", "texto": "Planaltos e Tabuleiros Goianos."}, {"letra": "E", "texto": "Planalto e Chapada dos Parecis."}]', 'B', 'Na classificação do relevo de Jurandyr Ross, a porção do Planalto Central correspondente ao Distrito Federal, Goiás e Triângulo Mineiro pertence ao compartimento "Planaltos e Serras de Goiás-Minas".', NULL, NULL, 'resumida', FALSE, FALSE, '3324d828b6cced56171eba062712842cb68663e8699c3951af7fa17b65274305', 'esa-2024-geral.txt'),
('ESA', 'História', 'Geografia do Brasil (Infraestrutura e Transportes)', 2024, 'Prova única', 'Exército Brasileiro (Comissão Própria)', 40, '40', NULL, 'medio', NULL, 'Sobre os portos, hidrovias e ferrovias brasileiras, é correto afirmar que:', '[{"letra": "A", "texto": "A Ferrovia Norte-Sul foi concebida para conectar a Estrada de Ferro Carajás, no Maranhão, com as rodovias e ferrovias da Região Sudeste."}, {"letra": "B", "texto": "A hidrovia Paraná-Tietê interliga o estado do Paraná ao Pampa argentino e tem sido pouco significativa para o transporte de cargas no Brasil."}, {"letra": "C", "texto": "A Estrada de Ferro Carajás foi construída com o propósito principal de escoar a produção mineral ao porto de Belém (PA)."}, {"letra": "D", "texto": "A hidrovia do rio Madeira conecta Rio Branco, no Acre, ao rio Amazonas. É uma alternativa para o escoamento da soja produzida nos cerrados."}, {"letra": "E", "texto": "O porto de Santos (SP) e o porto de Itaguaí (RJ) são os principais portos marítimos do Brasil em valor de cargas de exportação."}]', 'A', 'A Ferrovia Norte-Sul (FNS) foi originalmente concebida no plano nacional de transportes para promover a ligação entre Açailândia/MA (entroncamento da Estrada de Ferro Carajás) e o centro-sul do país.', NULL, NULL, 'resumida', FALSE, FALSE, '2cba321b2a0b7a97cf48c3f9b086a96e08056fc57ba3497d7c2f371794ad82e1', 'esa-2024-geral.txt'),
('ESA', 'Inglês', 'Gramática (Plural dos Substantivos)', 2024, 'Prova única', 'Exército Brasileiro (Comissão Própria)', 41, '41', NULL, 'facil', NULL, 'Fill in the blanks with the appropriate nouns in their correct plural form.

THE MANUFACTURING OF COMBATANTS
With a background of discipline and training, the Non-Commissioned Officer (NCO) Academy shapes its students into ____. The ____ of distinguished past students remind future sergeants of the legacy that they will receive. Marching in synchronized rhythm, they learn to move as a single unit, leaving no fallen ____ behind. They spend hours perfecting fieldcrafts or strategizing like ____ in the wild. Their ____ carry them through long exercises and hikes. At the core, these aspiring warriors desire to protect the innocent ____ of their homeland who depend on their strength and dedication.', '[{"letra": "A", "texto": "heroes - photoes - bodies - wolves - foots - children"}, {"letra": "B", "texto": "heroes - photos - bodys - wolves - feet - childs"}, {"letra": "C", "texto": "heros - photoes - bodies - wolfes - foots - children"}, {"letra": "D", "texto": "heroes - photos - bodies - wolves - feet - childrens"}, {"letra": "E", "texto": "heroes - photos - bodies - wolves - feet - children"}]', 'E', 'Plurais irregulares e regulares aplicados corretamente: hero -> heroes; photo -> photos (exceção à regra -oes); body -> bodies; wolf -> wolves; foot -> feet; child -> children.', NULL, NULL, 'resumida', FALSE, FALSE, 'dfb1d378bc5bce755e6a380dfbfa3a6c18ee0fd3f7e289aad76c7b6d4403345d', 'esa-2024-geral.txt'),
('ESA', 'Inglês', 'Interpretação de Texto e Associação', 2024, 'Prova única', 'Exército Brasileiro (Comissão Própria)', 42, '42', NULL, 'facil', NULL, 'Match the topics with the short texts describing the activities that the Brazilian Army carries out.

TOPICS
1. COMBAT OPERATIONS
2. HUMANITARIAN ASSISTANCE
3. EDUCATION
4. HONOURING SERVICE

TEXTS
A. We conduct commemorative activities and recognise the value of veterans in a way that respects their service including with medallic recognition... ( )
B. We are ready to act decisively at war. To do this, we must use force and protect ourselves in environments where threats cause our nation harm... ( )
C. Our people are highly specialised. We master our profession and know how apply military skills as part of a team... A new soldier''s training starts when they join the Army... ( )
D. Our Army responds quickly to unfolding events. We train to operate in tough conditions... to quickly deploy to disaster sites... ( )', '[{"letra": "A", "texto": "A-2, B-1, C-3, D-4."}, {"letra": "B", "texto": "A-4, B-1, C-3, D-2."}, {"letra": "C", "texto": "A-4, B-2, C-3, D-1."}, {"letra": "D", "texto": "A-3, B-1, C-4, D-2."}, {"letra": "E", "texto": "A-4, B-3, C-1, D-2."}]', 'B', 'Relacionando os conteúdos:
A (Atividades comemorativas e medalhas) = 4. HONOURING SERVICE;
B (Prontidão para combate e uso da força) = 1. COMBAT OPERATIONS;
C (Treinamento e especialização de recrutas/cadetes) = 3. EDUCATION;
D (Resposta rápida a desastres e apoio humanitário) = 2. HUMANITARIAN ASSISTANCE.
Sequência correta: A-4, B-1, C-3, D-2.', NULL, '[{"titulo": "Passo 1", "conteudo": "Relacionando os conteúdos: A (Atividades comemorativas e medalhas) = 4.", "formula": null}, {"titulo": "Passo 2", "conteudo": "HONOURING SERVICE; B (Prontidão para combate e uso da força) = 1.", "formula": null}, {"titulo": "Passo 3", "conteudo": "COMBAT OPERATIONS; C (Treinamento e especialização de recrutas/cadetes) = 3.", "formula": null}, {"titulo": "Passo 4", "conteudo": "EDUCATION; D (Resposta rápida a desastres e apoio humanitário) = 2.", "formula": null}, {"titulo": "Conclusão", "conteudo": "HUMANITARIAN ASSISTANCE. Sequência correta: A-4, B-1, C-3, D-2.", "formula": null}]', 'automatica', TRUE, FALSE, '28066fb6649616fdd93987bd121265df835f3532add9d2f932a458bb101558fe', 'esa-2024-geral.txt'),
('ESA', 'Inglês', 'Gramática (Tempos e Modos Verbais)', 2024, 'Prova única', 'Exército Brasileiro (Comissão Própria)', 43, '43', NULL, 'medio', NULL, 'Use the correct verb tenses to complete the text.

A BRAZILIAN NCO IN A UN FORCE
Sergeant Torres is a Brazilian Platoon Sergeant in a United Nations protection force at a refugee camp in the middle of a war zone. The mission of this force is to protect the refugees from local bandits, militia and the belligerents. A humanitarian organization ____ the camp, while Torres and his comrades provide security. A week ago, fighting ____ the supply route. Despite rationing, Torres and his fellow soldiers ____ nothing to eat for three days and are on their last bottles of water in a hot, dry, desert climate. Refugees, especially children, ____ at an increasing rate now, and the humanitarian worker warns that hundreds more ____ soon if the refugee camp does not receive water and food. Sergeant Torres and the other soldiers remain firm and alert in spite of the signs of dehydration and weakness from starvation.', '[{"letra": "A", "texto": "runs - blocked - have - are dying - perishing"}, {"letra": "B", "texto": "runs - blocked - have had - died - will perish"}, {"letra": "C", "texto": "ran - blocked - have had - is dying - will perish"}, {"letra": "D", "texto": "runs - blocks - have had - are dying - will perish"}, {"letra": "E", "texto": "runs - blocked - have had - are dying - will perish"}]', 'E', '1. "runs" (Present Simple para descrever rotina/fato permanente);
2. "blocked" (Simple Past marcado pelo adjunto "A week ago");
3. "have had" (Present Perfect para ação que dura até o presente com "for three days");
4. "are dying" (Present Continuous associado ao advérbio "now");
5. "will perish" (Simple Future para previsão condicionada "soon").', NULL, NULL, 'resumida', FALSE, FALSE, '121dd78503838dd41a382cff1daf162812feb55078771be52f37435ab33d46dc', 'esa-2024-geral.txt'),
('ESA', 'Inglês', 'Gramática (Pronomes e Adjetivos Indefinidos)', 2024, 'Prova única', 'Exército Brasileiro (Comissão Própria)', 44, '44', NULL, 'medio', NULL, 'Complete the story with the correct indefinite adjectives and pronouns.

During a patrol a United Nations Peacekeeping mission patrol, Sergeant Reis and his squad scans the surroundings of the area carefully.
Sergeant Reis: - Everything seems to be calm around here. I see ____ signs of danger but remain on alert.
Corporal Santos: - We are vigilant, sir, but I sincerely hope ____ bad happens tonight. However, we are ready to respond to ____ situation.
Private Costa: - There is ____ moving ahead in the darkness, Sergeant Reis. Can you see it? Is it a dog?
Corporal Santos: - I think it’s a person. ____ is coming towards us.
Sergeant Reis: - Take cover and cock your weapons. I will warn him or her of our presence. We have to follow the rules of engagement.
Sergeant Reis: Is ____ there? United Nations! Stop or I’ll shoot!
Although the mission is to maintain peace and security, Sergeant Reis is ready to protect his men at any cost and make sure that ____ poses a threat to his unit.', '[{"letra": "A", "texto": "no – nothing – no – anything – Somebody – anybody – nobody"}, {"letra": "B", "texto": "no – nothing – any – something – Somebody – anybody – nobody"}, {"letra": "C", "texto": "any – nothing – any – something – Somebody – anybody – somebody"}, {"letra": "D", "texto": "no – anything – any – something – Somebody – anybody – nobody"}, {"letra": "E", "texto": "no – nothing – any – something – Anything – nobody – nobody"}]', 'B', '1. "no signs" (sentido negativo sem outra negação na frase);
2. "nothing bad" (nada de ruim);
3. "any situation" (qualquer situação);
4. "something moving" (algo se movendo);
5. "Somebody is coming" (alguém se aproximando);
6. "Is anybody there?" (alguém em frase interrogativa);
7. "nobody poses" (ninguém represente ameaça).', NULL, NULL, 'resumida', TRUE, FALSE, '46dee9d6ba014af7d47bb38fe0a4650a52d0f69fb9ed453f9719a0124bb6f1df', 'esa-2024-geral.txt'),
('ESA', 'Inglês', 'Vocabulário e Regência de Adjetivos', 2024, 'Prova única', 'Exército Brasileiro (Comissão Própria)', 45, '45', NULL, 'medio', NULL, 'Choose the suitable adjectives to make the text coherent.

THE ROUTINE OF A MODEL PLATOON SERGEANT
The routine of a model platoon sergeant, a crucial figure in a military unit, is ____ of diverse responsibilities and challenges. While they may be ____ at maintaining discipline, they are never ____ with their subordinates. In fact, they understand the importance of being ____ to privates and corporals within the unit.
Platoon Sergeants are committed to the growth and well-being of their team. They are ____ in their soldiers'' professional development, offering guidance and mentorship. They are also devoted to the mission of the unit.
Like anyone else, platoon sergeants sometimes feel ____ with the demands of their role. However, their commitment remains firm, as they are aware that their actions can influence the success or failure of a mission. If any mistakes occur, they are ____ about the consequences and take responsibility for leading their team to learn and improve.
The role of a platoon sergeant is ____ from other ranks, requiring strong leadership. While they have moments of fear or hesitation, they do not let it overcome them. They perform their duties with diligence, always aware of the impact on their unit''s morale and performance.', '[{"letra": "A", "texto": "full – good – angry – kind – interested – fed up – sorry – different"}, {"letra": "B", "texto": "different – good – angry – kind – interested – fed up – sorry – full"}, {"letra": "C", "texto": "full – good – kind – angry – interested – fed up – sorry – different"}, {"letra": "D", "texto": "full – sorry – angry – kind – interested – fed up – good – different"}, {"letra": "E", "texto": "different – good – angry – kind – interested – full – sorry – fed up"}]', 'A', 'A correta regência dos adjetivos com suas respectivas preposições exige: full of (cheio de), good at (bom em), angry with (zangado com), kind to (gentil com), interested in (interessado em), fed up with (farto de), sorry about (magoado/arrependido por), diferente from (diferente de).', NULL, NULL, 'resumida', FALSE, FALSE, '06db63f0da11733d7e8d78338c3af89fa06afa5a11c6fc27ca661e5878ad4ddd', 'esa-2024-geral.txt'),
('ESA', 'Inglês', 'Gramática (Artigos Definidos e Indefinidos)', 2024, 'Prova única', 'Exército Brasileiro (Comissão Própria)', 46, '46', NULL, 'facil', NULL, 'If necessary, fill in the blanks with definite or indefinite articles to have a coherent text.

BRAZILIAN ARMY REPLACES FN FAL WITH IMBEL IA2
The IMBEL IA2 rifle is ____ versatile firearm in service in Brazilian Army. The state-owned company IMBEL (Indústria de Material Bélico do Brasil) manufactures the IA2 rifle. It has gradually replaced the outdated FN FAL rifle.
This modern assault rifle has gained ____ popularity among soldiers due to its exceptional accuracy, durability, and adaptability. The IA2 also offers quick barrel change for different mission requirements. Furthermore, the IA2 possesses tactical rails that enable the attachment of additional accessories such as optics, lasers, and flashlights.
With its exceptional performance and adaptability, the IMBEL IA2 rifle has greatly improved the operational capabilities of the Brazilian Army, making it ____ useful weapon in the defence of Brazil.', '[{"letra": "A", "texto": "a - the - \"no article\" - \"no article\" - a - the"}, {"letra": "B", "texto": "a - the - \"no article\" - \"no article\" - an - \"no article\""}, {"letra": "C", "texto": "a - \"no article\" - a"}, {"letra": "D", "texto": "\"no article\" - a - \"no article\""}, {"letra": "E", "texto": "a - a - \"no article\""}]', 'C', '1. "a versatile firearm" (uso do artigo indefinido ''a'' antes de som consonantal);
2. "gained popularity" (substantivo incontável abstrato usado em sentido geral, sem artigo);
3. "a useful weapon" (''useful'' inicia-se com som consonantal /j/, exigindo o artigo indefinido ''a'').', NULL, NULL, 'resumida', FALSE, FALSE, '891941903327d34e7fdde38750ef03f3ed725f614f76a3e156b0e4cb8b305b79', 'esa-2024-geral.txt'),
('ESA', 'Inglês', 'Gramática (Substituição por Pronomes Pessoais)', 2024, 'Prova única', 'Exército Brasileiro (Comissão Própria)', 47, '47', NULL, 'facil', NULL, 'Avoid repetition in text by replacing the underlined phrases with the right pronouns.

MARIA EDUARDA''S CHANGE OF CAREERS
Maria Eduarda was an English teacher at a private school in Três Corações. Seven years ago, she saw a military parade on Independence Day and thought about joining the Brazilian Army. At first Maria Eduarda''s husband didn''t support Maria Eduarda''s radical career change because Maria Eduarda''s husband was very worried about her radical career change. On the other hand, Maria Eduarda''s mother and father encouraged Maria Eduarda because Maria Eduarda''s mother and father were very proud of their daughter''s decision. Then Maria Eduarda applied for the Army exam and passed it. Now she is a brilliant English Teacher in the Language Teaching Section of the NCO Academy.', '[{"letra": "A", "texto": "her - he - it - her - they"}, {"letra": "B", "texto": "she - he - it - her - they"}, {"letra": "C", "texto": "her - she - it - him - they"}, {"letra": "D", "texto": "her - he - its - her - they"}, {"letra": "E", "texto": "her - he - it - her - them"}]', 'A', 'Substituições pronominais adequadas para evitar repetições no texto:
1. Maria Eduarda''s husband -> her husband / he;
2. Maria Eduarda''s radical career change -> it;
3. Maria Eduarda -> her;
4. Maria Eduarda''s mother and father -> they.', NULL, '[{"titulo": "Passo 1", "conteudo": "Substituições pronominais adequadas para evitar repetições no texto:\n1. Maria Eduarda''s husband -> her husband / he;\n2.", "formula": null}, {"titulo": "Passo 2", "conteudo": "Maria Eduarda''s radical career change -> it;\n3. Maria Eduarda -> her;\n4.", "formula": null}, {"titulo": "Conclusão", "conteudo": "Maria Eduarda''s mother and father -> they.", "formula": null}]', 'automatica', FALSE, FALSE, 'ec907d26a7c72288f1b38cbe7113a95fda577de50194a79544476946f6e5cf20', 'esa-2024-geral.txt'),
('ESA', 'Inglês', 'Gramática (Caso Possessivo / Relação de Posse)', 2024, 'Prova única', 'Exército Brasileiro (Comissão Própria)', 48, '48', NULL, 'facil', NULL, 'Read the text.

The sergeant major addressed the battalion with a powerful speech. "Courage and discipline," he said, "are the hallmarks of a true soldier." The troops felt a surge of pride as they listened.

Which part of the text contains a possessive case?', '[{"letra": "A", "texto": "The sergeant major addressed the battalion with a powerful speech."}, {"letra": "B", "texto": "\"Courage and discipline,\" he said."}, {"letra": "C", "texto": "\"are the hallmarks of a true soldier.\""}, {"letra": "D", "texto": "The troops felt a surge of pride."}, {"letra": "E", "texto": "as they listened."}]', 'C', 'Na expressão "hallmarks of a true soldier", o emprego da preposição "of" estabelece uma relação de posse/pertencimento atributivo ("características de um verdadeiro soldado"), configurando uma construção equivalente ao Genitive/Possessive case.', NULL, NULL, 'resumida', FALSE, FALSE, 'b1b520ad4e3a8a8323875818c530dc42c9ff081d6a061b783982ca5be54c43c4', 'esa-2024-geral.txt'),
('ESA', 'Inglês', 'Gramática (Preposições de Lugar e Direção)', 2024, 'Prova única', 'Exército Brasileiro (Comissão Própria)', 49, '49', NULL, 'medio', NULL, 'Read the text and then choose the correct answer to fill the blanks. Be attentive to the coherence of the text and the prepositions you must use or omit before the phrases.

SPECIAL TALENTS AT THE NCO ACADEMY
Sergeant Major Gilson commands respect, standing ____ the door of the NCO Academy print workshop and ready to greet his comrades with a gentle smile. He always works diligently ____ his desk, with piles of paperwork and a strong cup of coffee. However, behind closed doors, behind that disciplined facade, there is a secret: a passion for art. His own masterpieces are hanging ____ the walls of his office, showing his remarkable talent as a painter.
In his quarters, Sergeant Major Gilson devotes all his spare time to painting. Paintbrushes and palettes lie meticulously arranged ____ a shelf. As people rarely see him out of uniform, he surprises everyone with his remarkable talent. When he is not in the barracks, Sergeant Gilson is pursuing a degree in Fine Arts ____ the local college, indulging his passion.
Late in the evening, after his long day, Sergeant Gilson finally gets ____ home, exhausted but content. He kicks off his boots, relaxes in his favourite chair, and dreams of the next stroke of his brush that will bring his vivid imagination to life.', '[{"letra": "A", "texto": "on - on - no preposition - at - at - at"}, {"letra": "B", "texto": "at - at - on - on - at - no preposition"}, {"letra": "C", "texto": "at - on - no preposition - on - at - on"}, {"letra": "D", "texto": "in - at - in - on - at - on"}, {"letra": "E", "texto": "at - on - in - at - on - in"}]', 'B', 'Emprego das preposições de lugar e movimento:
1. standing at the door (posição específica);
2. works at his desk (local de trabalho);
3. hanging on the walls (superfície vertical);
4. arranged on a shelf (superfície horizontal);
5. at the local college (instituição);
6. gets home (o verbo ''get'' seguido de ''home'' não admite preposição de lugar).', NULL, NULL, 'resumida', FALSE, FALSE, 'dba456cf733910952197703def007b07d3e008138727948decb9b0d58be98463', 'esa-2024-geral.txt'),
('ESA', 'Inglês', 'Gramática (Verbos Modais / Identificação de Estrutura)', 2024, 'Prova única', 'Exército Brasileiro (Comissão Própria)', 50, '50', NULL, 'facil', NULL, 'Read the sentence:
"The soldiers are marching as if their lives depend on it."

Identify the modal verb in the phrase "as if their lives depend on it".', '[{"letra": "A", "texto": "lives"}, {"letra": "B", "texto": "as"}, {"letra": "C", "texto": "their"}, {"letra": "D", "texto": "on"}, {"letra": "E", "texto": "None of the above"}]', 'E', 'Na oração "as if their lives depend on it", encontram-se conjunção ("as if"), pronome possessivo ("their"), substantivo ("lives"), verbo principal no presente ("depend") e preposição ("on"). Não há presença de nenhum verbo modal (como can, could, may, might, must, shall, should, will, would), motivo pelo qual a resposta correta é "None of the above".', NULL, NULL, 'resumida', FALSE, FALSE, '1b0edec27615c1486dc05662400ea97e431ea9250b48b480c9e9365070efe725', 'esa-2024-geral.txt'),
('ESA', 'Matemática', 'Dominio de Funções e Inequações', 2025, 'Prova única', 'Exército Brasileiro / ESA', 1, '01', NULL, 'medio', NULL, 'Marque a alternativa que explicita o domínio D da função f: R -> R, definida pela lei de formação:
f(x) = sqrt((x + 1) / (x^2 - 16))', '[{"letra": "A", "texto": "D = {x in R | x >= 1 e x != 4}"}, {"letra": "B", "texto": "D = {x in R | -1 <= x <= 4}"}, {"letra": "C", "texto": "D = {x in R | -4 < x < 4}"}, {"letra": "D", "texto": "D = {x in R | x < 1 e x != -4}"}, {"letra": "E", "texto": "D = {x in R | -4 < x <= -1 e x > 4}"}]', 'E', 'Para que a função f(x) = sqrt((x+1)/(x^2-16)) exista no conjunto dos números reais, o radicando deve ser maior ou igual a zero e o denominador diferente de zero. Analisando as raízes do numerador (x = -1) e do denominador (x = -4 e x = 4) através do estudo do sinal do quociente, obtém-se o conjunto solução -4 < x <= -1 ou x > 4, correspondendo exatamente à alternativa E.', NULL, NULL, 'resumida', TRUE, FALSE, 'a86cabddcb8d874c5ad1f5c20abbb2c503274e02dcbc98207669aa1177bc6f75', 'esa-2025-geral.txt'),
('ESA', 'Matemática', 'Teoria dos Números e Paridade', 2025, 'Prova única', 'Exército Brasileiro / ESA', 2, '02', NULL, 'facil', NULL, 'Sabendo-se que x é um número inteiro positivo e par e y é um número inteiro positivo e ímpar, analise as assertivas abaixo:
I - x + y é um número ímpar.
II - 2x + 6y é um número ímpar.
III - -3x + 2y é um número ímpar.
IV - (x - y)^2 é um número ímpar.

Após analisar as assertivas, marque a alternativa correta:', '[{"letra": "A", "texto": "Todas as assertivas estão corretas."}, {"letra": "B", "texto": "Somente II e III estão corretas."}, {"letra": "C", "texto": "Somente I, II e IV estão corretas."}, {"letra": "D", "texto": "Somente I e II estão corretas."}, {"letra": "E", "texto": "Somente I e IV estão corretas."}]', 'E', 'Sendo x par (x = 2k) e y ímpar (y = 2m+1):
I. x + y = par + ímpar = ímpar (Correto).
II. 2x + 6y = 2(par) + 6(ímpar) = par + par = par (Incorreto).
III. -3x + 2y = -3(par) + 2(ímpar) = par + par = par (Incorreto).
IV. (x - y)^2 = (par - ímpar)^2 = (ímpar)^2 = ímpar (Correto).
Logo, somente I e IV são verdadeiras.', NULL, '[{"titulo": "Passo 1", "conteudo": "Sendo x par (x = 2k) e y ímpar (y = 2m+1):\nI. x + y = par + ímpar = ímpar (Correto).\nII. 2x + 6y = 2(par) + 6(ímpar) = par + par = par (Incorreto).\nIII. -3x + 2y = -3(par) + 2(ímpar) = par + par = par (Incorreto).\nIV. (x - y)^2 = (par - ímpar)^2 = (ímpar)^2 = ímpar (Correto).", "formula": null}, {"titulo": "Conclusão", "conteudo": "Logo, somente I e IV são verdadeiras.", "formula": null}]', 'automatica', TRUE, FALSE, 'f1e39c790a9e60f75669116688981378802dc0f464047d08645fe6c90bffec19', 'esa-2025-geral.txt'),
('ESA', 'Matemática', 'Geometria Analítica (Distância Ponto-Reta)', 2025, 'Prova única', 'Exército Brasileiro / ESA', 3, '03', NULL, 'medio', '[DESCRIÇÃO DA IMAGEM: Gráfico no plano cartesiano mostrando um eixo y variando de 0 a 9 e eixo x de 0 a 12. Há uma reta descendente "Avenida A" interceptando o eixo y em (0,9) e o eixo x em (12,0). Há um ponto P posicionado nas coordenadas (3,2).]', 'Um Pelotão de Infantaria está no terreno representado pelo sistema de coordenadas retangulares abaixo. Sua localização é o ponto P. Em que distância o Pelotão se encontra da Avenida "A"?', '[{"letra": "A", "texto": "3,8km"}, {"letra": "B", "texto": "3,6km"}, {"letra": "C", "texto": "2,8km"}, {"letra": "D", "texto": "2,7km"}, {"letra": "E", "texto": "2,4km"}]', 'A', 'A reta que representa a Avenida "A" passa pelos pontos (0,9) e (12,0). Sua equação geral é dada por 3x + 4y - 36 = 0. A distância do ponto P(3,2) até essa reta é calculada pela fórmula d = |a*x0 + b*y0 + c| / sqrt(a^2 + b^2). Aplicando os valores: d = |3(3) + 4(2) - 36| / sqrt(3^2 + 4^2) = |-19| / 5 = 19/5 = 3,8 km.', 'Gráfico no plano cartesiano mostrando um eixo y variando de 0 a 9 e eixo x de 0 a 12. Há uma reta descendente "Avenida A" interceptando o eixo y em (0,9) e o eixo x em (12,0). Há um ponto P posicionado nas coordenadas (3,2).', '[{"titulo": "Passo 1", "conteudo": "A reta que representa a Avenida \"A\" passa pelos pontos (0,9) e (12,0). Sua equação geral é dada por 3x + 4y - 36 = 0. A distância do ponto P(3,2) até essa reta é calculada pela fórmula d = |a*x0 + b*y0 + c| / sqrt(a^2 + b^2).", "formula": null}, {"titulo": "Aplicando a fórmula", "conteudo": "Aplicando os valores: d = |3(3) + 4(2) - 36| / sqrt(3^2 + 4^2) = |-19| / 5 = 19/5 = 3,8 km.", "formula": null}]', 'automatica', TRUE, FALSE, '2bd551c81dd6c251789fc09b58bfc859c57a22c279ed1af7424f8a3794510f03', 'esa-2025-geral.txt'),
('ESA', 'Matemática', 'Estatística (Média, Moda e Mediana)', 2025, 'Prova única', 'Exército Brasileiro / ESA', 4, '04', NULL, 'medio', 'Após o primeiro ano, cursado nas Unidades Escolares Tecnológicas do Exército, 516 Alunos do Curso de Formação e Graduação da Escola de Sargentos das Armas, provenientes das cinco regiões do país, adentraram o Portão Histórico da ESA, marcando o início da qualificação nas cinco armas combatentes do Exército. Logo após a atividade de entrada, os Alunos da Escola de Sargentos das Armas (ESA), dessa vez acompanhados de 32 Alunos do Centro de Instrução de Aviação do Exército (CIAvEx) participaram da Solenidade de Entrega do Sabre Sargento Max Wolff Filho.

Para a realização da solenidade, foi perguntado ao total de alunos a estatura de cada um, para que pudessem ser colocados em forma na ordem crescente de altura. A tabela abaixo mostra o quantitativo das estaturas, tanto dos alunos da ESA, quanto dos alunos do CIAvEx:

ESTATURA DOS ALUNOS DO CFGS 24/25
ESA:
- Quantidade: 120 | Estatura: 1,62m
- Quantidade: 150 | Estatura: 1,65m
- Quantidade: 200 | Estatura: 1,70m
- Quantidade: 46 | Estatura: 1,75m
TOTAL ESA: 516

CIAVEX:
- Quantidade: 16 | Estatura: 1,55m
- Quantidade: 6 | Estatura: 1,63m
- Quantidade: 8 | Estatura: 1,70m
- Quantidade: 2 | Estatura: 1,80m
TOTAL CIAVEX: 32', 'De acordo com os dados apresentados na tabela acima e levando em consideração o total de alunos das duas Escolas, pode-se afirmar que:
(Obs.: utilize apenas duas casas decimais após a vírgula).', '[{"letra": "A", "texto": "Mediana > média > moda"}, {"letra": "B", "texto": "Média = moda = mediana"}, {"letra": "C", "texto": "Mediana = média = moda"}, {"letra": "D", "texto": "Média < moda < mediana"}, {"letra": "E", "texto": "Moda > mediana > média"}]', 'E', 'Unindo a população total (548 alunos):
- Moda: valor de maior frequência, 1,70 m (208 alunos).
- Mediana: termo central (posições 274ª e 275ª acumuladas), resulta em 1,65 m.
- Média: soma ponderada total de alturas (914,18) dividida por 548 alunos, resultando em aproximadamente 1,67 m.
Portanto, comparando os valores obtidos (Moda = 1,70 > Média = 1,67 > Mediana = 1,65), a ordem decrescente é Moda > Mediana > Média (conforme alternativa E apresentada pela banca).', NULL, '[{"titulo": "Passo 1", "conteudo": "Unindo a população total (548 alunos):\n- Moda: valor de maior frequência, 1,70 m (208 alunos).\n- Mediana: termo central (posições 274ª e 275ª acumuladas), resulta em 1,65 m.\n- Média: soma ponderada total de alturas (914,18) dividida por 548 alunos, resultando em aproximadamente 1,67 m.", "formula": null}, {"titulo": "Conclusão", "conteudo": "Portanto, comparando os valores obtidos (Moda = 1,70 > Média = 1,67 > Mediana = 1,65), a ordem decrescente é Moda > Mediana > Média (conforme alternativa E apresentada pela banca).", "formula": null}]', 'automatica', TRUE, FALSE, 'e92ad4ed66109cb86f88c4354122452ef27036290402e38afda2dca3efbf4920', 'esa-2025-geral.txt'),
('ESA', 'Matemática', 'Equação do 2º Grau e Relações de Girard', 2025, 'Prova única', 'Exército Brasileiro / ESA', 5, '05', NULL, 'facil', NULL, 'Considere a equação:
x^2 - (9/4)x + m = 0

Sabendo que uma das raízes é o dobro da outra, marque a alternativa que apresenta o produto do numerador pelo denominador de m.', '[{"letra": "A", "texto": "72"}, {"letra": "B", "texto": "36"}, {"letra": "C", "texto": "24"}, {"letra": "D", "texto": "18"}, {"letra": "E", "texto": "12"}]', 'A', 'Pelas Relações de Girard, r1 + r2 = 9/4. Como r2 = 2*r1, temos 3*r1 = 9/4 => r1 = 3/4 e r2 = 3/2. O produto das raízes fornece m = r1 * r2 = (3/4) * (3/2) = 9/8. O numerador é 9 e o denominador é 8. O produto entre eles é 9 * 8 = 72.', NULL, '[{"titulo": "Passo 1", "conteudo": "Pelas Relações de Girard, r1 + r2 = 9/4.", "formula": null}, {"titulo": "O que o enunciado dá", "conteudo": "Como r2 = 2*r1, temos 3*r1 = 9/4 => r1 = 3/4 e r2 = 3/2. O produto das raízes fornece m = r1 * r2 = (3/4) * (3/2) = 9/8. O numerador é 9 e o denominador é 8. O produto entre eles é 9 * 8 = 72.", "formula": null}]', 'automatica', TRUE, FALSE, '4b98dc6649c6abcce835e245d55e20e683b10fdfd84ae1b1b2477bd0fde83ac3', 'esa-2025-geral.txt'),
('ESA', 'Matemática', 'Sistemas Lineares', 2025, 'Prova única', 'Exército Brasileiro / ESA', 6, '06', NULL, 'medio', NULL, 'Dado o sistema linear abaixo nas incógnitas x, y e z, determine o(s) valor(es) de t, tal que t in R para que seja um sistema possível e indeterminado (SPI).
{ 2x + y + 8z = -2
{ 4x + 5y + z = 5
{ 6x + 3y + (t^2 - 1)z = t - 1', '[{"letra": "A", "texto": "t = -5"}, {"letra": "B", "texto": "t = -1"}, {"letra": "C", "texto": "t = 0"}, {"letra": "D", "texto": "t = 1"}, {"letra": "E", "texto": "t = 5"}]', 'A', 'Para que o sistema linear seja Possível e Indeterminado (SPI), as equações devem ser dependentes. Multiplicando a 1ª equação por 3, temos 6x + 3y + 24z = -6. Igualando com a 3ª equação [6x + 3y + (t^2 - 1)z = t - 1], temos t^2 - 1 = 24 => t^2 = 25 (t = 5 ou -5) e t - 1 = -6 => t = -5. O único valor comum que satisfaz ambas as condições é t = -5.', NULL, '[{"titulo": "Passo 1", "conteudo": "Para que o sistema linear seja Possível e Indeterminado (SPI), as equações devem ser dependentes.", "formula": null}, {"titulo": "Fazendo a conta", "conteudo": "Multiplicando a 1ª equação por 3, temos 6x + 3y + 24z = -6. Igualando com a 3ª equação [6x + 3y + (t^2 - 1)z = t - 1], temos t^2 - 1 = 24 => t^2 = 25 (t = 5 ou -5) e t - 1 = -6 => t = -5. O único valor comum que satisfaz ambas as condições é t = -5.", "formula": null}]', 'automatica', TRUE, FALSE, 'ac71920de46b2958a60148528aee6d3ecd0a23448fae7af9efa335492bd75671', 'esa-2025-geral.txt'),
('ESA', 'Matemática', 'Probabilidade e Teoria dos Conjuntos', 2025, 'Prova única', 'Exército Brasileiro / ESA', 7, '07', NULL, 'medio', 'A Seção de Educação Física da ESA elaborou uma pesquisa entre 60 alunos do Curso de Formação e Graduação de Sargentos sobre a preferência entre 3 modalidades esportivas: basquete (B), futebol (F) e vôlei (V). Os dados obtidos foram tabelados como se seguem:
- B: 27
- F: 20
- V: 25
- B e F: 5
- B e V: 8
- F e V: 7
- B, F e V: 2', 'Escolhendo-se aleatoriamente um aluno entre os 60 alunos pesquisados, qual a probabilidade de ele preferir, no máximo, uma modalidade esportiva?', '[{"letra": "A", "texto": "0,7333..."}, {"letra": "B", "texto": "0,7"}, {"letra": "C", "texto": "0,6555..."}, {"letra": "D", "texto": "0,4333..."}, {"letra": "E", "texto": "0,6"}]', 'A', 'Preenchendo o diagrama de Venn com os dados: Apenas B = 16, Apenas F = 10, Apenas V = 12. Total de alunos que preferem exatamente 1 modalidade = 16 + 10 + 12 = 38. Alunos que não preferem nenhuma das 3 = 60 - (16 + 10 + 12 + 3 + 6 + 5 + 2) = 6. "No máximo 1 modalidade" inclui 0 ou 1 modalidade = 38 + 6 = 44 alunos. Probabilidade = 44 / 60 = 11/15 = 0,7333...', NULL, '[{"titulo": "Passo 1", "conteudo": "Preenchendo o diagrama de Venn com os dados: Apenas B = 16, Apenas F = 10, Apenas V = 12.", "formula": null}, {"titulo": "Passo 2", "conteudo": "Total de alunos que preferem exatamente 1 modalidade = 16 + 10 + 12 = 38. Alunos que não preferem nenhuma das 3 = 60 - (16 + 10 + 12 + 3 + 6 + 5 + 2) = 6. \"No máximo 1 modalidade\" inclui 0 ou 1 modalidade = 38 + 6 = 44 alunos.", "formula": null}, {"titulo": "Conclusão", "conteudo": "Probabilidade = 44 / 60 = 11/15 = 0,7333...", "formula": null}]', 'automatica', TRUE, FALSE, '6b6114fe91b8173201625ed116e4bc68c538bd28a383e6cedf7581202c6aee42', 'esa-2025-geral.txt'),
('ESA', 'Matemática', 'Raciocínio Lógico (Equivalências)', 2025, 'Prova única', 'Exército Brasileiro / ESA', 8, '08', NULL, 'facil', 'Durante a prova para um concurso, um candidato deparou-se com a seguinte proposição composta:
P: "Se o candidato não foi eliminado da prova, então ele estudou e foi aprovado."', 'Com base em seus conhecimentos de Noções de Lógica, pode-se afirmar que:', '[{"letra": "A", "texto": "Se ele não estudou e não foi aprovado, então o candidato foi eliminado da prova."}, {"letra": "B", "texto": "O candidato foi eliminado da prova e ele estudou ou foi reprovado."}, {"letra": "C", "texto": "Se ele não estudou ou foi aprovado, então o candidato foi eliminado da prova."}, {"letra": "D", "texto": "Ele não estudou ou não foi aprovado, então o candidato não foi eliminado da prova."}, {"letra": "E", "texto": "Se ele não estudou ou não foi aprovado, então o candidato foi eliminado da prova."}]', 'E', 'A proposição dada é uma condicional da forma P -> (Q e R). Sua equivalência lógica contrapositiva é ~ (Q e R) -> ~ P. Aplicando a Lei de De Morgan no consequente, temos (~ Q ou ~ R) -> ~ P. Traduzindo: "Se ele não estudou ou não foi aprovado, então o candidato foi eliminado da prova".', NULL, '[{"titulo": "Passo 1", "conteudo": "A proposição dada é uma condicional da forma P -> (Q e R). Sua equivalência lógica contrapositiva é ~ (Q e R) -> ~ P.", "formula": null}, {"titulo": "Aplicando a fórmula", "conteudo": "Aplicando a Lei de De Morgan no consequente, temos (~ Q ou ~ R) -> ~ P. Traduzindo: \"Se ele não estudou ou não foi aprovado, então o candidato foi eliminado da prova\".", "formula": null}]', 'automatica', TRUE, FALSE, 'acbfd71d17add17f2330d1b62aa091883d9919c73472e42043ab4f2163d0d445', 'esa-2025-geral.txt'),
('ESA', 'Matemática', 'Geometria Plana e Progressão Geométrica', 2025, 'Prova única', 'Exército Brasileiro / ESA', 9, '09', NULL, 'medio', NULL, 'O lado de um quadrado mede 4 cm. Unindo os pontos médios de seus lados, obtém-se um novo quadrado. Unindo os pontos médios do novo quadrado, obtém-se outro quadrado, e assim sucessivamente. Calcule a soma dos perímetros, em centímetros, de todos os quadrados citados:', '[{"letra": "A", "texto": "8 + 16*sqrt(2)"}, {"letra": "B", "texto": "16 + 8*sqrt(2)"}, {"letra": "C", "texto": "16 + 32*sqrt(2)"}, {"letra": "D", "texto": "32 + 16*sqrt(2)"}, {"letra": "E", "texto": "64 + 32*sqrt(2)"}]', 'D', 'O 1º quadrado tem lado 4 e perímetro P1 = 16. O 2º quadrado tem lado 2*sqrt(2) e perímetro P2 = 8*sqrt(2). O 3º quadrado tem lado 2 e perímetro P3 = 8. A sequência dos perímetros forma uma P.G. infinita decrescente de razão q = sqrt(2)/2. Aplicando a fórmula da soma da P.G. infinita S = P1 / (1 - q) = 16 / (1 - sqrt(2)/2), racionalizando obtemos 32 + 16*sqrt(2).', NULL, '[{"titulo": "Passo 1", "conteudo": "O 1º quadrado tem lado 4 e perímetro P1 = 16. O 2º quadrado tem lado 2*sqrt(2) e perímetro P2 = 8*sqrt(2). O 3º quadrado tem lado 2 e perímetro P3 = 8. A sequência dos perímetros forma uma P.G. infinita decrescente de razão q = sqrt(2)/2.", "formula": null}, {"titulo": "Aplicando a fórmula", "conteudo": "Aplicando a fórmula da soma da P.G. infinita S = P1 / (1 - q) = 16 / (1 - sqrt(2)/2), racionalizando obtemos 32 + 16*sqrt(2).", "formula": null}]', 'automatica', TRUE, FALSE, 'c6e1f7f03746300a9ee4cec611cd04e0c3e0ebc8280f47c0dfbf5af2aa34e469', 'esa-2025-geral.txt'),
('ESA', 'Matemática', 'Álgebra e Binômio de Newton', 2025, 'Prova única', 'Exército Brasileiro / ESA', 10, '10', NULL, 'medio', NULL, 'Sendo x e y números reais, marque a alternativa que apresenta o resultado para a soma x + y:
{ x + 2y = 5
{ x^6 + 6(x^5)y + 15(x^4)(y^2) + 20(x^3)(y^3) + 15(x^2)(y^4) + 6x(y^5) + y^6 = 64', '[{"letra": "A", "texto": "-2"}, {"letra": "B", "texto": "-1"}, {"letra": "C", "texto": "0"}, {"letra": "D", "texto": "1"}, {"letra": "E", "texto": "2"}]', 'E', 'A segunda equação representa o desenvolvimento do Binômio de Newton (x + y)^6 = 64. Tirando a raiz sexta, temos x + y = 2 ou x + y = -2. Substituindo no sistema combinado com x + 2y = 5 para verificação do conjunto real, obtém-se o valor válido x + y = 2.', NULL, '[{"titulo": "Passo 1", "conteudo": "A segunda equação representa o desenvolvimento do Binômio de Newton (x + y)^6 = 64. Tirando a raiz sexta, temos x + y = 2 ou x + y = -2.", "formula": null}, {"titulo": "Aplicando a fórmula", "conteudo": "Substituindo no sistema combinado com x + 2y = 5 para verificação do conjunto real, obtém-se o valor válido x + y = 2.", "formula": null}]', 'automatica', TRUE, FALSE, 'a70b0a8ba0be25fc94c11ea027b4cacad94afca82da96473ed2b5e6ef146dbb5', 'esa-2025-geral.txt'),
('ESA', 'Matemática', 'Equação Logarítmica', 2025, 'Prova única', 'Exército Brasileiro / ESA', 11, '11', NULL, 'dificil', NULL, 'Observe a equação real abaixo:
log_2(x + 5) + (1/2)*log_2(x + 8) = 1/2

Sobre a equação supracitada, pode-se afirmar que:', '[{"letra": "A", "texto": "Seu conjunto solução é o conjunto vazio."}, {"letra": "B", "texto": "Seu conjunto solução só possui uma raiz real irracional."}, {"letra": "C", "texto": "Seu conjunto solução possui exatamente três raízes reais."}, {"letra": "D", "texto": "Seu conjunto solução possui duas raízes reais, uma racional e a outra irracional."}, {"letra": "E", "texto": "A soma de suas raízes produz um número real e racional."}]', 'B', 'Multiplicando toda a equação por 2, temos 2*log_2(x+5) + log_2(x+8) = 1 => log_2([(x+5)^2] * (x+8)) = 1 => (x^2 + 10x + 25)(x + 8) = 2. Desenvolvendo a equação cúbica x^3 + 18x^2 + 105x + 198 = 0. Testando raízes, x = -6 é raiz algébrica, porém viola a condição de existência x + 5 > 0 (x > -5). As outras raízes são x = -6 +- sqrt(3). Apenas a raiz x = -6 + sqrt(3) atende a condição x > -5, sendo esta uma raiz real e irracional.', NULL, '[{"titulo": "Fazendo a conta", "conteudo": "Multiplicando toda a equação por 2, temos 2*log_2(x+5) + log_2(x+8) = 1 => log_2([(x+5)^2] * (x+8)) = 1 => (x^2 + 10x + 25)(x + 8) = 2. Desenvolvendo a equação cúbica x^3 + 18x^2 + 105x + 198 = 0.", "formula": null}, {"titulo": "Passo 2", "conteudo": "Testando raízes, x = -6 é raiz algébrica, porém viola a condição de existência x + 5 > 0 (x > -5). As outras raízes são x = -6 +- sqrt(3).", "formula": null}, {"titulo": "Conclusão", "conteudo": "Apenas a raiz x = -6 + sqrt(3) atende a condição x > -5, sendo esta uma raiz real e irracional.", "formula": null}]', 'automatica', TRUE, FALSE, '34521150469213381be1371cb7fd1637d7fa28887d534e8cb3fc48fe7625ad7c', 'esa-2025-geral.txt'),
('ESA', 'Matemática', 'Matrizes e Determinantes', 2025, 'Prova única', 'Exército Brasileiro / ESA', 12, '12', NULL, 'facil', 'Considere a matriz real a seguir:
[ x - 1 2 3 ]
[ -4 3 2 ]
[ 4 5 3 ]', 'Sabendo-se que seu determinante é igual a -57 e que x in R pode-se concluir que x é:', '[{"letra": "A", "texto": "Um número negativo."}, {"letra": "B", "texto": "Um número múltiplo de 4."}, {"letra": "C", "texto": "Um número divisor de 9."}, {"letra": "D", "texto": "Um número primo."}, {"letra": "E", "texto": "Um número que possui 2 divisores inteiros."}]', 'D', 'Calculando o determinante da matriz 3x3 pela Regra de Sarrus: Det = 9(x-1) + 16 - 60 - (36 + 10(x-1) - 24) = -x - 55. Igualando ao valor informado: -x - 55 = -57 => -x = -2 => x = 2. Como 2 é um número que só possui dois divisores naturais positivos (1 e ele mesmo), 2 é um número primo.', NULL, '[{"titulo": "Fazendo a conta", "conteudo": "Calculando o determinante da matriz 3x3 pela Regra de Sarrus: Det = 9(x-1) + 16 - 60 - (36 + 10(x-1) - 24) = -x - 55. Igualando ao valor informado: -x - 55 = -57 => -x = -2 => x = 2.", "formula": null}, {"titulo": "O que o enunciado dá", "conteudo": "Como 2 é um número que só possui dois divisores naturais positivos (1 e ele mesmo), 2 é um número primo.", "formula": null}]', 'automatica', TRUE, FALSE, '0b5c3c9dd9d10cc4e34b6382f42be69f3266365bc9c9c27634abf0a81b692360', 'esa-2025-geral.txt'),
('ESA', 'Matemática', 'Análise Combinatória (Permutação Circular)', 2025, 'Prova única', 'Exército Brasileiro / ESA', 13, '13', NULL, 'dificil', '[DESCRIÇÃO DA IMAGEM: Figura circular com o escudo da ESA no centro cercado por 8 divisões com as siglas dos Comandos Militares: CMO, CMP, CMNE, CMN, CMSE, CML, CMS e CMA.]

O COTER (Comando de Operações Terrestre) é formado por 8 Comandos Militares: CMO, CMP, CMNE, CMN, CMSE, CML, CMS e CMA. Todos eles possuem, em seus corpos permanentes, profissionais formados na ESA. Para caracterizar essa situação, foi criado um slogan como o da figura abaixo.', 'Permutando-se as siglas dos Comandos Militares e sabendo que CMA e CMO devem ficar juntas e CMNE e CMSE devem ficar separadas, quantos slogans diferentes podem ser formados?', '[{"letra": "A", "texto": "720"}, {"letra": "B", "texto": "960"}, {"letra": "C", "texto": "1440"}, {"letra": "D", "texto": "2520"}, {"letra": "E", "texto": "5040"}]', 'B', 'Em uma disposição circular com 8 elementos:
1) Juntando CMA e CMO como 1 bloco: temos 7 elementos circulares. Arranjos = (7-1)! * 2! = 6! * 2 = 1440.
2) Subtraindo os casos em que CMNE e CMSE também ficam juntas (ambos blocos juntos): temos 6 elementos circulares. Arranjos = (6-1)! * 2! * 2! = 5! * 4 = 480.
3) Total com CMA/CMO juntas e CMNE/CMSE separadas = 1440 - 480 = 960.', 'Figura circular com o escudo da ESA no centro cercado por 8 divisões com as siglas dos Comandos Militares: CMO, CMP, CMNE, CMN, CMSE, CML, CMS e CMA.', '[{"titulo": "Passo 1", "conteudo": "Em uma disposição circular com 8 elementos:\n1) Juntando CMA e CMO como 1 bloco: temos 7 elementos circulares. Arranjos = (7-1)! * 2! = 6! * 2 = 1440.\n2) Subtraindo os casos em que CMNE e CMSE também ficam juntas (ambos blocos juntos): temos 6 elementos circulares.", "formula": null}, {"titulo": "Conclusão", "conteudo": "Arranjos = (6-1)! * 2! * 2! = 5! * 4 = 480.\n3) Total com CMA/CMO juntas e CMNE/CMSE separadas = 1440 - 480 = 960.", "formula": null}]', 'automatica', TRUE, FALSE, '49a36de07ee6e72041b7ce84e08f4710c0c652bd1655be1e8b712530eb1fee2c', 'esa-2025-geral.txt'),
('ESA', 'Matemática', 'Geometria Plana e Mínimos de Funções', 2025, 'Prova única', 'Exército Brasileiro / ESA', 14, '14', NULL, 'medio', '[DESCRIÇÃO DA IMAGEM: Um quadrado externo cinza contendo um quadrado inscrito inclinado. O segmento da ponta superior esquerda até o vértice do quadrado inscrito mede x.]', 'O quadrado externo tem lados de medida 5 u.c. e o segmento indicado mede x. Marque a alternativa que apresenta o valor mínimo do lado do quadrado que está inscrito.', '[{"letra": "A", "texto": "sqrt(2) / 2"}, {"letra": "B", "texto": "5*sqrt(2) / 2"}, {"letra": "C", "texto": "5 / 2"}, {"letra": "D", "texto": "2 / 5"}, {"letra": "E", "texto": "1 / 2"}]', 'B', 'O lado L do quadrado inscrito em função do segmento x é a hipotenusa dos triângulos retângulos dos cantos de catetos x e 5-x. L^2 = x^2 + (5-x)^2 = 2x^2 - 10x + 25. O valor mínimo dessa função quadrática ocorre no vértice x = 10/4 = 5/2. O valor mínimo de L^2 é f(5/2) = 25/2. Logo, L_mínimo = sqrt(25/2) = 5 / sqrt(2) = 5*sqrt(2) / 2.', 'Um quadrado externo cinza contendo um quadrado inscrito inclinado. O segmento da ponta superior esquerda até o vértice do quadrado inscrito mede x.', '[{"titulo": "Passo 1", "conteudo": "O lado L do quadrado inscrito em função do segmento x é a hipotenusa dos triângulos retângulos dos cantos de catetos x e 5-x. L^2 = x^2 + (5-x)^2 = 2x^2 - 10x + 25. O valor mínimo dessa função quadrática ocorre no vértice x = 10/4 = 5/2. O valor mínimo de L^2 é f(5/2) = 25/2.", "formula": null}, {"titulo": "Conclusão", "conteudo": "Logo, L_mínimo = sqrt(25/2) = 5 / sqrt(2) = 5*sqrt(2) / 2.", "formula": null}]', 'automatica', TRUE, FALSE, '64ae36295e16c7ff0a4c8c3067a001c7fa0da45a42bda2ba86871f1a8f6b562e', 'esa-2025-geral.txt'),
('ESA', 'Português', 'Sintaxe (Orações Subordinadas Substantivas)', 2025, 'Prova única', 'Exército Brasileiro / ESA', 15, '15', NULL, 'medio', 'TEXTO I
SOLDADO NASCIMENTO: RELEMBRE A PASSAGEM DE PELÉ PELO EXÉRCITO BRASILEIRO
O Soldado Nascimento (Nr 201) incorporou às fileiras do Exército Brasileiro em 20 de janeiro de 1959, no 6º Grupo de Artilharia de Costa Motorizado (6° GACosM), localizado em Santos, hoje 2º Grupo de Artilharia Antiaérea (2º GAAAe) e atualmente situado em Praia Grande (SP).
Durante sua passagem pelo Exército, já campeão Mundial de Futebol na Copa do Mundo de 1958, conquistou o Campeonato Sul-americano de Futebol das Forças Armadas, marcando o gol decisivo no jogo final contra a Seleção Militar da Argentina (Brasil 2 x 1 Argentina).
Em entrevista à Revista Verde-Oliva em 2006, Pelé disse que a disciplina e o respeito ao próximo foram os principais ensinamentos que obteve na caserna. "Eu me orgulho muito, porque serviu de base para minha formação e meu caráter. Acho que todos os jovens deveriam passar pelo Exército", afirmou à época.', 'Observe o excerto extraído do Texto 1:
"Em entrevista à Revista Verde-Oliva em 2006, Pelé disse que a disciplina e o respeito ao próximo foram os principais ensinamentos que obteve na caserna. "Eu me orgulho muito, porque serviu de base para minha formação e meu caráter. Acho que todos os jovens deveriam passar pelo Exército", afirmou à época."
Como as orações destacadas podem ser classificadas?', '[{"letra": "A", "texto": "Oração subordinada substantiva apositiva - Oração subordinada substantiva objetiva direta."}, {"letra": "B", "texto": "Oração subordinada substantiva objetiva direta - Oração subordinada substantiva objetiva direta."}, {"letra": "C", "texto": "Oração subordinada substantiva objetiva indireta - Oração subordinada substantiva predicativa."}, {"letra": "D", "texto": "Oração subordinada substantiva subjetiva - Oração subordinada substantiva predicativa."}, {"letra": "E", "texto": "Oração subordinada substantiva completiva nominal - Oração subordinada substantiva objetiva indireta."}]', 'B', 'Ambas as orações destacadas exercem a função sintática de objeto direto dos verbos transitivos diretos a que se subordinam: "disse [que a disciplina e o respeito ao próximo foram...]" (Oração Subordinada Substantiva Objetiva Direta) e "Acho [que todos os jovens deveriam passar...]" (Oração Subordinada Substantiva Objetiva Direta).', NULL, NULL, 'resumida', TRUE, FALSE, '0ce672db56677964e24a12e69d15b4d95ab326929b4e54d87845c79c4dcc8b4a', 'esa-2025-geral.txt'),
('ESA', 'Português', 'Semântica e Polissemia', 2025, 'Prova única', 'Exército Brasileiro / ESA', 16, '16', NULL, 'medio', NULL, '"Pelé disse que a disciplina e o respeito ao próximo foram os principais ensinamentos (...)"
A palavra "próximo" é polissêmica e, para que haja uma clara interpretação, é preciso entender o seu contexto, como se vê no exemplo acima. Contudo, marque a alternativa em que haja um sentido que não está exposto na palavra em destaque no fragmento, mas a substituiria na frase: "no próximo mês, haverá aula."', '[{"letra": "A", "texto": "Paralelo."}, {"letra": "B", "texto": "Contíguo."}, {"letra": "C", "texto": "Anterior."}, {"letra": "D", "texto": "Pretérito."}, {"letra": "E", "texto": "Vigente."}]', 'C', 'Na frase "no próximo mês", a palavra "próximo" assume sentido temporal de subsequente/vindouro. A alternativa "Anterior" apresenta valor antônimo (passado/pretérito), ou seja, um sentido que não pode substituir "próximo" no contexto da frase citada.', NULL, NULL, 'resumida', FALSE, FALSE, 'f0354d2f7457c334e4e12b381c3207dfc1757841891efcbbb444d05b0a39d4e0', 'esa-2025-geral.txt'),
('ESA', 'Português', 'Sintaxe (Funções Sintáticas)', 2025, 'Prova única', 'Exército Brasileiro / ESA', 17, '17', NULL, 'medio', NULL, 'Marque a alternativa cuja estrutura destacada exerça a mesma função sintática da oração:
"(...) 6º Grupo de Artilharia de Costa Motorizado (6° GACosM), localizado em Santos (...)".', '[{"letra": "A", "texto": "\"incorporou às fileiras do Exército Brasileiro\"."}, {"letra": "B", "texto": "\"a disciplina e o respeito ao próximo\"."}, {"letra": "C", "texto": "\"afirmou à época\"."}, {"letra": "D", "texto": "\"Copa do Mundo de 1958\"."}, {"letra": "E", "texto": "\"Em entrevista à Revista Verde-Oliva\"."}]', 'D', 'A oração reduzida de particípio "localizado em Santos" funciona sintaticamente como um adjunto adnominal do substantivo que a antecede. Dentre as opções, a expressão "de 1958" em "Copa do Mundo de 1958" também exerce a função sintática de adjunto adnominal do substantivo "Copa".', NULL, NULL, 'resumida', TRUE, FALSE, '5cb70757d3d24ea909c5f6445545609b42b710de82893ad53d3f634ae1a44d74', 'esa-2025-geral.txt'),
('ESA', 'Português', 'Interpretação de Texto (Humor e Ironia)', 2025, 'Prova única', 'Exército Brasileiro / ESA', 18, '18', NULL, 'facil', 'TEXTO II
[DESCRIÇÃO DA IMAGEM: Tirinha de Armandinho por Alexandre Beck.
Quadro 1: Garota fala "Ele é muito inteligente!", garoto diz "Sabe usar a caixinha de areia!".
Quadro 2: Garoto diz "E eu uso o banheiro e às vezes até dou descarga!".
Quadro 3: Garoto conclui "Devo ser um gênio!".]', 'O humor da tirinha (Texto II) se encontra na expressão:', '[{"letra": "A", "texto": "\"Caixinha de areia\"."}, {"letra": "B", "texto": "\"Às vezes\"."}, {"letra": "C", "texto": "\"Muito Inteligente\"."}, {"letra": "D", "texto": "\"Devo ser\"."}, {"letra": "E", "texto": "\"Uso o banheiro\"."}]', 'D', 'O efeito cômico da tirinha deriva da sobrevalorização de ações cotidianas simples (usar o banheiro e dar descarga), culminando no desfecho pretensioso do personagem ao utilizar a expressão modal "Devo ser" (um gênio), comparando-se de forma cômica ao gato.', 'Tirinha de Armandinho por Alexandre Beck.', NULL, 'resumida', FALSE, FALSE, '2c25337ee956fe86cd7ab20b0328e25a7be936aa481a1fc3e20cdf19f5c5be75', 'esa-2025-geral.txt'),
('ESA', 'Português', 'Sintaxe (Adjunto Adnominal e Predicativo)', 2025, 'Prova única', 'Exército Brasileiro / ESA', 19, '19', NULL, 'facil', NULL, 'Analise os trechos abaixo:
I - "Sabe usar a caixinha de areia!"
II - "Eu devo ser um gênio!"

Os termos em destaque ("de areia" e "um gênio") classificam-se, respectivamente, como:', '[{"letra": "A", "texto": "Complemento nominal e predicativo do sujeito."}, {"letra": "B", "texto": "Adjunto adnominal e predicativo do objeto."}, {"letra": "C", "texto": "Adjunto adnominal e predicativo do sujeito."}, {"letra": "D", "texto": "Complemento nominal e objeto direto."}, {"letra": "E", "texto": "Adjunto adnominal e objeto direto."}]', 'C', 'Em "caixinha de areia", o termo "de areia" especifica a matéria do substantivo concreto "caixinha", atuando como adjunto adnominal. Em "Eu devo ser um gênio!", o termo "um gênio" atribui uma característica ao sujeito "Eu" intermediado por verbo de ligação, funcionando como predicativo do sujeito.', NULL, NULL, 'resumida', FALSE, FALSE, '5d22966480361823db932f8eef873ccd6530f07370c4456857394a6b71e7f946', 'esa-2025-geral.txt'),
('ESA', 'Português', 'Interpretação de Texto (Pressuposição)', 2025, 'Prova única', 'Exército Brasileiro / ESA', 20, '20', NULL, 'facil', 'TEXTO III
FAB HOMENAGEIA AYRTON SENNA
Era uma quarta-feira, 29 de março de 1989. Amanhecia dentro das instalações do Esquadrão Jaguar (1° GDA), localizado na Base Aérea de Anápolis (BAAN). Mas, não era apenas um dia normal. Dois Mirage III do Esquadrão decolavam, com o intuito de interceptar e conduzir a aeronave PT-ASN, matrícula que referenciava as iniciais de Ayrton Senna, até o pouso seguro na BAAN. A bordo, o então campeão mundial da Fórmula 1. Naquele dia, o piloto conheceu as instalações da unidade e embarcou a bordo do Mirage III, onde realizou um voo no supersônico, inspirando brasileiros em uma data lembrada com carinho até hoje.
Ayrton Senna havia sido campeão mundial pela primeira vez em 1988. Ele estava no início da temporada de 1989 da Fórmula 1, protagonizada pelo seu duelo com Alain Prost dentro e fora das pistas. Até o precoce fim de sua carreira na categoria, ainda conquistaria mais dois títulos mundiais (1990 e 1991) e obteria números impressionantes, que fazem com que muitos especialistas o considerem, até hoje, o melhor piloto que já passou pela categoria.
Em 1987, Ayrton Senna já havia voado nas asas da FAB. Daquela vez, em um caça F-5 do Primeiro Grupo de Aviação de Caça (1° GAVCA), sobrevoou o hoje extinto Circuito de Jacarepaguá.
Homenagens
Ayrton Senna também foi condecorado pela Força Aérea Brasileira com a Medalha Mérito Santos Dumont, em 1987, e com a Medalha da Ordem do Mérito Aeronáutico, Grau Cavaleiro, em 1993.', '"(...) que fazem com que muitos especialistas o considerem, até hoje, o melhor piloto que já passou pela categoria."
Tendo em vista o trecho acima, ao analisar alguns elementos textuais de pressuposição, depreende-se que:', '[{"letra": "A", "texto": "Muitos pilotos, até hoje, em outras categorias, estão no mesmo nível que o Ayrton Senna."}, {"letra": "B", "texto": "Senna é o melhor piloto na categoria que foi específica para ele."}, {"letra": "C", "texto": "Ayrton foi o melhor na categoria, mas, nos dias atuais, já foi superado."}, {"letra": "D", "texto": "Ayrton Senna é considerado ainda o melhor piloto que passou pela categoria."}, {"letra": "E", "texto": "Os especialistas o consideraram o piloto a ser superado, em todas as categorias."}]', 'D', 'O trecho "que fazem com que muitos especialistas o considerem, até hoje, o melhor piloto que já passou pela categoria" estabelece a pressuposição de que o reconhecimento da excelência e do favoritismo de Ayrton Senna permanece inalterado ao longo do tempo.', NULL, NULL, 'resumida', FALSE, FALSE, '593e92827132122c020f9a520e414b8faf668447a6cdb9348bf3702aef7978bc', 'esa-2025-geral.txt'),
('ESA', 'Português', 'Sintaxe (Predicativo em Oração Sem Sujeito)', 2025, 'Prova única', 'Exército Brasileiro / ESA', 21, '21', NULL, 'medio', NULL, 'Em "Era uma quarta-feira", a estrutura em destaque ("uma quarta-feira") classifica-se como:', '[{"letra": "A", "texto": "Predicativo."}, {"letra": "B", "texto": "Adjunto adverbial."}, {"letra": "C", "texto": "Aposto."}, {"letra": "D", "texto": "Sujeito."}, {"letra": "E", "texto": "Adjunto adnominal."}]', 'A', 'O verbo "ser" na frase "Era uma quarta-feira" é impessoal, pois indica tempo cronológico, constituindo uma oração sem sujeito. Em orações sem sujeito construídas com o verbo ser impessoal, o termo nominal subsequente ("uma quarta-feira") desempenha a função de predicativo.', NULL, NULL, 'resumida', TRUE, FALSE, '0363a186cf2e93728d30ea1db168f77b3c3a3a5049afc36fd4cd8388f5939582', 'esa-2025-geral.txt'),
('ESA', 'Português', 'Morfossintaxe (Verbos Impessoais)', 2025, 'Prova única', 'Exército Brasileiro / ESA', 22, '22', NULL, 'facil', NULL, 'Marque a alternativa que apresenta forma verbal impessoal, a partir de trechos retirados do texto III:', '[{"letra": "A", "texto": "\"Dois Mirage III do Esquadrão decolavam com o intuito\" (linha 3)."}, {"letra": "B", "texto": "\"o então campeão mundial da Fórmula 1\" (linha 5)."}, {"letra": "C", "texto": "\"Amanhecia dentro das instalações do Esquadrão Jaguar\" (linha 1)."}, {"letra": "D", "texto": "\"onde realizou um voo no supersônico\" (linha 6)."}, {"letra": "E", "texto": "\"inspirando brasileiros\" (linha 7)."}]', 'C', 'O verbo "Amanhecer" é um verbo que exprime fenômeno meteorológico/da natureza e, utilizado em sentido denotativo ("Amanhecia dentro das instalações..."), é impessoal e não possui sujeito.', NULL, NULL, 'resumida', FALSE, FALSE, 'f4a273830461bc56f3282d00e069dedadf3e7a8db7944d51d4e110c63864207c', 'esa-2025-geral.txt'),
('ESA', 'Português', 'Morfologia (Tempos Verbais Compostos)', 2025, 'Prova única', 'Exército Brasileiro / ESA', 23, '23', NULL, 'medio', NULL, 'Na passagem do Texto III - "Em 1987, Ayrton Senna já havia voado nas asas da FAB.", a locução verbal destacada está conjugada na:', '[{"letra": "A", "texto": "Terceira pessoa do singular do pretérito perfeito composto."}, {"letra": "B", "texto": "Terceira pessoa do singular do pretérito mais-que-perfeito composto."}, {"letra": "C", "texto": "Terceira pessoa do singular do presente composto."}, {"letra": "D", "texto": "Segunda pessoa do plural do futuro do presente composto."}, {"letra": "E", "texto": "Terceira pessoa do singular do futuro do pretérito composto."}]', 'B', 'A locução verbal "havia voado" é formada pelo verbo auxiliar "haver" no Pretérito Imperfeito do Indicativo mais o particípio do verbo principal, o que constitui a conjugação no Pretérito Mais-Que-Perfeito Composto do Indicativo na 3ª pessoa do singular.', NULL, NULL, 'resumida', FALSE, FALSE, 'e6b325f60d657015d1f200a91a820a773af88f7438313898928b4d45676293d6', 'esa-2025-geral.txt'),
('ESA', 'Português', 'Sintaxe (Função do Pronome Relativo)', 2025, 'Prova única', 'Exército Brasileiro / ESA', 24, '24', NULL, 'medio', NULL, 'No trecho "onde realizou um voo no supersônico", há um pronome relativo, cuja função sintática é a de:', '[{"letra": "A", "texto": "Conectivo."}, {"letra": "B", "texto": "Advérbio de lugar."}, {"letra": "C", "texto": "Adjunto adverbial."}, {"letra": "D", "texto": "Sujeito."}, {"letra": "E", "texto": "Adjunto adnominal."}]', 'C', 'O pronome relativo "onde" retoma a ideia de lugar físico/espaço ("Mirage III / aeronave") e introduz uma oração exercendo a função sintática de adjunto adverbial de lugar do verbo "realizou".', NULL, NULL, 'resumida', TRUE, FALSE, 'd17bc44fd018f1b53de72161915aa8580c977dad08de767457d16d9fdf8cc11b', 'esa-2025-geral.txt'),
('ESA', 'Português', 'Interpretação de Texto (Análise de Canção)', 2025, 'Prova única', 'Exército Brasileiro / ESA', 25, '25', NULL, 'facil', 'TEXTO IV
CANÇÃO SARGENTO MAX WOLFF FILHO
Em mil novecentos e onze,
no interior do Paraná,
nasceu um herói de guerra
para o Brasil se orgulhar.

Fiel e audaz voluntário,
intrépido nas decisões,
o guerreiro ardoroso não teme,
cumpre sempre as suas missões.

No campo ardil da batalha,
o infante empunha o fuzil,
carrega no peito estandarte,
glória do nosso Brasil.

Deixou para nós o legado
repleto de fé e ações
do soldado até o comandante,
somos todos fiéis guardiões.

Estribilho
A Pátria enaltece
seu bravo tão querido,
sargento Max Wolff Filho,
valoroso e aguerrido!', 'Após a leitura da canção (Texto IV), observa-se que a letra tem como estratégia:', '[{"letra": "A", "texto": "Dirimir seus grandes feitos em missões de modo que o brasileiro se orgulhe de sua história."}, {"letra": "B", "texto": "Demonstrar sentimento de altivez pelo soldado renitente que deixou para nós um legado de bravura por suas ações."}, {"letra": "C", "texto": "Desestimar um herói de guerra que lutou bravamente pelo Brasil."}, {"letra": "D", "texto": "Salientar que, no campo de batalha, o guerreiro contumaz esmoreceu e teve sua memória ofuscada."}, {"letra": "E", "texto": "Retificar a importância do Sargento Max Wolff para a história do país, corroborando a ideia de que sua influência foi minimizada e de que ele não foi exemplo para todos os soldados."}]', 'B', 'A letra do hino/canção busca exalçar e enaltecer a imagem e as virtudes militares do Sargento Max Wolff Filho, valorizando seu sentimento de bravura, voluntariado e patriotismo, transmitindo um sentimento de altivez e orgulho nacional.', NULL, NULL, 'resumida', FALSE, FALSE, '3f4553d5a12ceac09fb945af6cd494204e957204f3475853654314a3b1eb511b', 'esa-2025-geral.txt'),
('ESA', 'Português', 'Morfologia (Classes de Palavras)', 2025, 'Prova única', 'Exército Brasileiro / ESA', 26, '26', NULL, 'facil', NULL, 'Na segunda estrofe do Texto IV, há o verso: "Deixou para nós o legado". Quanto à classe de palavras, "legado" classifica-se como:', '[{"letra": "A", "texto": "Adjunto adnominal."}, {"letra": "B", "texto": "Adjetivo."}, {"letra": "C", "texto": "Objeto direto."}, {"letra": "D", "texto": "Sujeito."}, {"letra": "E", "texto": "Substantivo."}]', 'E', 'No verso "Deixou para nós o legado", a palavra "legado" está antecedida pelo artigo definido "o", o que a caracteriza morfologicamente como um substantivo masculino.', NULL, NULL, 'resumida', TRUE, FALSE, 'a3a48fcabfae4a631a48b0a464aa97669b468685d47c4b72d78dab6dc80e2388', 'esa-2025-geral.txt'),
('ESA', 'Português', 'Literatura (Simbolismo - Obras)', 2025, 'Prova única', 'Exército Brasileiro / ESA', 27, '27', NULL, 'facil', NULL, 'A Escola Literária Simbolista começa a se definir com clareza a partir do ano de 1891, com o surgimento de poetas em torno do jornal carioca Folha Popular, que começou a publicar artigos de autores deste viés estético-literário. Esse movimento se consolida com o lançamento da obra:', '[{"letra": "A", "texto": "Missal e de Broquéis, de Cruz e Souza."}, {"letra": "B", "texto": "Os Sertões, de Euclides da Cunha."}, {"letra": "C", "texto": "Primeiros Sonhos, de Raimundo Correia."}, {"letra": "D", "texto": "Tratado da Metrificação, de Olavo Bilac."}, {"letra": "E", "texto": "Macunaíma, de Mário de Andrade."}]', 'A', 'O marco fundador e consolidador do Simbolismo na literatura brasileira ocorreu no ano de 1893 com a publicação simultânea dos livros de poesia "Broquéis" e de prosa poética "Missal", ambos de autoria do poeta Cruz e Sousa.', NULL, NULL, 'resumida', FALSE, FALSE, 'd20e36f1527479d4395e84fd8a6d96c0b71dfce82f92c4aa52fc692c56b31898', 'esa-2025-geral.txt'),
('ESA', 'Português', 'Literatura (Simbolismo - Características)', 2025, 'Prova única', 'Exército Brasileiro / ESA', 28, '28', NULL, 'medio', 'TEXTO V
Antífona
Formas alvas, brancas, Formas claras
de luares, de neves, de neblinas!...
Ó Formas vagas, fluidas, cristalinas...
Incensos dos turíbulos das aras...
Formas do Amor, constelarmente puras,
de Virgens e de Santas vaporosas...
Brilhos errantes, mádidas frescuras
e dolências de lírios e de rosas...
Indefiníveis músicas supremas,
harmonias da Cor e do Perfume...
Horas do Ocaso, trêmulas, extremas,
Réquiem do Sol que a Dor da Luz resume...
(...)', 'A partir da leitura do poema e ao interpretar a Escola Literária do autor Cruz e Sousa, podem-se destacar como características estéticas deste movimento:', '[{"letra": "A", "texto": "A rigorosidade aos padrões métricos e a ideia da \"arte pela arte\", com culto ao belo."}, {"letra": "B", "texto": "A busca por uma temática de caráter social e uma escrita prosaica."}, {"letra": "C", "texto": "A busca por uma literatura nacional e a valorização do regionalismo."}, {"letra": "D", "texto": "A tendência ao conceptismo e ao cultismo, com ênfase ao paradoxo e à hipérbole."}, {"letra": "E", "texto": "A musicalidade e as sugestões cromáticas e sinestésicas, com base materialista."}]', 'E', 'A estética simbolista presente no poema "Antífona" destaca-se pelo forte emprego da musicalidade, ritmo fluido, sugestões de cores (sinestesia cromática: "formas alvas, brancas") e sobreposição de sentidos (sinestesia).', NULL, NULL, 'resumida', FALSE, FALSE, '5ef828b43ed686766adcd6252249304e7fa639cb599fd9adfda61f6810b25bb6', 'esa-2025-geral.txt'),
('ESA', 'História', 'História do Brasil (Período Pré-Colonial)', 2025, 'Prova única', 'Exército Brasileiro / ESA', 29, '29', NULL, 'facil', '"Em consequência dessas informações, o governo português arrendou, por três anos, em 1502, a exploração do pau-brasil a comerciantes. A obrigação destes era construir um forte e enviar navios que explorassem anualmente trezentas léguas de litoral. Em contrapartida, tínham isenção fiscal no primeiro ano de contrato, passando a pagar 1/6 de direitos reais no segundo ano e no terceiro. Há indicações de que o sistema deu bons lucros a ambas as partes. Em 1503, o grupo comercial enviou uma segunda expedição exploradora provavelmente responsável pela fundação da feitoria de Cabo Frio, destinada à extração de pau-brasil."
(WEHLING, Arno. Formação do Brasil Colonial. Rio de Janeiro: Nova Fronteira, 1994. p. 45)', 'O sistema, estabelecido no período pré-colonial, através do qual estabeleceu-se o monopólio sobre a exploração do pau-brasil era conhecido como:', '[{"letra": "A", "texto": "Estanco."}, {"letra": "B", "texto": "Feitoria."}, {"letra": "C", "texto": "Escambo."}, {"letra": "D", "texto": "Monopsônio."}, {"letra": "E", "texto": "Sesmaria."}]', 'A', 'O arrendamento da exploração do pau-brasil a particulares (como Fernão de Loronha), no qual a Coroa mantinha o monopólio e concedia o direito de exploração mediante contrapartida fiscal e construção de feitorias, denominava-se regime de Estanco.', NULL, NULL, 'resumida', FALSE, FALSE, '54fe63fd48a72470ce67d4228910abeae7f3499e60faa468019826497f1cdb57', 'esa-2025-geral.txt'),
('ESA', 'História', 'História do Brasil (Economia Colonial)', 2025, 'Prova única', 'Exército Brasileiro / ESA', 30, '30', NULL, 'medio', '"Não é exato falar de um ciclo histórico da produção açucareira, como foi tradicional entre os historiadores. "Ciclo" dá a ideia de surgimento, ascensão e fim de uma atividade econômica, o que certamente não foi o caso do açúcar ou de outros produtos, como o café. O avanço da exploração do ouro no século XVIII, por exemplo, não significou o fim da economia açucareira. É mais adequado falar em conjunturas, ou seja, fases melhores ou piores, embora possamos dizer que, em meados do século XIX, o açúcar deixou de cumprir papel dominante na economia do país."
(FAUSTO, Boris. História do Brasil. 14ª ed. São Paulo: Editora da Universidade de São Paulo, 2024. p. 72)', 'Conforme afirmou Boris Fausto, a predominância do açúcar na economia nacional não significou a inexistência de outras atividades produtivas, em especial aquelas voltadas para o mercado interno. É neste sentido que podemos entender, por exemplo, o papel da pecuária na economia nacional. Sobre a pecuária durante o período colonial, analise as afirmativas abaixo e assinale a alternativa correta:', '[{"letra": "A", "texto": "O desenvolvimento da pecuária no Brasil esteve sempre restrito ao Centro-Sul da colônia, tendo em vista a expansão dos canaviais e o clima desfavorável em toda a Região Nordeste."}, {"letra": "B", "texto": "A Coroa portuguesa buscava estimular a criação de gado em regiões próximas às áreas litorâneas, de modo a melhorar o abastecimento e desobrigar a metrópole de enviar animais para a colônia."}, {"letra": "C", "texto": "Em todo o período colonial, a pecuária foi a atividade mais importante no território do atual estado do Rio Grande do Sul, o que levou ao surgimento ali de uma sociedade tipicamente pastoril."}, {"letra": "D", "texto": "Até fins do século XVIII, a principal finalidade da criação de gado bovino no sul do país foi a produção de leite. Foi só a partir do século XIX que se deu a expansão da produção de couro na região."}, {"letra": "E", "texto": "A indústria do charque desenvolveu-se lentamente no sul do país, tendo em vista a falta de maquinário necessário para sua produção e a baixa demanda, quadro este que só se alteraria após a metade do século XIX."}]', 'C', 'Durante o período colonial, a atividade pecuária na Região Sul (campos do Rio Grande do Sul) assumiu papel central e estruturante, propiciando o surgimento de uma formação social e cultural marcadamente pastoril vinculada às estâncias e ao tropeirismo.', NULL, NULL, 'resumida', FALSE, FALSE, '63fda504416c48490b433f8423461a9502f07278203be651e0f56620b5cf8fdb', 'esa-2025-geral.txt'),
('ESA', 'História', 'História do Brasil (Escravidão Colonial)', 2025, 'Prova única', 'Exército Brasileiro / ESA', 31, '31', NULL, 'facil', '"O elemento crucial na manufatura do açúcar foram os escravos. Suas condições de vida e trabalho são fundamentais para explicar a natureza da sociedade que se originou da economia açucareira."
(SCHWARTZ, Stuart. Segredos internos: engenhos e escravos na sociedade colonial, 1550-1835. São Paulo: Companhia das Letras, 1988. p. 122)', 'A escravidão foi uma das bases das atividades desenvolvidas durante o período colonial no Brasil, tendo deixado raízes que marcaram a sociedade brasileira mesmo após a abolição da escravatura no final do século XIX. Essa dinâmica, com o predomínio da mão de obra africana, marca um traço distintivo da colonização portuguesa. Neste sentido, diversas são as razões apontadas pelos historiadores para a escolha da mão de obra africana como base do sistema escravista colonial. Dentre os enunciados abaixo, assinale a alternativa que apresenta uma razão INCORRETA para este predomínio:', '[{"letra": "A", "texto": "Os indígenas do sexo masculino não estavam adaptados ao trabalho na lavoura, caracterizando assim uma barreira cultural difícil de ser rompida pelo colonizador."}, {"letra": "B", "texto": "Vários setores da Igreja e da Coroa opunham-se à escravização indígena, fato que não ocorria em relação aos africanos."}, {"letra": "C", "texto": "Os africanos eram naturalmente predispostos ao cativeiro, elemento tradicional de sua cultura, ao passo que os indígenas brasileiros desconheciam qualquer forma de servidão."}, {"letra": "D", "texto": "As epidemias que afetaram a população indígena ao entrarem em contato com o colonizador levou os senhores a considerarem arriscado o investimento na mão de obra nativa."}, {"letra": "E", "texto": "O tráfico negreiro gerou um lucrativo negócio cujos rendimentos iam para a metrópole, seja para os negociantes envolvidos ou seja através do pagamento de impostos à Coroa."}]', 'C', 'A afirmativa C está incorreta por atribuir aos africanos uma falsa e preconceituosa "predisposição natural ao cativeiro". A opção pelo tráfico negreiro respondeu a fatores econômicos (lucro mercantil do tráfico transatlantic), imunológicos e político-religiosos.', NULL, NULL, 'resumida', FALSE, FALSE, 'aff1263bfff00e071fd698e1026d1fdb52aa0224aed4f57261eb29f186e68441', 'esa-2025-geral.txt'),
('ESA', 'História', 'História do Brasil (Invasões Francesas)', 2025, 'Prova única', 'Exército Brasileiro / ESA', 32, '32', NULL, 'facil', '"Apesar de exaustivamente relatada em inúmeras versões a portuguesa e as francesa, católica e protestante, a invasão tem muitos pontos obscuros. Sabe-se que foi proposta pelo fidalgo e militar católico Villegaignon ao rei Henrique II, com o duplo objetivo de estabelecer o domínio francês no Brasil e servir de refúgio àqueles que quisessem afastar-se das desavenças religiosas que na França, opunham católicos e huguenotes."
(WEHLING, Arno. Formação do Brasil Colonial. Rio de Janeiro: Nova Fronteira, 1994. p. 71)', 'O trecho acima faz referência a um dos episódios de invasão por parte dos franceses ao litoral brasileiro. Dentre as afirmativas abaixo, assinale aquela que identifica corretamente o episódio tratado:', '[{"letra": "A", "texto": "O episódio em tela foi a tentativa dos franceses, comandados por Daniel de La Touche, de ocuparem a área do atual Estado do Rio Grande do Norte."}, {"letra": "B", "texto": "O relato localiza o contexto da fundação de Caiena, a partir da qual os franceses buscaram estabelecer sua presença ao norte da América do Sul, violando assim as disposições do Tratado de Tordesilhas."}, {"letra": "C", "texto": "Trata-se da invasão do Maranhão, onde os franceses tentaram organizar uma colônia chamada de \"França Equinocial\", origem da atual cidade de São Luís."}, {"letra": "D", "texto": "O trecho trata do ataque corsário de Duguay-Trouin à cidade de Olinda, em 1711."}, {"letra": "E", "texto": "Trata-se da expedição que levou à fundação da \"França Antártica\", em 1555, empreendimento que seria desbaratado na década seguinte pelos portugueses e que levaria, em 1º de março de 1565, à fundação da cidade de São Sebastião do Rio de Janeiro."}]', 'E', 'O texto faz referência explícita à tentativa de ocupação francesa comandada por Nicolas Durand de Villegaignon na Baía de Guanabara em 1555, projeto colonial conhecido como França Antártica, derrotado posteriormente pelos portugueses liderados por Estácio de Sá.', NULL, NULL, 'resumida', FALSE, FALSE, 'd1189b2b406fae43d129aa15d062ad3800f7928e74b35f57aac48b28a737a62f', 'esa-2025-geral.txt'),
('ESA', 'História', 'História do Brasil (Era Vargas e Trabalhismo)', 2025, 'Prova única', 'Exército Brasileiro / ESA', 33, '33', NULL, 'medio', NULL, 'Um dos aspectos mais marcantes do governo de Getúlio Vargas (1930-1945) foi a implementação de uma política trabalhista estruturada e intervencionista. Essa política, desenvolvida em diferentes fases ao longo da Era Vargas, representou uma ruptura com o modelo econômico liberal da Primeira República (1889-1930). Sobre a política trabalhista no governo Vargas (1930-1945), é correto afirmar que:', '[{"letra": "A", "texto": "Foi inspirada exclusivamente no modelo liberal norte-americano, priorizando a negociação direta entre patrões e empregados sem intervenção estatal."}, {"letra": "B", "texto": "Criou a Consolidação das Leis do Trabalho (CLT) em 1940, unificando a legislação trabalhista da Primeira República com a criada durante o Estado Novo (1937-1945) garantindo direitos como salário mínimo e férias remuneradas."}, {"letra": "C", "texto": "Constitui um nítido exemplo de uma ampla iniciativa que não derivou das pressões das classes sociais, mas sim da ação centralizadora e intervencionista do Estado."}, {"letra": "D", "texto": "Manteve-se inalterada durante todo o Estado Novo (1937-1945), sem novas leis ou intervenções governamentais."}, {"letra": "E", "texto": "Teve como principal característica a eliminação de qualquer forma de regulamentação do trabalho industrial."}]', 'C', 'A política trabalhista da Era Vargas (1930-1945) caracterizou-se pela forte tutela e cooptação do Estado sobre a classe trabalhadora (trabalhismo), originando direitos e regulamentações outorgados diretamente pelo poder central de forma intervencionista.', NULL, NULL, 'resumida', FALSE, FALSE, '5d22c36b97ccec5cd3a9a6bb7bb497dae58375ad9f29949c3d1d9f49f0a63f03', 'esa-2025-geral.txt'),
('ESA', 'História', 'História do Brasil (Organização Militar)', 2025, 'Prova única', 'Exército Brasileiro / ESA', 34, '34', NULL, 'medio', '"Não delegava a Coroa aos donatários apenas poderes civis, tão amplos que Varnhagen os chamou de majestático, delegava ainda o ônus da defesa, e por isso mesmo o donatário era, a um tempo, governador e capitão [...] Mas no Foral dispunha taxativamente: ''os moradores e povoadores e povo da dita capitania serão obrigados em tempo de guerra a servir nela com o capitão se lhe necessário for.'' Permitia, assim, ao donatário, o exercício do poder militar e o título de comandante, enquanto colocava às suas ordens os povoadores, obrigados a servi-lo e a reconhece-lo como chefe, ao mesmo tempo em que permitia a entrada de instrumentos necessários à luta militar, as armas e munições, e ainda o tráfico delas, com a reserva de que isso só ocorresse entre cristãos e súditos do reino, o que vedava o comércio de armas com os indígenas, objeto, como se verá, de constantes cuidados e discriminações nesse sentido."
(SODRÉ, Nelson Werneck. História Militar do Brasil. 2ª ed. São Paulo: Expressão Popular, 2010. p.28)', 'O primeiro sistema de administração do Brasil Colonial foi o chamado sistema de Capitanias Hereditárias. Este sistema conferia à empresa colonizadora o caráter de empreendimento privado amplos poderes eram cedidos aos donatários, que os exerciam em nome da Coroa, em troca da assunção por estes dos riscos e gastos necessários. O fracasso desse sistema, porém, levaria o governo português a centralizar a administração o que também afetou a organização da defesa da colônia. Sobre a organização militar no período colonial, assinale a afirmativa correta:', '[{"letra": "A", "texto": "As primeiras feitorias não apresentavam caráter militar, estando desprotegidas e vulneráveis. Esta situação permaneceria até o período pombalino, quando a Coroa deu início então a um amplo programa de construção de fortes junto aos centros urbanos da colônia."}, {"letra": "B", "texto": "As tropas de linha, também conhecidas como terços, eram comandadas por um oficial civil, escolhido pelo governador segundo prestígio e riqueza, e não remunerados."}, {"letra": "C", "texto": "As milícias eram tropas regulares e profissionais em armas, sendo na maioria das vezes compostas por mercenários estrangeiros."}, {"letra": "D", "texto": "As ordenanças eram compostas por toda a população masculina em condições físicas e idade militar, convocadas quando necessário."}, {"letra": "E", "texto": "Em 1692, a preocupação com a defesa da colônia levou à fundação, em Salvador, da Real Academia de Artilharia, Fortificação e Desenho."}]', 'D', 'No sistema defensivo e militar do Brasil Colonial, as Ordenanças constituíam forças de 3ª linha integradas por todos os homens livres em idade militar (entre 18 e 60 anos) não engajados nas tropas de linha ou milícias, convocados em situações pontuais de emergência.', NULL, NULL, 'resumida', FALSE, FALSE, 'f0bd88d11321141e4d3b8b1703363f101780572ef604f3ef014bc8c4695f7352', 'esa-2025-geral.txt'),
('ESA', 'História', 'Geografia do Brasil (Industrialização)', 2025, 'Prova única', 'Exército Brasileiro / ESA', 35, '35', NULL, 'facil', 'ECONOMIA
Brasil ganha nova política industrial com metas para o desenvolvimento até 2033
Inovação e sustentabilidade estão no centro da Nova Indústria Brasil, que definiu áreas estratégicas para investimento de acordo com o potencial impacto no desenvolvimento social e econômico do País.', 'Com a nova política industrial, o Brasil dá um passo decisivo em direção à neoindustrialização, a indústria ainda enfrenta, porém, vários problemas que aumentam os custos e dificultam a maior participação no mercado externo, entre eles:
1. Flutuação cambial;
2. Problemas logísticos;
3. Barreiras tarifárias e não tarifárias; e
4. Falta de qualificação da força de trabalho.

Está correto o contido em:', '[{"letra": "A", "texto": "2 e 3, apenas."}, {"letra": "B", "texto": "2 e 4, apenas."}, {"letra": "C", "texto": "1, 2 e 4, apenas."}, {"letra": "D", "texto": "1, 3 e 4, apenas."}, {"letra": "E", "texto": "Todas estão corretas."}]', 'E', 'A indústria brasileira enfrenta gargalos estruturais recorrentes denominados "Custo Brasil", que abrangem exatamente a instabilidade cambial, gargalos na infraestrutura logística, protecionismo/barreiras tarifárias e o déficit de qualificação da mão de obra.', NULL, NULL, 'resumida', FALSE, FALSE, '9d806418d3cdbdc5f53b279c90a14301a104ec60320ccfb614893886056e1241', 'esa-2025-geral.txt'),
('ESA', 'História', 'Geografia do Brasil (Divisão Regional)', 2025, 'Prova única', 'Exército Brasileiro / ESA', 36, '36', NULL, 'medio', 'O Brasil, país de extensão e diversidade geográfica continental, expressa o dilema da regionalização em múltiplas escalas. Jamais podemos ignorar que as regionalizações são sempre historicamente datadas, assim como as periodizações têm sua validade regionalmente delimitada, pois nunca podem ser amplamente generalizadas.
HAESBAERT, Rogério. Regionalizações brasileiras: antigos legados e novos desafios.', 'Diante do exposto e sobre os seus conhecimentos de divisão regional, assinale com "V" (verdadeiro) ou com "F" (falso) as seguintes afirmações:
I - A mais conhecida das divisões regionais do Brasil é a divisão oficial do IBGE, que estabeleceu pela primeira vez as cinco macrorregiões, na década de 1990. Nasce o Sudeste, com SP e RJ sendo agrupadas a MG e ES. O Nordeste com a presença do TO, BA e MA. Todo o território de Goiás, pertencente ao Centro-Oeste e por fim as regiões Norte e Sul, existentes desde a década de 1940. ( )
II - O foco da proposta de regionalização do Geógrafo Pedro Pinchas Geiger é de formação do território brasileiro e a integração nacional a partir da industrialização. Por isso é uma das regionalizações oficiais do Brasil como a mais assertiva do país. É bastante rigorosa do ponto de vista científico e dos limites estaduais. ( )
III - Outra regionalização do espaço brasileiro é a que reconhece em três grandes complexos e/ou unidades regionais, também conhecida como regiões geoeconômicas: a Amazônia, o Centro-Sul e o Nordeste. ( )

A sequência correta de preenchimento dos parênteses das afirmativas I, II e III, respectivamente, é:', '[{"letra": "A", "texto": "F, V, F."}, {"letra": "B", "texto": "F, F, V."}, {"letra": "C", "texto": "V, F, V."}, {"letra": "D", "texto": "V, V, F."}, {"letra": "E", "texto": "Todas são falsas."}]', 'B', 'I. Falsa: a divisão regional oficial em 5 macrorregiões foi estabelecida pelo IBGE na década de 1960/1970 (e não 1990).
II. Falsa: a divisão geoeconômica de Pedro Geiger não respeita os limites estaduais e não é a divisão oficial do IBGE.
III. Verdadeira: a divisão geoeconômica divide o país em Amazônia, Centro-Sul e Nordeste.
Sequência: F, F, V.', NULL, '[{"titulo": "Passo 1", "conteudo": "I. Falsa: a divisão regional oficial em 5 macrorregiões foi estabelecida pelo IBGE na década de 1960/1970 (e não 1990).", "formula": null}, {"titulo": "Passo 2", "conteudo": "II. Falsa: a divisão geoeconômica de Pedro Geiger não respeita os limites estaduais e não é a divisão oficial do IBGE.", "formula": null}, {"titulo": "Conclusão", "conteudo": "III. Verdadeira: a divisão geoeconômica divide o país em Amazônia, Centro-Sul e Nordeste. Sequência: F, F, V.", "formula": null}]', 'automatica', FALSE, FALSE, '8d51925015440d4cc0d8164677450c45d56928308babc8e0ad8b8641f4ac7661', 'esa-2025-geral.txt'),
('ESA', 'História', 'Geografia do Brasil (Estatuto da Cidade)', 2025, 'Prova única', 'Exército Brasileiro / ESA', 37, '37', NULL, 'facil', '[DESCRIÇÃO DA IMAGEM: Recrutinha e Olivinha em quadrinho educativo sobre o meio ambiente falando sobre poluição nos rios, esgotos de casas e indústrias.]', 'O personagem Recrutinha aponta um problema ambiental recorrente em áreas urbanas. Contudo, afim de assegurar o bem estar geral, de modo a preservar o meio ambiente, promover qualidade de vida para a população e garantir desenvolvimento urbano sustentável para a cidade, em 10 de julho de 2001, foi sancionado um documento que regulamentou itens de política urbana que constam da Constituição de 1988, denominado de:', '[{"letra": "A", "texto": "Plano Gerenciador Ambiental."}, {"letra": "B", "texto": "Lei de Zoneamento Urbano."}, {"letra": "C", "texto": "Lei do Parcelamento do Solo Urbano."}, {"letra": "D", "texto": "Lei do Perímetro Urbano."}, {"letra": "E", "texto": "Estatuto da Cidade."}]', 'E', 'A Lei nº 10.257, sancionada em 10 de julho de 2001, é denominada Estatuto da Cidade. Ela regulamenta os artigos 182 e 183 da Constituição Federal de 1988, estabelecendo diretrizes gerais da política urbana e instrumentos de gestão sustentável das cidades.', 'Recrutinha e Olivinha em quadrinho educativo sobre o meio ambiente falando sobre poluição nos rios, esgotos de casas e indústrias.', NULL, 'resumida', FALSE, FALSE, 'efb5bdac264c552074042a26eb372681a8bb1ecd6852c6b08421bfd7f74f7f68', 'esa-2025-geral.txt'),
('ESA', 'História', 'Geografia do Brasil (Domínios Morfoclimáticos)', 2025, 'Prova única', 'Exército Brasileiro / ESA', 38, '38', NULL, 'facil', NULL, 'As faixas de transição funcionam como extensos corredores que se interpõem entre as áreas nucleares dos domínios morfoclimáticos. Qual das alternativas abaixo são faixas de transição?', '[{"letra": "A", "texto": "Mata dos Cocais e Pantanal Mato-Grossense."}, {"letra": "B", "texto": "Manguezais e Mata das Araucárias."}, {"letra": "C", "texto": "Pantanal Mato-Grossense e Pradarias."}, {"letra": "D", "texto": "Mata das Araucárias e Mata dos Cocais."}, {"letra": "E", "texto": "Cerrado e Pradarias."}]', 'A', 'Segundo a classificação dos domínios morfoclimáticos de Aziz Ab''Sáber, a Mata dos Cocais (transição entre a Amazônia e a Caatinga) e o Pantanal Mato-Grossense (transição entre o Cerrado, a Amazônia e o Chaco) são consideradas as principais faixas de transição do Brasil.', NULL, NULL, 'resumida', FALSE, FALSE, '3bb10517c2adc28f6d32f63d17fa7dd76df6e22288cc1428ad70b8ce4550bb81', 'esa-2025-geral.txt'),
('ESA', 'História', 'Geografia do Brasil (Matriz Energética)', 2025, 'Prova única', 'Exército Brasileiro / ESA', 39, '39', NULL, 'facil', NULL, 'O Brasil, por motivos diferentes, também apresenta uma das matrizes energéticas mais limpas do mundo. A respeito dessa afirmação, julgue os itens abaixo:
I. O país desenvolveu estratégias baseadas na exploração intensa de seus vastos recursos hídricos para a geração de eletricidade.
II. A produção comercial de biocombustíveis teve o Programa Nacional do Álcool (Proálcool) como tentativa de amenizar a dependência do Brasil em relação ao petróleo.
III. As usinas hidrelétricas, que têm a menor capacidade instalada de produção do país, produzem energias mais caras e com mais impactos ambientais, quando comparadas às usinas termelétricas e termonucleares.
IV. A instalação de termelétricas visa diversificar a matriz energética brasileira e evitar novas crises em várias regiões.

Marque a alternativa correta:', '[{"letra": "A", "texto": "I, II e IV, apenas."}, {"letra": "B", "texto": "I, apenas."}, {"letra": "C", "texto": "III, apenas."}, {"letra": "D", "texto": "I e IV, apenas."}, {"letra": "E", "texto": "II e III, apenas."}]', 'A', 'As afirmativas I, II e IV estão corretas. A afirmativa III é incorreta porque a energia hidrelétrica representa a MAIOR parcela da capacidade instalada do país e apresenta custo operacional de geração mais barato em relação às usinas termelétricas.', NULL, NULL, 'resumida', FALSE, FALSE, '87b8ab5e6a5c6aac582c6913a4f85692f0809eb5dc7b2c0986f298d3edebeb4a', 'esa-2025-geral.txt'),
('ESA', 'História', 'Geografia do Brasil (Unidades de Conservação)', 2025, 'Prova única', 'Exército Brasileiro / ESA', 40, '40', NULL, 'facil', 'As atividades de caminhada e escalada no Parque Nacional do Itatiaia (PNI), são eventos turísticos tradicionais naquele maciço. Nos últimos anos essas atividades vêm sendo adequadas à realidade de uma Unidade de Conservação (UC) em conjunto com a equipe do parque e a Câmara Técnica de Montanhismo e Ecoturismo (CTME). Para isso, desde 2007, o parque conta com as "Regras para o uso daquele Planalto", que vêm sendo aprimoradas anualmente. [...]', 'Como parte dessa formação, servidores do PNI e o Coordenador da CTME ministraram palestra, na qual a melhor definição para o parque nacional foi destacado como:', '[{"letra": "A", "texto": "Uma estação ecológica destinada à preservação integral dos atributos naturais existentes em seus limites, sem interferência humana direta."}, {"letra": "B", "texto": "Uma reserva biológica destinada à pesquisa científica. É vedada à visitação pública, exceto para atividade educacional."}, {"letra": "C", "texto": "Um refúgio da vida silvestre destinado a manter os ecossistemas naturais em áreas relativamente reduzidas, com pouca ocupação humana."}, {"letra": "D", "texto": "Uma área de relevante interesse ecológico destinada a proteger ambientes naturais nos quais se assegurem a existência e a reprodução de espécies da flora e da fauna."}, {"letra": "E", "texto": "Uma categoria destinada à preservação de ecossistemas naturais de grande beleza cênica. Deve ser aberto à visitação pública, mas de acordo com as normas do plano de manejo."}]', 'E', 'Conforme o Sistema Nacional de Unidades de Conservação (SNUC - Lei 9.985/2000), o Parque Nacional é uma Unidade de Proteção Integral cujo objetivo é a preservação de ecossistemas naturais de grande relevância ecológica e beleza cênica, sendo permitida a visitação pública condicionada ao Plano de Manejo.', NULL, NULL, 'resumida', FALSE, FALSE, 'e37f7b8b9085e510a21647f50ba9120c405632ce779e5a6242d5c9b3d3be7ae4', 'esa-2025-geral.txt'),
('ESA', 'Inglês', 'Compreensão de Texto e Coesão', 2025, 'Prova única', 'Exército Brasileiro / ESA', 41, '41', NULL, 'medio', 'Insert detached sentences 1, 2, 3, 4 and 5 into the right gaps of the text. The parentheses ( ) show where the gaps are in the text.

DETACHED SENTENCES
1. This firepower increases the Army''s ability to engage in fight, provide fire support to ground forces, and suppress enemy positions effectively
2. This has proven instrumental in saving lives during natural disasters, assisting civil authorities in emergency situations, and supporting humanitarian missions
3. In summary, the Brazilian Army''s adoption of the Sikorsky UH-60 Black Hawk helicopters has revolutionized its operational capabilities
4. This capability supports the Brazilian Army''s tactical and logistical needs with rapid deployment of troops, equipment, and supplies to any location across the country, including remote and inaccessible areas
5. Brazil''s vast and varied landscape encompasses dense jungles, rugged mountains, and extensive coastlines

THE BLACK HAWK IN THE BRAZILIAN ARMY AVIATION
The Brazilian Army has successfully incorporated the use of the Sikorsky UH-60 Black Hawk helicopters into its operations. This versatile aircraft has proven to be a game-changer, enhancing the Army''s capabilities across various missions and improving the efficiency of its operations.
One of the key advantages of the Black Hawk is its ability to operate in diverse terrains and challenging conditions. ( ). The Black Hawk can navigate with its powerful engines through these different environments. The Black Hawk has demonstrated its agility in Brazil''s diverse terrains performing close air support, troop transport, or search and rescue missions.
The helicopter''s capacity to carry personnel and cargo is impressive. With its spacious cabin, the Black Hawk can transport 11 equipped soldiers or carry a payload of 2,600 kilograms. ( ).
Furthermore, the Black Hawk''s advanced weapon systems and communication equipment enhance the Brazilian Army''s combat capabilities. Armed variants of the helicopter can carry and deploy machine guns, rockets, and guided missiles. ( ). Moreover, the integration of modern communication systems ensures seamless coordination between the helicopter crew and ground units, improving situational awareness and mission success.
The use of Black Hawk helicopters has also significantly enhanced the Brazilian Army''s search and rescue capabilities. Equipped with advanced sensor systems and night-vision technology, the aircraft can conduct rescue operations in adverse weather conditions, during night-time hours, and in remote areas, where traditional means are often insufficient. ( ).
( ). Its versatility, cargo capacity, firepower, and search and rescue capabilities have proved invaluable in a variety of missions. The Black Hawk''s integration into the Army''s fleet has strengthened its ability to defend the nation, support peacekeeping efforts, and effectively respond to threats and emergencies, making it an indispensable asset for the Brazilian military.', 'Choose the correct sequence of sentences to fill in the gaps in the text:', '[{"letra": "A", "texto": "5 - 4 - 1 - 2 - 3"}, {"letra": "B", "texto": "3 - 2 - 1 - 4 - 5"}, {"letra": "C", "texto": "5 - 3 - 1 - 2 - 4"}, {"letra": "D", "texto": "5 - 4 - 2 - 1 - 3"}, {"letra": "E", "texto": "1 - 2 - 4 - 5 - 3"}]', 'A', 'A ordem correta dos parágrafos atende à coesão textual:
- Parágrafo 1: lacuna preenchida pela frase 5 (descreve a geografia diversificada do Brasil).
- Parágrafo 2: lacuna preenchida pela frase 4 (detalha a capacidade de transporte e logística).
- Parágrafo 3: lacuna preenchida pela frase 1 (explica o poder de fogo dos sistemas de armas).
- Parágrafo 4: lacuna preenchida pela frase 2 (trata de missões de busca e salvamento).
- Parágrafo 5: lacuna preenchida pela frase 3 (conclusão resumitiva).
Sequência: 5-4-1-2-3.', NULL, NULL, 'resumida', FALSE, FALSE, '419b2fc2d1ba986eb3adb66ceb0a26c547303c5c90cc2c5cedacf57a716e43ea', 'esa-2025-geral.txt'),
('ESA', 'Inglês', 'Gramática (Graus dos Adjetivos)', 2025, 'Prova única', 'Exército Brasileiro / ESA', 42, '42', NULL, 'medio', 'Drill Sergeant Mendonça barked orders to the Signal Corps students like a mad dog. Today''s training was (demanding) than yesterday''s, pushing the will-be NCO''s to their limits. The Signal Corps students are sure they are the (smart) bunch in academic disciplines, but they also needed to excel in their physical training. Mendonça, (mean) as a rattlesnake, kept reminding them of the consequences of failing the fitness test.
The obstacle course was the (bad) of all the exercises. They climbed walls, slogged through mud, and crawled under barbed wire, sweating like pigs. By lunchtime, they were exhausted and (hungry) than wolves. Sergeant Mendonça, however, would not let us rest. "This is not a picnic, gentlemen!" he yelled. The NCO academy is not for the faint of heart in fact, but the students are determined to make it.', 'Choose the correct statement considering the underlined adjectives in the text and their correct degrees according to the context:', '[{"letra": "A", "texto": "The correct form of \"smart\" is \"the most smart\"."}, {"letra": "B", "texto": "\"The worse\" is the right form for \"bad\"."}, {"letra": "C", "texto": "\"Demanding\" becomes \"most demanding\" in the context."}, {"letra": "D", "texto": "\"Hungryer\" is the correct form for \"hungry\"."}, {"letra": "E", "texto": "The correct form of the adjective \"mean\" is \"as mean\"."}]', 'E', 'No trecho "Mendonça, (mean) as a rattlesnake", a estrutura exige a igualdade comparativa "as mean as" (tão maldoso quanto uma cascavel), tornando a afirmativa E correta. As demais formas apresentadas nas alternativas incorrem em erros gramaticais de flexão de adjetivos.', NULL, NULL, 'resumida', TRUE, FALSE, '4b8c5f843624ad5015bdb75edfa326028742b91a66ce0acd4d8303db92489361', 'esa-2025-geral.txt'),
('ESA', 'Inglês', 'Compreensão de Texto (Interpretação)', 2025, 'Prova única', 'Exército Brasileiro / ESA', 43, '43', NULL, 'facil', 'Soccer is the national sport of Brazil. The Brazilian passion for the game leads many observers to describe it as more of a religion than a sport for Brazilians. Intense and often fanatical support of the national team is a force that serves to bridge Brazil''s ethnic and class divisions. Its national team is the only team that has played in all nineteen World Cup competitions, the sport''s highest level of international play that are held every four years. Brazil is also the only team to win the tournament five times. Males of all classes and backgrounds play soccer. Its popularity stems partly from its limited equipment demands. The poorest of youth play in the streets because soccer requires just a ball (or even a makeshift ball) and some open space. Peladas, or pick-up games, are common occurrences, especially on Sundays. For spectators, national team games draw the attention of the entire nation. Work essentially halts while Brazilians gather to watch the game in homes, offices, bars, and other venues. Wins in international competition can lead to nationwide partying and parades; losses can lead to widespread disappointment and national debate concerning the team''s performance and future.', 'Read the text about soccer in Brazil and choose the FALSE statement:', '[{"letra": "A", "texto": "Soccer has a nearly sacred aura in the Brazilian society."}, {"letra": "B", "texto": "People from the upper middle class do not root for the national team."}, {"letra": "C", "texto": "The national team never failed to qualify for a World Cup."}, {"letra": "D", "texto": "Soccer is an accessible sport to the impoverished."}, {"letra": "E", "texto": "The national team''s results interest Brazilians nationwide."}]', 'B', 'O texto afirma que o futebol no Brasil une todas as classes e origens sociais ("serves to bridge Brazil''s ethnic and class divisions"). Deste modo, a afirmativa B ("People from the upper middle class do not root for the national team") é falsa e incorreta em relação ao texto.', NULL, NULL, 'resumida', FALSE, FALSE, '3ebec9fa4a42ae4950a6a44d8ee8f97bb810648df8d4d15c4b35bf3abfb411c4', 'esa-2025-geral.txt'),
('ESA', 'Inglês', 'Interpretação de Cartuns', 2025, 'Prova única', 'Exército Brasileiro / ESA', 44, '44', NULL, 'facil', '[DESCRIÇÃO DA IMAGEM: Tirinha do Recruta Zero (Beetle Bailey).
Quadro 1: Recruta diz na cama "I can''t do the hike today", Sargento responde de braços cruzados "What''s your excuse this time?".
Quadro 2: Recruta fala "I lost my other sock in the laundry", enquanto o Sargento o encara irritado.]', 'Which option has the correct statement about what is going on in the comic strip?', '[{"letra": "A", "texto": "The Private has not avoided putting in some physical effort."}, {"letra": "B", "texto": "The Private has not given the Sergeant a lousy excuse."}, {"letra": "C", "texto": "The Private has hurt his foot."}, {"letra": "D", "texto": "The Private''s behavior has pleased the Sergeant."}, {"letra": "E", "texto": "The Private has slacked on his duties."}]', 'E', 'Na tirinha do Beetle Bailey (Recruta Zero), o recruta inventa a desculpa fútil de ter perdido a outra meia na lavanderia para não fazer a marcha militar, evidenciando que ele está se esquivando de suas obrigações militares ("slacked on his duties").', 'Tirinha do Recruta Zero (Beetle Bailey).', NULL, 'resumida', FALSE, FALSE, '15c5707261c8bc1af4099f05f827778e06bf572f3b0b923a9f378f44f6b868f2', 'esa-2025-geral.txt'),
('ESA', 'Inglês', 'Compreensão de Texto (Vocabulário Militar)', 2025, 'Prova única', 'Exército Brasileiro / ESA', 45, '45', NULL, 'medio', 'Now the platoon commander of No 3 Platoon is briefing his section commanders:
''Pay attention and take notes. The Company Commander is not happy with the standard of map reading. So, next Tuesday, 26th October, the whole platoon is going out on a 24-hour exercise, Exercise "Hot Foot". The aim of the exercise is to give the platoon practice in compass marching across country. You will move by day and night. The dress for the exercise will be fighting order. You will not carry weapons and ammunition. You are to draw combat rations for your sections from the stores. Do this at 1600 hours on Monday 25th October. Individuals will be responsible for their own meals during the exercise. Each man is to take a protractor, a compass, map sheet 175, map-case, torch and chinagraph pencils. You are responsible for checking this. The platoon is to parade outside the guardroom at 0730 hours on Tuesday 26th October. We shall travel to the exercise area by 4-tonner but we shall march back to camp. Estimated time of return to camp will be 1030 hours on Wednesday 27th October. Make sure you brief your sections. Right, that''s all. Any questions?''', 'Read the text about a military briefing and choose the FALSE statement:', '[{"letra": "A", "texto": "The platoon will carry out the activity unarmed."}, {"letra": "B", "texto": "The platoon will retrieve their food prior to the exercise."}, {"letra": "C", "texto": "The platoon will measure angles during the exercise."}, {"letra": "D", "texto": "The platoon will perform the exercise both in daylight and at nighttime."}, {"letra": "E", "texto": "The platoon will return to camp on a military vehicle."}]', 'E', 'A afirmativa E é falsa em relação ao texto porque o comandante instrui claramente que o pelotão retornará ao acampamento marchando a pé ("we shall march back to camp"), e não em um veículo militar.', NULL, NULL, 'resumida', FALSE, FALSE, '141b92c17e0f33eb3dae3487856ce1c8d2542850da3af3423bff8c623d9228de', 'esa-2025-geral.txt'),
('ESA', 'Inglês', 'Gramática (Ordem dos Advérbios)', 2025, 'Prova única', 'Exército Brasileiro / ESA', 46, '46', NULL, 'medio', 'Structure the sentence by matching the adverbs and adverbial phrases with the positions in the sentence:
"The NCO Academy students [A] march [B] [C] [D] [E]"

Adverbs:
1. on the parade ground
2. proudly
3. on Independence Day
4. very
5. always', 'Choose the correct order of the adverbs in the sentence:', '[{"letra": "A", "texto": "A-5, B-4, C-2, D-3, E-1"}, {"letra": "B", "texto": "A-5, B-4, C-1, D-2, E-3"}, {"letra": "C", "texto": "A-5, B-4, C-2, D-1, E-3"}, {"letra": "D", "texto": "A-5, B-2, C-4, D-1, E-3"}, {"letra": "E", "texto": "A-4, B-5, C-2, D-1, E-3"}]', 'C', 'A ordem padrão dos advérbios na frase em inglês segue a estrutura: Sujeito + Advérbio de Frequência [A: always] + Verbo (march) + Advérbio de Intensidade [B: very] + Advérbio de Modo [C: proudly] + Advérbio de Lugar [D: on the parade ground] + Advérbio de Tempo [E: on Independence Day]. Sequência: A-5, B-4, C-2, D-1, E-3.', NULL, '[{"titulo": "Passo 1", "conteudo": "A ordem padrão dos advérbios na frase em inglês segue a estrutura: Sujeito + Advérbio de Frequência [A: always] + Verbo (march) + Advérbio de Intensidade [B: very] + Advérbio de Modo [C: proudly] + Advérbio de Lugar [D: on the parade ground] + Advérbio de Tempo [E: on Independence Day].", "formula": null}, {"titulo": "Conclusão", "conteudo": "Sequência: A-5, B-4, C-2, D-1, E-3.", "formula": null}]', 'automatica', FALSE, FALSE, 'f788bb8321d92db8b65216b241abc30f02b84ec8aee358811dae484bcae3c14f', 'esa-2025-geral.txt'),
('ESA', 'Inglês', 'Gramática (Gerúndio e Infinitivo)', 2025, 'Prova única', 'Exército Brasileiro / ESA', 47, '47', NULL, 'medio', 'NCO Academy student: Good morning, Sir.
Sergeant Major: Why are you awake in uniform so early? Today is your day off. You can (sleep) until seven o''clock today. It''s worth (stay) in bed a little longer to recover from the exhausting week.
NCO Academy student: I enjoy (learn) foreign languages, so I woke up early (study) English.
Sergeant Major: I''m really proud of (see) you working so hard.', 'Choose the correct use of the infinitive or gerund to complete the dialogue:', '[{"letra": "A", "texto": "You can to sleep until seven o''clock."}, {"letra": "B", "texto": "It''s worth to stay in bed a little bit longer."}, {"letra": "C", "texto": "I enjoy learning foreign languages."}, {"letra": "D", "texto": "I woke up early learning English."}, {"letra": "E", "texto": "I''m really proud of to see you working hard."}]', 'C', 'O verbo "enjoy" exige obrigatoriamente o verbo seguinte na forma do gerúndio (-ing). Portanto, a estrutura "I enjoy learning foreign languages" na alternativa C está perfeitamente correta.', NULL, '[{"titulo": "Passo 1", "conteudo": "O verbo \"enjoy\" exige obrigatoriamente o verbo seguinte na forma do gerúndio (-ing).", "formula": null}, {"titulo": "Conclusão", "conteudo": "Portanto, a estrutura \"I enjoy learning foreign languages\" na alternativa C está perfeitamente correta.", "formula": null}]', 'automatica', FALSE, FALSE, '78be9ea60ab3a2a37db9129b81b16159ecd403fb069c11b2f2014a1222a64009', 'esa-2025-geral.txt'),
('ESA', 'Inglês', 'Gramática (Tempos Verbais e Passiva)', 2025, 'Prova única', 'Exército Brasileiro / ESA', 48, '48', NULL, 'medio', 'TEXT 1
Brazil Armed Forces launch border patrol operation
Nearly 30 thousand soldiers have been engaged

The Brazilian Armed Forces HAVE INITIATED an operation named Agatha 8 in an attempt to clamp down on crimes and irregularities that take place on national borders. This year, due to the World Cup, the measure will encompass the full length of the borders, which total over 16.8 thousand km.
Approximately 30 thousand soldiers from the Brazilian Army, Navy and Air Force, WERE SELECTED to take part in the operation, which began on Saturday (May 10). In addition, agents from the Federal Police, the Federal Highway Police and the Military Police are also employed in the states covered. Other professionals ENGAGED in the action are those from such governmental agencies as the Federal Revenue Office, the Brazilian Intelligence Agency ("Abin"), and the National Civil Aviation Agency ("Anac"). Their focus is placed on the crimes most commonly committed at the national border, such as the trafficking of drugs and weapons, smuggling, environmental crimes, illegal immigration and mining.
According to the press office of the Ministry of Defense, no date HAS BEEN SCHEDULED for the end of the operation, as it depends on the outcomes of the patrols.
Operation Agatha 8 is part of a measure called Strategic Plan for Frontiers, CREATED by the federal government in 2011. Before the plan WAS INITIATED, the Brazilian government MAINTAINED contact with its ten neighbors so as to keep them informed of the employment of its military forces.', 'Analyze the statements about the fragments in uppercase letters in Text 1, then choose the correct option:
I - All of the fragments in uppercase letters are examples of the Simple Past tense.
II - All of the fragments in uppercase letters refer to past actions in some way.
III - In "have initiated", the verb tense refers to a recent action at the time the news was written.
IV - None of the fragments in uppercase letters contain a past participle form.
V - The verb "created" is used in this verb tense because it refers to a past action in a specific time.', '[{"letra": "A", "texto": "All statements are true."}, {"letra": "B", "texto": "Only statements II and III are true."}, {"letra": "C", "texto": "Only one statement is false."}, {"letra": "D", "texto": "All statements are false."}, {"letra": "E", "texto": "Only statements I and IV are false."}]', 'E', 'As afirmativas I e IV são falsas, pois o texto contém formas no Present Perfect ("have initiated") e na Voz Passiva contendo particípio passado ("were selected", "created", "was initiated"). Portanto, apenas I e IV são incorretas.', NULL, '[{"titulo": "Passo 1", "conteudo": "As afirmativas I e IV são falsas, pois o texto contém formas no Present Perfect (\"have initiated\") e na Voz Passiva contendo particípio passado (\"were selected\", \"created\", \"was initiated\").", "formula": null}, {"titulo": "Conclusão", "conteudo": "Portanto, apenas I e IV são incorretas.", "formula": null}]', 'automatica', FALSE, FALSE, '7d2269780105c0583398db1284f9ece53e6c8393816278ed6f826140facc1390', 'esa-2025-geral.txt'),
('ESA', 'Inglês', 'Gramática (Preposições)', 2025, 'Prova única', 'Exército Brasileiro / ESA', 49, '49', NULL, 'facil', NULL, 'The underlined words in Text 1 are prepositions. About this topic, judge the statements below as true (T) or false (F):
I) The preposition "from" in the second paragraph indicates origin or source. ( )
II) The preposition "in" in the second paragraph is also used for cities and countries. ( )
III) The preposition "on" in the second paragraph is also used for seasons and months. ( )
IV) The preposition "in" in the fourth paragraph is also used for days of the week. ( )
V) The fragment "depends on" in the third paragraph could correctly be replaced with "depends of". ( )

Choose the correct sequence:', '[{"letra": "A", "texto": "T - T - F - F - T"}, {"letra": "B", "texto": "T - T - F - F - F"}, {"letra": "C", "texto": "T - T - T - T - T"}, {"letra": "D", "texto": "F - F - T - F - F"}, {"letra": "E", "texto": "T - F - F - F - T"}]', 'B', 'I) "from" indica origem (Verdadeiro - T).
II) "in" é usada para cidades e países (Verdadeiro - T).
III) "on" não é usada para meses e estações (usa-se "in") (Falso - F).
IV) "in" não é usada para dias da semana (usa-se "on") (Falso - F).
V) A regência do verbo depender exige a preposição "on" ("depends on"), não existindo a forma "depends of" (Falso - F).
Sequência: T - T - F - F - F.', NULL, '[{"titulo": "Passo 1", "conteudo": "I) \"from\" indica origem (Verdadeiro - T). II) \"in\" é usada para cidades e países (Verdadeiro - T).", "formula": null}, {"titulo": "Passo 2", "conteudo": "III) \"on\" não é usada para meses e estações (usa-se \"in\") (Falso - F). IV) \"in\" não é usada para dias da semana (usa-se \"on\") (Falso - F).", "formula": null}, {"titulo": "Conclusão", "conteudo": "V) A regência do verbo depender exige a preposição \"on\" (\"depends on\"), não existindo a forma \"depends of\" (Falso - F). Sequência: T - T - F - F - F.", "formula": null}]', 'automatica', FALSE, FALSE, 'c4ddc8d70e5be1e748306282d6348ae558af2432fa521d8a33cc09524809f705', 'esa-2025-geral.txt'),
('ESA', 'Inglês', 'Vocabulário (Gênero dos Substantivos)', 2025, 'Prova única', 'Exército Brasileiro / ESA', 50, '50', NULL, 'facil', '[DESCRIÇÃO DA IMAGEM: Tirinha de Beetle Bailey por Mort Walker.
Sargento e Recruta na festa de Valentine''s Day. No diálogo aparece a frase: "That girl over there is cute".]', 'The sentence "That girl over there is cute" shows an example of a feminine noun. Choose the option that correctly shows masculine and feminine equivalent nouns:', '[{"letra": "A", "texto": "People and peoples."}, {"letra": "B", "texto": "Big and short."}, {"letra": "C", "texto": "Uncle and aunt."}, {"letra": "D", "texto": "Cousin and niece."}, {"letra": "E", "texto": "Doctor and doctress."}]', 'C', 'A alternativa C indica corretamente o par equivalente de gênero substantivo masculino e feminino em inglês: "Uncle" (tio) e "Aunt" (tia).', 'Tirinha de Beetle Bailey por Mort Walker.', NULL, 'resumida', FALSE, FALSE, '704e46c51644093326100eb9693dc0271111653ed9d462e99cc0ef95af13d729', 'esa-2025-geral.txt'),
('ESA', 'Matemática', 'Análise Combinatória', 2026, 'Prova única', 'Exército Brasileiro', 1, '03', NULL, 'medio', '[DESCRIÇÃO DA IMAGEM: Diagrama retangular com 5 divisões em linha com os rótulos "Cavalaria", "Infantaria", "Artilharia", "Engenharia", "Comunicações"]', 'A Escola de Sargentos das Armas (ESA) oferece as qualificações militares nas armas de Infantaria, Cavalaria, Artilharia, Engenharia e Comunicações. O fuzil, o carro de combate, o obuseiro, as máquinas de engenharia e os rádios são objetos que caracterizam essas armas, respectivamente. A fim de divulgar o Exército Brasileiro, a ESA montará uma exposição com pelo menos um objeto de cada arma, num total de 12 objetos. Se a ESA possui objetos em número suficiente e os objetos de cada arma são idênticos, de quantas maneiras diferentes a exposição poderá ser montada se ela será em linha e obedecendo ao espaço reservado, conforme esquema abaixo?', '[{"letra": "A", "texto": "165"}, {"letra": "B", "texto": "215"}, {"letra": "C", "texto": "330"}, {"letra": "D", "texto": "495"}, {"letra": "E", "texto": "615"}]', 'C', 'Como a exposição exige 1 de cada uma das 5 armas num total de 12 objetos dispostos em posições reservadas de forma sequencial por tipo, sobram 7 objetos para distribuir livremente entre as 5 categorias. O número de combinações completas é calculado por CR(5,7) = C(5+7-1, 7) = C(11,4) = (11 x 10 x 9 x 8) / (4 x 3 x 2 x 1) = 330.', 'Diagrama retangular com 5 divisões em linha com os rótulos "Cavalaria", "Infantaria", "Artilharia", "Engenharia", "Comunicações"', NULL, 'resumida', TRUE, FALSE, 'fd59290e7345d497ac689eab7d089b9744524904930328fe159922fb3df39793', 'esa-2026-geral.txt'),
('ESA', 'Português', 'Acentuação Gráfica', 2026, 'Prova única', 'Exército Brasileiro', 1, '28', NULL, 'medio', NULL, 'Assinale a alternativa em que todas as palavras foram acentuadas seguindo a mesma regra de acentuação gráfica.', '[{"letra": "A", "texto": "açúcar - difícil - só"}, {"letra": "B", "texto": "ônix - mês - água"}, {"letra": "C", "texto": "sofá - júri - útil"}, {"letra": "D", "texto": "é - só - mês"}, {"letra": "E", "texto": "álbum - câmara - júri"}]', 'D', 'Na alternativa D, as três palavras ("é", "só", "mês") são acentuadas pela mesma regra gramatical: monossílabos tônicos terminados em -e, -o e -es.', NULL, NULL, 'resumida', FALSE, FALSE, 'c50ef361b604161e8f43da0f93777c1bb1dfe421017f0ecf094d9caf8cc42f80', 'esa-2026-geral.txt'),
('ESA', 'História', 'Geografia do Brasil - Demografia', 2026, 'Prova única', 'Exército Brasileiro', 1, '36', NULL, 'facil', '[DESCRIÇÃO DA IMAGEM: Mapa demonstrando a "Intensidade dos deslocamentos para trabalho e estudo na Concentração Urbana do Rio de Janeiro/RJ". Linhas arqueadas conectam municípios da Baixada Fluminense, Niterói, São Gonçalo e Maricá em direção à cidade do Rio de Janeiro, com espessuras variando conforme a quantidade de pessoas envolvidas no deslocamento diário.]', 'Observe o mapa abaixo:
Sobre a dinâmica populacional abordada no mapa, é correto afirmar que:', '[{"letra": "A", "texto": "trata-se de uma migração sazonal, determinada pela oferta de emprego em períodos determinados de tempo e praticada, em geral, por trabalhadores contratados como mão de obra barata."}, {"letra": "B", "texto": "refere-se à migração pendular, comum nas regiões metropolitanas, em que parcela da população migra diariamente do local de moradia, cidades dormitórios, para outras cidades nas quais o elevado custo de vida as impede de morar."}, {"letra": "C", "texto": "especializa um tipo de migração forçada, onde parcela da população é obrigada a migrar, em geral por questões de perseguição motivada por divergências políticas, ideológicas, religiosas, etc."}, {"letra": "D", "texto": "demonstra a migração de retorno, em que um determinado contingente de migrantes busca retornar para seus locais de origem, que agora lhes oferecem melhores condições de vida e emprego."}, {"letra": "E", "texto": "aborda casos de êxodo urbano, que, no caso específico, é motivado pelo elevado grau de violência urbana e pela busca de locais com maior oferta de serviços e empregos que ofereçam melhores salários."}]', 'B', 'O mapa ilustra os fluxos diários de vai e vem da população entre municípios vizinhos (cidades-dormitório) e o centro metropolitano da capital do Rio de Janeiro para trabalhar ou estudar, fenômeno conhecido como migração pendular.', 'Mapa demonstrando a "Intensidade dos deslocamentos para trabalho e estudo na Concentração Urbana do Rio de Janeiro/RJ". Linhas arqueadas conectam municípios da Baixada Fluminense, Niterói, São Gonçalo e Maricá em direção à cidade do Rio de Janeiro, com espessuras variando conforme a quantidade de pessoas envolvidas no deslocamento diário.', NULL, 'resumida', FALSE, FALSE, 'de13482d5ddce520b6379c52142c6faf4bd06eb67b9ebf22ea91becb4ccd2d59', 'esa-2026-geral.txt'),
('ESA', 'Inglês', 'Gramática - Grau dos Adjetivos', 2026, 'Prova única', 'Exército Brasileiro', 1, '45', NULL, 'facil', 'THE PHYSICAL FITNESS COMPETITION
The men of Platoon Number 3 are having a competition. They are tested for fitness and military skills such as shooting, attack and ambush drills, and night patrolling. The (important) test of their fitness is the ten-mile endurance march, where they have to run and march ten miles in fighting order in their (good) time. There is a prize for the first one to finish. The soldier with the (impressive) performance will have to compete again with Platoon Number 4.', 'Mark the correct option that change the adjectives in parentheses into the correct form of the superlative.', '[{"letra": "A", "texto": "importantest - best - less impressive."}, {"letra": "B", "texto": "most important - better - least impressive."}, {"letra": "C", "texto": "most important - best - least impressive."}, {"letra": "D", "texto": "more important - more good - few impressive."}, {"letra": "E", "texto": "importantest - better - less impressive."}]', 'C', 'A forma correta do superlativo dos adjetivos entre parênteses é: "important" (long adjetive) -> "most important"; "good" (irregular) -> "best"; e "impressive" -> "least impressive" (conforme opções disponíveis no contexto de avaliação).', NULL, NULL, 'resumida', FALSE, FALSE, '82fe8afe9ac09ae44e5facf86f68d53c4eb719e20007a49db5eab7ea31814a29', 'esa-2026-geral.txt'),
('ESA', 'Matemática', 'Estatística', 2026, 'Prova única', 'Exército Brasileiro', 2, '06', NULL, 'facil', '[DESCRIÇÃO DA IMAGEM: Gráfico de barras indicando o número de alunos por nota obtida. Eixo vertical (número de alunos) varia de 0 a 8. Eixo horizontal (notas obtidas pelos alunos) apresenta as notas 1,0; 2,0; 3,0; 4,0; e 5,0. As barras mostram: nota 1,0 (4 alunos), nota 2,0 (6 alunos), nota 3,0 (5 alunos), nota 4,0 (7 alunos), nota 5,0 (3 alunos).]', 'Um professor de Matemática aplicou uma prova contendo 5 questões, valendo 1 ponto cada uma, a 25 alunos de uma sala. Após fazer a correção, o professor construiu o gráfico abaixo, que relaciona o número de alunos às notas obtidas por eles:
Analisando o gráfico, conclui-se que a soma da média, da moda e da mediana das notas obtidas pelos alunos é igual a:', '[{"letra": "A", "texto": "9,15"}, {"letra": "B", "texto": "9,96"}, {"letra": "C", "texto": "8,35"}, {"letra": "D", "texto": "8,15"}, {"letra": "E", "texto": "8,59"}]', 'B', 'Média = (1*4 + 2*6 + 3*5 + 4*7 + 5*3) / 25 = 74 / 25 = 2,96.
- Moda = 4,0 (nota com maior frequência, obtida por 7 alunos).
- Mediana = nota da 13ª posição em ordem crescente = 3,0.
A soma pedida é 2,96 + 4,0 + 3,0 = 9,96.', 'Gráfico de barras indicando o número de alunos por nota obtida. Eixo vertical (número de alunos) varia de 0 a 8. Eixo horizontal (notas obtidas pelos alunos) apresenta as notas 1,0; 2,0; 3,0; 4,0; e 5,0. As barras mostram: nota 1,0 (4 alunos), nota 2,0 (6 alunos), nota 3,0 (5 alunos), nota 4,0 (7 alunos), nota 5,0 (3 alunos).', NULL, 'resumida', TRUE, FALSE, 'a7d9af1920b4541c4f5b6385feaa869b6143becdd779319ddcfbfc55b78460f4', 'esa-2026-geral.txt'),
('ESA', 'Português', 'Colocação Pronominal', 2026, 'Prova única', 'Exército Brasileiro', 2, '19', NULL, 'medio', 'TEXTO IV
"- Perdoai-me, senhora, aqui me tendes a vossos pés! tende pena de mim que eu sofri muito, que amei-vos, que vos amo muito! Compaixão! que serei vosso escravo, (...) ajoelhar-me-ei à noite à vossa porta, ouvirei vosso ressonar, vossas orações, vossos sonhos e isso me bastará. Serei vosso escravo e vosso cão, deitar-me-ei a vossos pés quando estiveres acordada, velarei com meu punhal quando a noite cair: e, se algum dia, se algum dia vós me puderes amar... então! então!..."
(AZEVEDO, Álvares de. Noite na taverna. Porto Alegre: L & PM, 2009. p. 69.)', 'Considerando a colocação pronominal no Texto IV, assinale a única alternativa em que seria possível deslocar o pronome "me" sem violar as regras gramaticais.', '[{"letra": "A", "texto": "Em \"perdoai-me, senhora\", o pronome poderia ser deslocado para antes do verbo, \"me perdoai\" já que o vocativo funciona como fator de atração para próclise."}, {"letra": "B", "texto": "Em \"ajoelhar-me-ei à noite à vossa porta\", a forma \"me ajoelharei\" seria aceita, pois há ideia de futuro e ausência de atrativos, o que permite liberdade na colocação."}, {"letra": "C", "texto": "Em \"deitar-me-ei a vossos pés\", o pronome pode ser anteposto ao verbo \"me deitarei\" considerando a familiaridade de forma na linguagem contemporânea."}, {"letra": "D", "texto": "Em \"aqui me tendes a vossos pés\", o pronome pode ser posposto ao verbo, pois seu emprego é facultativo com a presença do advérbio."}, {"letra": "E", "texto": "Em \"vós me puderes amar\", a estrutura verbal \"puderes amar\", formada por dois verbos, admite o deslocamento do pronome antes dos dois verbos, entre ou depois deles."}]', 'E', 'Na estrutura com locução verbal "puderes amar" precedida de pronome reto ("vós") sem palavra atrativa obrigatória antes, o pronome oblíquo "me" pode ser posicionado antes dos dois verbos, entre eles ou depois do verbo principal no infinitivo.', NULL, NULL, 'resumida', FALSE, FALSE, 'c7a15a3efe953199a85b0fa4c4577ae8a5c07b3eda8f5cc73d6964f373288ed4', 'esa-2026-geral.txt'),
('ESA', 'História', 'Geografia do Brasil - Demografia', 2026, 'Prova única', 'Exército Brasileiro', 2, '40', NULL, 'medio', '[DESCRIÇÃO DA IMAGEM: Dois mapas do Brasil comparando a idade mediana da população por Unidade da Federação nos anos de 2010 e 2022. Em 2010, a idade mediana do Brasil era de 29 anos, variando de 22 anos no Acre e Amapá a 32 anos no Rio Grande do Sul e Rio de Janeiro. Em 2022, a idade mediana do Brasil subiu para 35 anos, variando de 26 anos em Roraima a 38 anos no Rio Grande do Sul e Minas Gerais.]', 'Com base nos dados demonstrados nos mapas abaixo, aponte, respectivamente, um fator que permitiu a variação demonstrada e uma dificuldade enfrentada pelo Estado a partir dessa variação.', '[{"letra": "A", "texto": "Acesso aos programas de vacinação infantil e aumento nos gastos com o sistema de educação."}, {"letra": "B", "texto": "Acesso a sistemas de saneamento básico e aumento na necessidade de geração de emprego."}, {"letra": "C", "texto": "Acesso a sistemas de educação e aumento na demanda por moradias populares."}, {"letra": "D", "texto": "Acesso a avanços da medicina e aumento nos gastos com o sistema de saúde."}, {"letra": "E", "texto": "Acesso ao mercado de trabalho pelas mulheres e aumento na demanda por creches."}]', 'D', 'A elevação da idade mediana (de 29 para 35 anos) reflete a transição demográfica no Brasil impulsionada pelo avanço da medicina e melhoria nas condições de vida, o que impõe ao Estado o desafio de maiores gastos com o sistema de saúde e previdência social.', 'Dois mapas do Brasil comparando a idade mediana da população por Unidade da Federação nos anos de 2010 e 2022. Em 2010, a idade mediana do Brasil era de 29 anos, variando de 22 anos no Acre e Amapá a 32 anos no Rio Grande do Sul e Rio de Janeiro. Em 2022, a idade mediana do Brasil subiu para 35 anos, variando de 26 anos em Roraima a 38 anos no Rio Grande do Sul e Minas Gerais.', NULL, 'resumida', FALSE, FALSE, 'fbbaea1f40141b31810656839847d7097ea83f2ac71ac73a587f647f7c162c69', 'esa-2026-geral.txt'),
('ESA', 'Inglês', 'Gramática - Plural e Concordância', 2026, 'Prova única', 'Exército Brasileiro', 2, '42', NULL, 'facil', NULL, 'Mark the correct option that rewrite the following sentence in the plural:
"A soldier doesn''t hold this grenade loosely, and he always wears protective equipment."', '[{"letra": "A", "texto": "Soldiers doesn''t hold those grenades loosely, and they always wears protective equipments."}, {"letra": "B", "texto": "Soldiers don''t hold those grenades loosely, and they always wear protective equipment."}, {"letra": "C", "texto": "Soldiers don''t hold these grenades loosely, and they always wears protective equipment."}, {"letra": "D", "texto": "Soldiers don''t hold these grenades loosely, and they always wear protective equipment."}, {"letra": "E", "texto": "Soldiers doesn''t hold these grenades loosely, and they always wears protective equipment."}]', 'D', 'Passando a frase para o plural: "A soldier" -> "Soldiers"; "doesn''t hold" -> "don''t hold"; "this grenade" -> "these grenades"; "he always wears" -> "they always wear"; "equipment" permanece no singular por ser substantivo incontável.', NULL, NULL, 'resumida', FALSE, FALSE, '241de415f44d9b713be132a7ee0a087f17c4ae06df4dfe4ebb571ecf9d7444d0', 'esa-2026-geral.txt'),
('ESA', 'Matemática', 'Funções', 2026, 'Prova única', 'Exército Brasileiro', 3, '01', NULL, 'medio', NULL, 'A robótica tem se tornado cada vez mais presente nas Forças Armadas. Robôs são desenvolvidos e empregados para aumentar a segurança dos combatentes e executar tarefas em que são guiados por meio de controle remoto. Durante um exercício no Campo de Instrução da Escola de Sargentos das Armas, um robô, que se encontra na origem de um sistema cartesiano ortogonal, deve passar pelos pontos A(1,1), B(2,0) e C(4,4), que também estão no mesmo plano cartesiano. Inicialmente, ele deve caminhar em linha reta até o ponto A. Em seguida, deve ajustar sua trajetória para deslocar-se sobre um arco parabólico, a fim de passar pelos pontos B e C. Dessa forma, o robô deve ser programado para deslocar-se sobre o gráfico da função:
f(x) = mx, se 0 <= x <= 1
f(x) = ax^2 + bx + c, se x > 1
Nesse caso, a^2 + b^2 + c^2 + m^2 é igual a:', '[{"letra": "A", "texto": "32"}, {"letra": "B", "texto": "34"}, {"letra": "C", "texto": "36"}, {"letra": "D", "texto": "38"}, {"letra": "E", "texto": "40"}]', 'B', 'Para f(x) ser contínua em A(1,1), m(1) = 1 => m = 1. Para a parábola f(x) = ax^2 + bx + c passar por A(1,1), B(2,0) e C(4,4), montamos o sistema: a+b+c=1; 4a+2b+c=0; 16a+4b+c=4. Resolvendo o sistema, obtemos a = 1, b = -4 e c = 4. Calculando a^2 + b^2 + c^2 + m^2 = 1^2 + (-4)^2 + 4^2 + 1^2 = 1 + 16 + 16 + 1 = 34.', NULL, '[{"titulo": "Passo 1", "conteudo": "Para f(x) ser contínua em A(1,1), m(1) = 1 => m = 1. Para a parábola f(x) = ax^2 + bx + c passar por A(1,1), B(2,0) e C(4,4), montamos o sistema: a+b+c=1; 4a+2b+c=0; 16a+4b+c=4.", "formula": null}, {"titulo": "Fazendo a conta", "conteudo": "Resolvendo o sistema, obtemos a = 1, b = -4 e c = 4.", "formula": null}, {"titulo": "Fazendo a conta", "conteudo": "Calculando a^2 + b^2 + c^2 + m^2 = 1^2 + (-4)^2 + 4^2 + 1^2 = 1 + 16 + 16 + 1 = 34.", "formula": null}]', 'automatica', TRUE, FALSE, 'a32534384aff3f9de18e5f6863d31e27dc5aa2c4003e4e42490b7d1e84725eb3', 'esa-2026-geral.txt'),
('ESA', 'Português', 'Concordância Verbal', 2026, 'Prova única', 'Exército Brasileiro', 3, '22', NULL, 'facil', NULL, 'Analise as afirmações abaixo e assinale a única alternativa que apresenta erro de concordância verbal, de acordo com a norma-padrão da Língua Portuguesa.', '[{"letra": "A", "texto": "Faltaram explicações claras sobre os procedimentos adotados durante a operação."}, {"letra": "B", "texto": "Haveriam problemas graves se a tropa não seguisse as instruções corretamente."}, {"letra": "C", "texto": "Chegaram, por fim, os reforços que haviam sido solicitados pelo comandante."}, {"letra": "D", "texto": "Permanecem em alerta os soldados que não participaram da missão anterior."}, {"letra": "E", "texto": "Não é admissível que se percam informações tão relevantes por descuido."}]', 'B', 'O verbo "haver", quando empregado no sentido de existir ("existiriam problemas graves"), é impessoal e não possui sujeito. Portanto, deve permanecer obrigatoriamente no singular: "Haveria problemas graves...".', NULL, '[{"titulo": "Passo 1", "conteudo": "O verbo \"haver\", quando empregado no sentido de existir (\"existiriam problemas graves\"), é impessoal e não possui sujeito.", "formula": null}, {"titulo": "Conclusão", "conteudo": "Portanto, deve permanecer obrigatoriamente no singular: \"Haveria problemas graves...\".", "formula": null}]', 'automatica', FALSE, FALSE, '122c8c67f41916c67462d6f9bd8e8263123fec2db65dcd41d967890dea91d665', 'esa-2026-geral.txt'),
('ESA', 'História', 'Geografia do Brasil - Geopolítica e Integração', 2026, 'Prova única', 'Exército Brasileiro', 3, '39', NULL, 'facil', NULL, 'Uma das características da globalização é a intensificação dos fluxos de mercadorias pelo espaço mundial. A expansão do comércio internacional decorre da expansão dos mercados e da modernização dos sistemas de transportes, além da adoção de acordos multilaterais e da constituição de blocos econômicos regionais, como é o caso do MERCOSUL.
Assinale a alternativa que apresenta, respectivamente, em que tipo de bloco econômico está inserido o MERCOSUL e suas principais características.', '[{"letra": "A", "texto": "Zona de livre comércio, há a busca apenas pela liberalização gradativa do fluxo de mercadorias e de capitais dentro dos limites dos blocos."}, {"letra": "B", "texto": "União aduaneira, há a eliminação de tarifas alfandegárias nas relações comerciais no interior do bloco e define-se uma Tarifa Externa Comum."}, {"letra": "C", "texto": "Mercado comum, há a eliminação das barreiras alfandegárias e há a liberalização da circulação de bens, capitais, serviços e pessoas."}, {"letra": "D", "texto": "União econômica e monetária, há um estágio mais avançado e adoção de uma moeda comum."}, {"letra": "E", "texto": "Acordo Geral sobre Comércio de Serviços, há um intercâmbio de serviços e trocas internacionais."}]', 'B', 'O MERCOSUL é classificado como uma União Aduaneira (imperfeita), cuja estrutura prevê a livre circulação de mercadorias com alíquota zero entre os países-membros e a adoção de uma Tarifa Externa Comum (TEC) para o comércio com terceiros países.', NULL, NULL, 'resumida', FALSE, FALSE, '9259895d77b0288215a726b8f184b43a8fe82d109c12f98d0182a8ce7640e6d0', 'esa-2026-geral.txt'),
('ESA', 'Inglês', 'Gramática - Possessivos', 2026, 'Prova única', 'Exército Brasileiro', 3, '47', NULL, 'medio', 'THE DAY BEFORE A FIELD TRAINING EXERCISE
Lieutenant Santos: Gomes, Is that your backpack on the bench?
Corporal Gomes: No, sir. Sergeant Silvia Smith left it there. I think that''s.
Lieutenant Santos: And what about this helmet with a red stripe?
Corporal Gomez: That one belongs to me, Sir. It is. I always mark gear with a red stripe.
Lieutenant Santos: Good habit! Where is the privates'' equipment?
Corporal Gomez: They have already put in the locker room, sir.', 'Mark the correct option that complete the dialogue with the respective suitable possessives.', '[{"letra": "A", "texto": "his - my - mine - their"}, {"letra": "B", "texto": "hers - mine - my - their"}, {"letra": "C", "texto": "her - my - mine - their"}, {"letra": "D", "texto": "her - mine - mine - theirs"}, {"letra": "E", "texto": "hers - mine - my - theirs"}]', 'E', 'Preenchimento correto dos pronomes possessivos:
1) "that''s hers" (pronome possessivo referente a Silvia Smith).
2) "It is mine" (pronome possessivo referente a mim).
3) "my gear" (adjetivo possessivo acompanhando o substantivo gear).
4) "put theirs" (pronome possessivo referente aos soldados/privates).', NULL, NULL, 'resumida', FALSE, FALSE, '26c08fe0fa11bdd8b4e83dda645e27673b09195927f35e10fbf6624f887972bc', 'esa-2026-geral.txt'),
('ESA', 'Matemática', 'Funções', 2026, 'Prova única', 'Exército Brasileiro', 4, '02', NULL, 'medio', '[DESCRIÇÃO DA IMAGEM: Gráfico cartesiano da função logarítmica f(x) = log2(x). Há marcações no eixo x nos pontos x = 2 e x = 8. As projeções pontilhadas mostram os valores f(2) e f(8) no eixo y. Há um segmento de reta unindo os pontos (2, f(2)) e (8, f(8)). A área sob essa reta entre x=2 e x=8 e acima do eixo x está sombreada.]', 'A figura abaixo representa o gráfico da função f: R+* -> R definida por f(x) = log2(x).
A área da região sombreada é numericamente igual a:', '[{"letra": "A", "texto": "10"}, {"letra": "B", "texto": "12"}, {"letra": "C", "texto": "16"}, {"letra": "D", "texto": "18"}, {"letra": "E", "texto": "20"}]', 'B', 'Os pontos destacados na função f(x) = log2(x) são (2, f(2)) = (2,1) e (8, f(8)) = (8,3). A área sob o segmento reto entre x = 2 e x = 8 forma um trapézio de bases b1 = 1 e b2 = 3 e altura h = 8 - 2 = 6. Área do trapézio = (1 + 3) * 6 / 2 = 12.', 'Gráfico cartesiano da função logarítmica f(x) = log2(x). Há marcações no eixo x nos pontos x = 2 e x = 8. As projeções pontilhadas mostram os valores f(2) e f(8) no eixo y. Há um segmento de reta unindo os pontos (2, f(2)) e (8, f(8)). A área sob essa reta entre x=2 e x=8 e acima do eixo x está sombreada.', '[{"titulo": "Passo 1", "conteudo": "Os pontos destacados na função f(x) = log2(x) são (2, f(2)) = (2,1) e (8, f(8)) = (8,3). A área sob o segmento reto entre x = 2 e x = 8 forma um trapézio de bases b1 = 1 e b2 = 3 e altura h = 8 - 2 = 6.", "formula": null}, {"titulo": "Conclusão", "conteudo": "Área do trapézio = (1 + 3) * 6 / 2 = 12.", "formula": null}]', 'automatica', TRUE, FALSE, '6853ace3d1fbc85a5c9bec91305845041961bb0f1cb0371d977b6a5c8f5002f4', 'esa-2026-geral.txt'),
('ESA', 'Português', 'Figuras de Linguagem', 2026, 'Prova única', 'Exército Brasileiro', 4, '18', NULL, 'facil', 'TEXTO III
"Dormia tudo como se o universo fosse um erro; e o vento, flutuando incerto, era uma bandeira sem forma desfraldada sobre um quartel sem ser.
Esfarrapava-se coisa nenhuma no ar alto e forte, e os caixilhos das janelas sacudiam os vidros para que a extremidade se ouvisse. No fundo de tudo, calada, a noite era o túmulo de Deus (a alma sofria com pena de Deus).
E, de repente nova ordem das coisas universais agia sobre a cidade, o vento assobiava no intervalo do vento, e havia uma noção dormida de muitas agitações na altura. Depois a noite fechava-se como um alçapão, e um grande sossego fazia vontade de ter estado a dormir."
(PESSOA, Fernando. Livro do Desassossego.)', 'Observe o trecho abaixo extraído do Texto III:
"vento assobiava no intervalo do vento"
Assinale a alternativa que indica uma das figuras de linguagem representadas pelo trecho acima:', '[{"letra": "A", "texto": "Antítese"}, {"letra": "B", "texto": "Eufemismo"}, {"letra": "C", "texto": "Prosopopeia"}, {"letra": "D", "texto": "Ironia"}, {"letra": "E", "texto": "Hipérbole"}]', 'C', 'O excerto "o vento assobiava..." atribui uma característica e ação humana (assobiar) a um elemento inanimado da natureza (o vento), configurando a figura de linguagem Prosopopeia (ou Personificação).', NULL, NULL, 'resumida', FALSE, FALSE, '7f184790c7d765c777c10fa8f173e99c1f79d049d6fe62ea2b9bc76cad501032', 'esa-2026-geral.txt'),
('ESA', 'História', 'Geografia do Brasil - Impactos Ambientais Urbanos', 2026, 'Prova única', 'Exército Brasileiro', 4, '35', NULL, 'facil', '[DESCRIÇÃO DA IMAGEM: Ilustração comparativa entre "Zona Rural" e "Cidade". Na Zona Rural indica-se menor absorção/retenção de calor, alta transpiração de plantas/evaporação de água e alta penetração de água no solo. Na Cidade indica-se maior absorção/retenção de calor, baixa penetração de água e destaca-se que a temperatura é "3° a 10°C mais quente".]', 'Observe a imagem abaixo:
O problema ambiental climático que está diretamente relacionado à imagem acima é o(a):', '[{"letra": "A", "texto": "Camada de ozônio."}, {"letra": "B", "texto": "Ilha de calor."}, {"letra": "C", "texto": "El Niño."}, {"letra": "D", "texto": "Inversão térmica."}, {"letra": "E", "texto": "Aquecimento global."}]', 'B', 'A ilustração compara o ambiente urbano densamente construído (com maior retenção de calor pelas superfícies de asfalto e concreto e menor vegetação) à zona rural, caracterizando o fenômeno microclimático urbano da Ilha de Calor.', 'Ilustração comparativa entre "Zona Rural" e "Cidade". Na Zona Rural indica-se menor absorção/retenção de calor, alta transpiração de plantas/evaporação de água e alta penetração de água no solo. Na Cidade indica-se maior absorção/retenção de calor, baixa penetração de água e destaca-se que a temperatura é "3° a 10°C mais quente".', NULL, 'resumida', FALSE, FALSE, '6cb70cc6a99fe4b8223efa406cd2eb862a3310da011a3227adb190bdc3c21d7b', 'esa-2026-geral.txt'),
('ESA', 'Inglês', 'Gramática - Preposições', 2026, 'Prova única', 'Exército Brasileiro', 4, '41', NULL, 'medio', 'Dear Lopes,
I arrived Salvador three weeks ago. I spent two days Itaparica Island and then went to the Green Coast by hitching a ride. The beaches there are great for surfing, especially Monte Gordo. I had a great time there. After 3 days, I went to Porto Seguro plane and stayed there for another 3 days. I was so tired that I fell asleep all the way back Salvador. When I got there, I took a shuttle from the bus station to the airport. When the shuttle arrived the airport, I got the vehicle without paying. I was so embarrassed but I apologized to the driver for that, and everything was OK. I am travelling back to Três Corações next week.
I hope everything is ok with you!
Take care,
Sarmento', 'Read the message that an NCO Academy student on vacation wrote to his comrade who lives in Três Corações, Minas Gerais.
Fill in the blanks with the suitable prepositions.', '[{"letra": "A", "texto": "in - on - by - to - at - off"}, {"letra": "B", "texto": "at - in - of - of - in - out"}, {"letra": "C", "texto": "in - on - by - to - in - off"}, {"letra": "D", "texto": "at - on - by - in - for - off"}, {"letra": "E", "texto": "at - in - of - of - for - out"}]', 'A', 'Uso correto das preposições no texto: "in Salvador" (cidade), "on Itaparica Island" (ilha), "by plane" (meio de transporte), "back to Salvador" (direção/retorno), "arrived at the airport" (ponto/local específico), "got off the vehicle" (descer do veículo).', NULL, NULL, 'resumida', FALSE, FALSE, 'ca087dbe3d563d8c34a4a1a6363c40c285efb242fc0d53103e628e69e7ad97b1', 'esa-2026-geral.txt'),
('ESA', 'Matemática', 'Funções', 2026, 'Prova única', 'Exército Brasileiro', 5, '13', NULL, 'medio', NULL, 'A administração de um pequeno shopping fez um estudo com o objetivo de melhorar a frequência. Um dos engenheiros responsáveis por esse estudo observou que a frequência que representa essa situação pode ser expressa pela função f(x) = 700 + |225 - 15x|, sendo 1 <= x <= 30, em que x representa o dia do mês e f(x) a quantidade de pessoas que frequentam esse pequeno shopping nesse dia (considere o mesmo horário de funcionamento para todos os dias do mês). Com base no enunciado, avalie as afirmações abaixo em verdadeiro (V) ou falso (F).
I. O dia mais frequentado nesse shopping é o 30º dia.
II. O dia menos frequentado nesse shopping é o 15º dia.
III. No 15º dia, a quantidade de pessoas que frequentou esse shopping é zero.
IV. No dia 30, a quantidade de pessoas que frequentou esse shopping foi de 225.
V. No dia 25, a quantidade de pessoas que frequentou esse shopping foi de 850.
Marque a alternativa que representa a sequência correta com relação às afirmações acima:', '[{"letra": "A", "texto": "V - V - V - F - F"}, {"letra": "B", "texto": "F - F - F - V - V"}, {"letra": "C", "texto": "V - V - F - F - F"}, {"letra": "D", "texto": "F - F - V - V - V"}, {"letra": "E", "texto": "V - V - F - F - V"}]', 'E', 'Avaliando f(x) = 700 + |225 - 15x| para 1 <= x <= 30:
I. Verdadeiro: f(30) = 700 + |225 - 450| = 925 (ponto máximo).
II. Verdadeiro: f(15) = 700 + |0| = 700 (ponto mínimo).
III. Falso: no dia 15 a frequência é 700 pessoas.
IV. Falso: no dia 30 a frequência é 925.
V. Verdadeiro: f(25) = 700 + |225 - 375| = 850.
A sequência correta é V - V - F - F - V.', NULL, '[{"titulo": "Passo 1", "conteudo": "Avaliando f(x) = 700 + |225 - 15x| para 1 <= x <= 30: I.", "formula": null}, {"titulo": "Passo 2", "conteudo": "Verdadeiro: f(30) = 700 + |225 - 450| = 925 (ponto máximo). II.", "formula": null}, {"titulo": "Passo 3", "conteudo": "Verdadeiro: f(15) = 700 + |0| = 700 (ponto mínimo). III.", "formula": null}, {"titulo": "Passo 4", "conteudo": "Falso: no dia 15 a frequência é 700 pessoas. IV.", "formula": null}, {"titulo": "Passo 5", "conteudo": "Falso: no dia 30 a frequência é 925. V.", "formula": null}, {"titulo": "Conclusão", "conteudo": "Verdadeiro: f(25) = 700 + |225 - 375| = 850. A sequência correta é V - V - F - F - V.", "formula": null}]', 'automatica', TRUE, FALSE, 'b6761605e4250db40878e7f851b5d6e9cd3efcc54ef41142a48d2345294521bd', 'esa-2026-geral.txt'),
('ESA', 'Português', 'Figuras de Linguagem', 2026, 'Prova única', 'Exército Brasileiro', 5, '27', NULL, 'medio', NULL, 'Assinale, dentre as alternativas abaixo, aquela em que apresenta a mesma figura de linguagem presente no seguinte trecho:
"Vão os dois em diálogo peripatético, ele em passo largo, ela no voo."
(ANDRADE, Carlos Drummond de. Cadeira de balanço. Rio de Janeiro: Record, 1970.)', '[{"letra": "A", "texto": "\"A barca vinha de perto, chegou, atracou, entramos.\" (Machado de Assis)"}, {"letra": "B", "texto": "\"O bonde, cuspindo e engolindo gente, mergulhava nas saborosas entranhas de Belém.\" (Dalcídio Jurandir)"}, {"letra": "C", "texto": "\"E se os olhos reaprendessem a chorar, seria um segundo dilúvio.\" (Carlos Drummond de Andrade)"}, {"letra": "D", "texto": "\"Se chegar depois das três, a casa fechada. A mala na varanda. E o táxi na porta.\" (Dalton Trevisan)"}, {"letra": "E", "texto": "\"Deixa lá, que ainda havemos de ser feliz os dois, com a nossa casinha e as nossas coisas.\" (Almada Negreiros)"}]', 'B', 'O texto do enunciado utiliza prosopopeia/personificação ("ela no voo"). Na alternativa B, a frase "O bonde, cuspindo e engolindo gente..." atribui ações humanas (cuspir e engolir) ao bonde, empregando exatamente a mesma figura de linguagem.', NULL, NULL, 'resumida', FALSE, FALSE, '2847e633ee89cfc81d5c68696ab803e0767ba225cf397aba676865d0a98a7076', 'esa-2026-geral.txt'),
('ESA', 'História', 'Geografia do Brasil - Recursos e Matriz Energética', 2026, 'Prova única', 'Exército Brasileiro', 5, '37', NULL, 'medio', '[DESCRIÇÃO DA IMAGEM: Diagrama esquemático em perfil do oceano e do subsolo marinho mostrando a camada de água (até 2140 m), a camada pós-sal (2140 m a 3500 m), a camada de sal (3500 m a 5500 m) e a camada pré-sal (abaixo de 5500 m), com reservatório de petróleo e gás natural.]', 'O crescimento populacional, o desenvolvimento de novas tecnologias e a elevação do padrão de consumo têm levado ao aumento da demanda por energia e à crescente necessidade de aumentar sua produção mundial. Em 2008, dirigentes da Petrobras anunciaram a descoberta de enormes reservas de petróleo e gás natural a mais de 5 quilômetros de profundidade, na camada pré-sal, conforme imagem abaixo.
Sobre a camada pré-sal, é correto afirmar que:', '[{"letra": "A", "texto": "É uma formação geológica que se constituiu com a separação dos continentes sul-americano e africano ao longo das bacias de Santos, Campos e Espírito Santo."}, {"letra": "B", "texto": "É considerada um recurso renovável que se constituiu com a separação dos continentes sul-americano e europeu ao longo das bacias de Santos, Campos e Amazônica."}, {"letra": "C", "texto": "Vem sendo amplamente explorada a partir de recursos internos."}, {"letra": "D", "texto": "É encontrada nos subsolos oceânicos, em áreas de escudos cristalinos."}, {"letra": "E", "texto": "Mesmo não tendo valor no mercado internacional, garante autossuficiência energética ao Brasil."}]', 'A', 'As reservas do Pré-sal estão localizadas em rochas sedimentares marinhas formadas durante o processo de separação dos continentes Sul-Americano e Africano na Era Mesozoica, ao longo das bacias petrolíferas de Santos, Campos e Espírito Santo.', 'Diagrama esquemático em perfil do oceano e do subsolo marinho mostrando a camada de água (até 2140 m), a camada pós-sal (2140 m a 3500 m), a camada de sal (3500 m a 5500 m) e a camada pré-sal (abaixo de 5500 m), com reservatório de petróleo e gás natural.', NULL, 'resumida', FALSE, FALSE, 'f3cf516dfd4fd7a07155741d67901654d3c77f54e9d9b21d72837e34fb8ec298', 'esa-2026-geral.txt'),
('ESA', 'Inglês', 'Gramática - Tag Questions', 2026, 'Prova única', 'Exército Brasileiro', 5, '43', NULL, 'facil', 'Good morning, Captain Louis. Isn''t it a nice day to go for a swim?
It surely is, but there isn''t a pool in the area. We have to pick up another sport, ?', 'Choose the best option to correctly complete the sentence below.', '[{"letra": "A", "texto": "haven''t we?"}, {"letra": "B", "texto": "don''t we?"}, {"letra": "C", "texto": "do you?"}, {"letra": "D", "texto": "is there?"}, {"letra": "E", "texto": "haven''t you?"}]', 'B', 'A oração principal utiliza o verbo principal no Simple Present ("We have to..."). A tag question correspondente para a frase afirmativa no presente deve usar o verbo auxiliar no negativo: "don''t we?".', NULL, NULL, 'resumida', FALSE, FALSE, 'e65da3f255a1ccf5b77aeba3b4872027eb72d27aba1978de32bcf6d58193657b', 'esa-2026-geral.txt'),
('ESA', 'Matemática', 'Geometria Analítica', 2026, 'Prova única', 'Exército Brasileiro', 6, '14', NULL, 'dificil', '[DESCRIÇÃO DA IMAGEM: Desenho de uma mesa de sinuca elíptica no plano cartesiano com centro na origem. Os focos F1 e F2 estão sobre o eixo x. Há uma bola no ponto A localizado no terceiro quadrante e uma bola no ponto B posicionada entre A e o foco F2.]', 'A figura abaixo representa uma mesa de sinuca em forma elíptica de focos F1 e F2 e distância focal igual a 8. A sinuca possui uma única caçapa localizada em F2. Um jogador deseja jogar nessa caçapa a bola que se encontra no ponto A. Entretanto, ele não consegue fazer isso diretamente, pois existe uma bola em B que está localizado entre A e F2. Para cumprir o objetivo, o jogador resolve fazer uma "tabela", ou seja, jogar a bola na parede da sinuca para que ela reflita em direção a F2.
Considerando que o sistema cartesiano tenha origem no centro da elipse e que o ponto A tem coordenadas (-2,-2), qual das equações abaixo dá a direção para que o jogador cumpra seu objetivo?', '[{"letra": "A", "texto": "2x + y + 8 = 0"}, {"letra": "B", "texto": "3x - y + 12 = 0"}, {"letra": "C", "texto": "x + 2y + 6 = 0"}, {"letra": "D", "texto": "x + y + 4 = 0"}, {"letra": "E", "texto": "3x - 2y + 2 = 0"}]', 'D', 'Pela propriedade focal da elipse, para rebater a bola em A(-2,-2) na parede e atingir o foco F2(4,0) contornando o obstáculo B, a tacada deve ser dada ao longo da reta alinhada com o foco F1(-4,0) e o ponto A(-2,-2). O coeficiente angular é m = (-2 - 0) / (-2 - (-4)) = -1. A equação da reta é y - 0 = -1(x + 4) => x + y + 4 = 0.', 'Desenho de uma mesa de sinuca elíptica no plano cartesiano com centro na origem. Os focos F1 e F2 estão sobre o eixo x. Há uma bola no ponto A localizado no terceiro quadrante e uma bola no ponto B posicionada entre A e o foco F2.', '[{"titulo": "Passo 1", "conteudo": "Pela propriedade focal da elipse, para rebater a bola em A(-2,-2) na parede e atingir o foco F2(4,0) contornando o obstáculo B, a tacada deve ser dada ao longo da reta alinhada com o foco F1(-4,0) e o ponto A(-2,-2). O coeficiente angular é m = (-2 - 0) / (-2 - (-4)) = -1.", "formula": null}, {"titulo": "Conclusão", "conteudo": "A equação da reta é y - 0 = -1(x + 4) => x + y + 4 = 0.", "formula": null}]', 'automatica', TRUE, FALSE, 'ec148943ed3363cea66d3e120e2ac7ce0358a053bfc89b37b9e3b981de9b9a5b', 'esa-2026-geral.txt'),
('ESA', 'Português', 'Interpretação de Texto', 2026, 'Prova única', 'Exército Brasileiro', 6, '17', NULL, 'facil', 'TEXTO II
"A revolução digital já não é uma promessa, mas uma realidade concreta. Ela molda a forma como nos comunicamos, consumimos e trabalhamos. Isso impõe novos desafios à educação, que precisa não apenas se adaptar, mas também liderar mudanças."
(BARROS, M. L. Educação na era digital. Revista Educação em Pauta, n. 34, 2022.)', 'De acordo com o Texto II, qual é a principal exigência que a revolução digital impõe à educação?', '[{"letra": "A", "texto": "A educação deve manter os métodos tradicionais para garantir estabilidade."}, {"letra": "B", "texto": "A educação deve aguardar que a tecnologia se estabilize para se adaptar."}, {"letra": "C", "texto": "A educação deve limitar o uso de tecnologias em sala de aula."}, {"letra": "D", "texto": "A educação precisa apenas se adaptar às novas tecnologias."}, {"letra": "E", "texto": "A educação deve se adaptar e também liderar mudanças diante dessa revolução."}]', 'E', 'O Texto II afirma de forma direta na sua frase final que a revolução digital "impõe novos desafios à educação, que precisa não apenas se adaptar, mas também liderar mudanças."', NULL, NULL, 'resumida', FALSE, FALSE, '02aacbe8b5207bde6a13566b6704cb53a1f6c7b6ede2845f20c7be2dc90f81be', 'esa-2026-geral.txt'),
('ESA', 'História', 'Geografia do Brasil - Recursos e Matriz Energética', 2026, 'Prova única', 'Exército Brasileiro', 6, '38', NULL, 'medio', 'Os sistemas isolados, como seu próprio nome já diz, são plataformas de geração e transmissão de energia elétrica que não estão conectados ao Sistema Interligado Nacional. Atualmente, o SIN é composto de quatro subsistemas: Sul, Sudeste/Centro-Oeste, Nordeste e a maior parte da Região Norte. No total, são pouco mais de 200 localidades isoladas no Brasil, a maioria no Norte do país. [...] Os Sistemas Isolados são operados de forma independente do SIN, com suas próprias regras e regulamentos. Eles geralmente são administrados por empresas de distribuição de energia elétrica, que também são responsáveis pela construção e manutenção das linhas de transmissão e subestações.', 'O mapa e o texto tratam de uma importante questão energética brasileira. Sobre essa questão, julgue as afirmações a seguir:
I - O SIN não atende parte da região Norte do país, pois o consumo de energia nesta região é muito baixo. Não há nenhum ponto de grande consumo de energia na região, além do fato de não existir tecnologia apropriada para transmissão de energia no ambiente amazônico;
II - As usinas de geração de energia que atuam de forma isolada, especialmente na região Norte, são basicamente movidas a óleo diesel, o que torna seu funcionamento caro e logisticamente complexo;
III - A questão ambiental e as distâncias entre os pontos de consumo no interior da Amazônia são fatores que ainda inviabilizam a interligação dessas localidades com o Sistema Interligado Nacional;
IV - Em caso de falha em uma dessas usinas ou a falta de combustível para a geração de eletricidade, essas localidades não possuem outras formas de receber eletricidade e permanecerão assim até a solução do problema na usina em questão.
Estão corretas somente as afirmações:', '[{"letra": "A", "texto": "I e II."}, {"letra": "B", "texto": "II e III."}, {"letra": "C", "texto": "III e IV."}, {"letra": "D", "texto": "I, II e III."}, {"letra": "E", "texto": "II, III e IV."}]', 'E', 'As afirmações II, III e IV estão corretas. A afirmação I é incorreta pois a Amazônia possui polos de elevado consumo de energia (como Manaus e áreas de mineração) e a falta de interligação decorre das enormes distâncias e dos rigorosos impactos ambientais na floresta.', NULL, NULL, 'resumida', FALSE, FALSE, '9907366f8b1e2077cecc2696cb2b4f8c2916d024fdfe23628adc9a40418c249c', 'esa-2026-geral.txt'),
('ESA', 'Inglês', 'Gramática - Tempos Verbais (Simple Past)', 2026, 'Prova única', 'Exército Brasileiro', 6, '49', NULL, 'facil', 'Sophie: What happened here?
Jake: I broke the chair while I was trying to fix it.
Sophie: Why were you fixing it? You can''t do that kind of work.
Jake: I thought it was easy.
Sophie: Next time, ask for help. You can''t just try everything on your own.
Jake: I know... I''ll be more careful.', 'Check the alternative that only contains verbs in the simple past.', '[{"letra": "A", "texto": "happened - broke - fix"}, {"letra": "B", "texto": "broke - fixing - thought"}, {"letra": "C", "texto": "were - can''t - work"}, {"letra": "D", "texto": "broke - was - thought"}, {"letra": "E", "texto": "happened - broke - try"}]', 'D', 'A alternativa D contém apenas formas verbais conjugadas no Simple Past: "broke" (passado de break), "was" (passado de be) e "thought" (passado de think).', NULL, NULL, 'resumida', FALSE, FALSE, '7cded5ac13af18bf850fc944f2be8842d2280caf5a304611c4303a6c5cf90831', 'esa-2026-geral.txt'),
('ESA', 'Matemática', 'Geometria Espacial', 2026, 'Prova única', 'Exército Brasileiro', 7, '08', NULL, 'medio', NULL, 'Um cilindro, cujo raio da base mede 20 cm, possui água em seu interior até a altura de 10 cm. Três esferas metálicas (E1, E2 e E3, nessa ordem) possuem os raios com medidas que seguem uma progressão geométrica. O raio da esfera E1 mede 3 cm. Quando essas esferas são colocadas no interior do cilindro, o nível da água sobe 6,57 cm. Assim, pode-se afirmar que o volume da esfera E2 é igual a:', '[{"letra": "A", "texto": "36pi cm³"}, {"letra": "B", "texto": "72pi cm³"}, {"letra": "C", "texto": "180pi cm³"}, {"letra": "D", "texto": "240pi cm³"}, {"letra": "E", "texto": "288pi cm³"}]', 'E', 'O volume de água deslocado no cilindro de raio 20 cm é V = pi * R^2 * h = pi * (20^2) * 6,57 = 2628*pi cm³. Sendo os raios r1=3, r2=3q e r3=3q^2, a soma dos volumes das 3 esferas é (4/3)*pi*(3^3 + (3q)^3 + (3q^2)^3) = 2628*pi => 36*(1 + q^3 + q^6) = 2628 => q^6 + q^3 - 72 = 0, gerando q^3 = 8 => q = 2. O raio de E2 é r2 = 6 cm, e seu volume é V2 = (4/3)*pi*(6^3) = 288*pi cm³.', NULL, '[{"titulo": "Passo 1", "conteudo": "O volume de água deslocado no cilindro de raio 20 cm é V = pi * R^2 * h = pi * (20^2) * 6,57 = 2628*pi cm³.", "formula": null}, {"titulo": "Conclusão", "conteudo": "Sendo os raios r1=3, r2=3q e r3=3q^2, a soma dos volumes das 3 esferas é (4/3)*pi*(3^3 + (3q)^3 + (3q^2)^3) = 2628*pi => 36*(1 + q^3 + q^6) = 2628 => q^6 + q^3 - 72 = 0, gerando q^3 = 8 => q = 2. O raio de E2 é r2 = 6 cm, e seu volume é V2 = (4/3)*pi*(6^3) = 288*pi cm³.", "formula": null}]', 'automatica', TRUE, FALSE, '410adab3d4cd486795b35eb7daf34f35d16ddb98283089aa192b54e208c73084', 'esa-2026-geral.txt'),
('ESA', 'Português', 'Interpretação de Texto', 2026, 'Prova única', 'Exército Brasileiro', 7, '21', NULL, 'facil', 'TEXTO VI
"No ambiente militar contemporâneo, a competência linguística do sargento - entendida como a capacidade de ler criticamente, interpretar contextos e expressar-se com clareza - assume papel estratégico. Um sargento que domina a linguagem é capaz de compreender instruções complexas, redigir relatórios precisos e, sobretudo, liderar com autoridade comunicativa. Assim, a leitura e a escrita deixam de ser habilidades acessórias e tornam-se instrumentos de ação tática e administrativa, cuja ausência compromete o desempenho e a credibilidade do profissional."
(BRASIL. Ministério da Defesa. Exército Brasileiro. Revista Verde-Oliva, Brasília, n. 530, p. 19, 2022.)', 'Com base no Texto VI, sobre o papel da competência linguística na formação e atuação do sargento, é correto afirmar que:', '[{"letra": "A", "texto": "A competência linguística é uma exigência exclusiva das funções administrativas, não interferindo nas atividades táticas realizadas em campo."}, {"letra": "B", "texto": "A clareza na comunicação é desejável, mas não constitui fator determinante para a autoridade e o desempenho do sargento."}, {"letra": "C", "texto": "O domínio da linguagem pelo sargento é um elemento estratégico que impacta diretamente sua capacidade de liderar, interpretar ordens e agir com eficiência."}, {"letra": "D", "texto": "A leitura e a escrita são habilidades complementares que podem ser delegadas a superiores, não sendo centrais à função do sargento."}, {"letra": "E", "texto": "A exigência por competências linguísticas é uma tendência recente, mas opcional, e não afeta significativamente o dia a dia militar."}]', 'C', 'O Texto VI destaca explicitamente que o domínio da linguagem pelo sargento é "um instrumento de ação tática e administrativa" indispensável para liderar com autoridade, compreender ordens e atuar com eficiência.', NULL, NULL, 'resumida', FALSE, FALSE, '37a0239ec1881d09e498336840409b524c571437426a8514073449dda56c6d9c', 'esa-2026-geral.txt'),
('ESA', 'História', 'História do Brasil - Período Colonial', 2026, 'Prova única', 'Exército Brasileiro', 7, '29', NULL, 'facil', '[DESCRIÇÃO DA IMAGEM: Mapa histórico das Capitanias Hereditárias (1534-1536) mostrando a divisão do território da América Portuguesa por linhas paralelas à Linha de Tordesilhas, delimitando os quinhões doados aos capitães-donatários.]', 'Considerações políticas levaram a Coroa portuguesa à convicção de que era necessário colonizar a nova terra na América. Ficou decidido que o modelo seria de capitanias hereditárias. A América portuguesa foi dividida, à época, em quinze quinhões, por uma série de linhas paralelas ao Equador que iam do litoral ao meridiano de Tordesilhas, sendo os quinhões entregues aos chamados capitães-donatários.
Selecione entre as alternativas abaixo as características das capitanias mais prósperas:', '[{"letra": "A", "texto": "atividade açucareira e um relacionamento menos agressivo com as tribos indígenas."}, {"letra": "B", "texto": "atividade mineradora e um relacionamento menos agressivo com as tribos indígenas."}, {"letra": "C", "texto": "atividade de extração do pau-brasil e um relacionamento menos agressivo com as tribos indígenas."}, {"letra": "D", "texto": "atividade açucareira e um relacionamento mais agressivo com as tribos indígenas."}, {"letra": "E", "texto": "atividade mineradora e um relacionamento mais agressivo com as tribos indígenas."}]', 'A', 'As capitanias de Pernambuco e São Vicente foram as únicas que prosperaram no início da colonização portuguesa graças ao sucesso do cultivo da cana-de-açúcar para exportação e ao estabelecimento de alianças e menor atrito com certas tribos indígenas locais.', 'Mapa histórico das Capitanias Hereditárias (1534-1536) mostrando a divisão do território da América Portuguesa por linhas paralelas à Linha de Tordesilhas, delimitando os quinhões doados aos capitães-donatários.', NULL, 'resumida', FALSE, FALSE, 'b23eec63de9948696ade045e1cae4a2e9a1fca66a5edf0a18f32a3112932e673', 'esa-2026-geral.txt'),
('ESA', 'Inglês', 'Interpretação de Texto', 2026, 'Prova única', 'Exército Brasileiro', 7, '44', NULL, 'facil', 'U.S. Army @USArmy:
"The Army surpassed its 2025 reenlistment goal SIX months early! Over 15,600 Soldiers are staying in uniform. Thank you to every Soldier who raised their hand again to defend our nation."', 'Read the following U.S. Army post. Then, choose the option that best reflects the main idea of the message.', '[{"letra": "A", "texto": "The Army''s goal was achieved sooner than expected."}, {"letra": "B", "texto": "There are more than 15,600 new soldiers in the American Army in 2025."}, {"letra": "C", "texto": "American soldiers use their hands to defend the country."}, {"letra": "D", "texto": "More than 15,000 American soldiers are not going to buy a new uniform."}, {"letra": "E", "texto": "The Army''s goal was to reenlist more than 20,000 soldiers."}]', 'A', 'O post oficial do Exército dos EUA afirma que a meta de reengajamento de soldados para 2025 foi atingida "SIX months early" (seis meses antes do prazo), indicando que o objetivo foi alcançado antes do esperado.', NULL, NULL, 'resumida', FALSE, FALSE, 'f289226f95f1b5b17eeba2fab1a9abee5de70f7ede95bf6e7025fa15319ec67d', 'esa-2026-geral.txt'),
('ESA', 'Matemática', 'Geometria Espacial', 2026, 'Prova única', 'Exército Brasileiro', 8, '10', NULL, 'facil', '[DESCRIÇÃO DA IMAGEM: Representação tridimensional de um paralelepípedo reto-retângulo com os vértices rotulados: base inferior ABCD e base superior EFGH, tal que A está abaixo de D, B abaixo de C, E abaixo de H, F abaixo de G.]', 'Observe o paralelepípedo ABCDEFGH.
Marque a única alternativa correta entre as afirmações abaixo:', '[{"letra": "A", "texto": "As retas BE e FG são coplanares."}, {"letra": "B", "texto": "Os vértices A, B e G não definem um plano."}, {"letra": "C", "texto": "As retas BC e EF são ortogonais."}, {"letra": "D", "texto": "As retas AE e BF são reversas."}, {"letra": "E", "texto": "Os vértices C, E, H e G pertencem a um mesmo plano."}]', 'C', 'A reta BC é paralela a AD, enquanto EF é perpendicular a AD. Como BC e EF estão em planos paralelos distintos e suas direções formam um ângulo de 90°, elas são retas reversas perpendiculares entre si, ou seja, ortogonais.', 'Representação tridimensional de um paralelepípedo reto-retângulo com os vértices rotulados: base inferior ABCD e base superior EFGH, tal que A está abaixo de D, B abaixo de C, E abaixo de H, F abaixo de G.', '[{"titulo": "Passo 1", "conteudo": "A reta BC é paralela a AD, enquanto EF é perpendicular a AD.", "formula": null}, {"titulo": "O que o enunciado dá", "conteudo": "Como BC e EF estão em planos paralelos distintos e suas direções formam um ângulo de 90°, elas são retas reversas perpendiculares entre si, ou seja, ortogonais.", "formula": null}]', 'automatica', TRUE, FALSE, '2c194d0754ed54a766fca62b5a1bfa398c51e79448031e5165c42ef4f507a4c7', 'esa-2026-geral.txt'),
('ESA', 'Português', 'Interpretação de Texto', 2026, 'Prova única', 'Exército Brasileiro', 8, '24', NULL, 'facil', 'TEXTO VIII
"E era como se chovesse. Chovia dentro dele. Não águas, mas sentimentos, lembranças, culpas antigas. Uma chuva que não molhava a pele, mas encharcava a alma."
(ABREU, Caio Fernando. Os dragões não conhecem o paraíso.)', 'Com base na leitura do Texto VIII, a palavra "encharcava", em "mas encharcava a alma", tem como significado principal:', '[{"letra": "A", "texto": "Tornava a alma mais pesada, como se fosse feita de pedra."}, {"letra": "B", "texto": "Inundava a alma de emoções, de forma intensa e profunda."}, {"letra": "C", "texto": "Deixava a alma seca, exaurida pelas lembranças."}, {"letra": "D", "texto": "Limpava a alma de todas as culpas passadas."}, {"letra": "E", "texto": "Cobria a alma com uma camada superficial de sentimentos passageiros."}]', 'B', 'No contexto do conto figurado ("uma chuva que não molhava a pele, mas encharcava a alma"), o verbo "encharcar" expressa a ideia metafórica de preencher/inundar a alma com sentimentos e emoções de forma profunda.', NULL, NULL, 'resumida', FALSE, FALSE, '2b17861cd9535399e26ab4c7c6f0108de2079263acd61a13d592267f72ad99c8', 'esa-2026-geral.txt'),
('ESA', 'História', 'História do Brasil - Primeiro e Segundo Reinado', 2026, 'Prova única', 'Exército Brasileiro', 8, '30', NULL, 'medio', NULL, 'O Império do Brasil acompanhava com atenção as evoluções geopolíticas na região da Bacia do Rio da Prata. Era uma área de grande importância, porque controlava o acesso ao interior e, especialmente, à província do Mato Grosso. Neste sentido, a Guerra contra Oribe e Rosas ocorreu porque:', '[{"letra": "A", "texto": "Dom Pedro II queria recuperar a Província Cisplatina."}, {"letra": "B", "texto": "A ocupação de Montevidéu por Oribe rompeu o equilíbrio estabelecido em 1828."}, {"letra": "C", "texto": "Manuel Oribe tinha a intenção de formar um novo Estado com o Rio Grande do Sul."}, {"letra": "D", "texto": "José Urquiza, governador da província de Corrientes, preparava a invasão do Mato Grosso."}, {"letra": "E", "texto": "Rivera organizava o exército paraguaio para unir-se a Urquiza contra o Império do Brasil."}]', 'B', 'A intervenção militar brasileira na Guerra contra Oribe e Rosas (1851-1852) foi motivada pela ameaça ao equilíbrio de poder na Bacia do Prata gerada pela ocupação de Montevidéu por Manuel Oribe com o apoio do governante argentino Juan Manuel de Rosas.', NULL, NULL, 'resumida', TRUE, FALSE, 'b0899c1e9950b97d987f06f6a3b7e09b1b23d6c9b9ce7c5f018a04870d68d73d', 'esa-2026-geral.txt'),
('ESA', 'Inglês', 'Interpretação de Texto', 2026, 'Prova única', 'Exército Brasileiro', 8, '46', NULL, 'medio', 'MODERN PEACEKEEPING OPERATIONS
Modern peacekeeping operations are inherently complex and place considerable demands on deployed personnel. At present, the most prevalent category of United Nations peacekeepers consists of infantry soldiers. However, there is an increasing requirement for specialized personnel, referred to as "enablers," which includes engineers, helicopter crews, transport units, communications specialists, and medical staff.
Prior to deployment, it is essential that troops undergo rigorous and comprehensive training. They must be adequately prepared to respond effectively to hostile scenarios, such as ambushes. Furthermore, conduct and discipline are critical components of the training regimen and are vital to operational success.
UN uniformed personnel are drawn from over 120 nations, bringing with them a wealth of cultural diversity and professional experience. This diversity significantly enriches the mission and enhances the capacity of peacekeeping forces to operate in varied and challenging environments.', 'Read the text and choose the incorrect statement about it.', '[{"letra": "A", "texto": "Modern peacekeeping operations demands mandatory pre-deployment training."}, {"letra": "B", "texto": "Peacekeepers must be trained not only in tactical response but also in behavioral standards."}, {"letra": "C", "texto": "Infantry soldiers remain the most common type of UN peacekeeper."}, {"letra": "D", "texto": "UN peacekeeping missions require personnel from diverse professional backgrounds."}, {"letra": "E", "texto": "The diversity of UN personnel poses challenges to mission cohesion and effectiveness."}]', 'E', 'A alternativa E traz uma afirmação incorreta sobre o texto. O texto original afirma que a diversidade cultural do pessoal da ONU "significantly enriches the mission" (enriquece significativamente a missão), e não que gera problemas ou desafios à coesão.', NULL, NULL, 'resumida', FALSE, FALSE, '1e67935b3827d096b2f17b86853e80803e4f583388a493827ed7c0b52f07bef9', 'esa-2026-geral.txt'),
('ESA', 'Matemática', 'Geometria Plana', 2026, 'Prova única', 'Exército Brasileiro', 9, '04', NULL, 'dificil', NULL, 'Em um triângulo equilátero (DEF) de perímetro igual a 60 cm, traça-se um segmento de reta com origem no ponto médio do lado DE até o ponto R, que se encontra sobre o prolongamento do segmento EF, sendo que: FR = 15 cm. Assim, o valor correto da medida de F até o ponto de interseção com o lado DF é:', '[{"letra": "A", "texto": "30 cm"}, {"letra": "B", "texto": "24 cm"}, {"letra": "C", "texto": "15 cm"}, {"letra": "D", "texto": "8 cm"}, {"letra": "E", "texto": "6 cm"}]', 'E', 'No triângulo equilátero DEF de lado 20 cm, M é ponto médio de DE (DM=10, ME=10), FR = 15 cm e ER = EF + FR = 35 cm. Aplicando o Teorema de Menelaus com a reta secante M-P-R sobre o triângulo DEF: (DM/ME) * (ER/FR) * (FP/PD) = 1 => (10/10) * (35/15) * (FP/PD) = 1 => FP/PD = 3/7. Como FP + PD = 20, temos FP + (7/3)FP = 20 => (10/3)FP = 20 => FP = 6 cm.', NULL, '[{"titulo": "Passo 1", "conteudo": "No triângulo equilátero DEF de lado 20 cm, M é ponto médio de DE (DM=10, ME=10), FR = 15 cm e ER = EF + FR = 35 cm.", "formula": null}, {"titulo": "Aplicando a fórmula", "conteudo": "Aplicando o Teorema de Menelaus com a reta secante M-P-R sobre o triângulo DEF: (DM/ME) * (ER/FR) * (FP/PD) = 1 => (10/10) * (35/15) * (FP/PD) = 1 => FP/PD = 3/7.", "formula": null}, {"titulo": "O que o enunciado dá", "conteudo": "Como FP + PD = 20, temos FP + (7/3)FP = 20 => (10/3)FP = 20 => FP = 6 cm.", "formula": null}]', 'automatica', TRUE, FALSE, 'cdd9b717b3f33ee4c97450ef1301fc4253ecca4a7e6ddb400b9c58f3ef03d71f', 'esa-2026-geral.txt'),
('ESA', 'Português', 'Interpretação de Texto', 2026, 'Prova única', 'Exército Brasileiro', 9, '25', NULL, 'facil', 'TEXTO IX
"Subi à carruagem que me aguardava, e, tão logo me acomodei, dei a ordem ao cocheiro. Durante o trajeto, os pensamentos se agitavam em minha mente, tumultuados e contraditórios. Algumas lembranças me assaltaram como vultos do passado, outras se dissipavam com o tempo. As ruas estavam silenciosas, e o luar conferia à cidade um aspecto quase onírico. Não sabia se era a nostalgia ou a dúvida o que mais me dominava. O coração apertava-se com uma dor estranha, como se a consciência me cobrasse escolhas já feitas. Tinham-se perdido, talvez, os últimos fragmentos da serenidade que outrora possuíra. Ou talvez não fosse a serenidade, mas a esperança, que lentamente se desfazia dentro de mim."
(ALENCAR, José de. Senhora. São Paulo: Martin Claret, 2009.)', 'Analisando o Texto IX, é correto afirmar que a personagem principal está em um estado emocional de:', '[{"letra": "A", "texto": "Euforia e entusiasmo, devido à expectativa do que o futuro lhe reserva."}, {"letra": "B", "texto": "Calma e serenidade, pois a viagem de carruagem a tranquiliza."}, {"letra": "C", "texto": "Medo e ansiedade, temendo um perigo iminente durante o percurso."}, {"letra": "D", "texto": "Melancolia e incerteza, refletindo sobre perdas e decisões passadas."}, {"letra": "E", "texto": "Saudosismo e alegria, lembrando-se de momentos felizes de seu passado."}]', 'D', 'O Texto IX expõe reflexões íntimas ("pensamentos se agitavam", "nostalgia ou a dúvida", "consciência me cobrasse escolhas já feitas"), evidenciando um estado de melancolia, incerteza e remorso do personagem.', NULL, NULL, 'resumida', FALSE, FALSE, '216b7e7f9879dbc5bbcc571e44fb646e1c30594ac8d33cc8ca8859933978cb90', 'esa-2026-geral.txt'),
('ESA', 'História', 'História do Brasil - Primeiro e Segundo Reinado', 2026, 'Prova única', 'Exército Brasileiro', 9, '31', NULL, 'medio', NULL, 'Luís Alves de Lima e Silva, futuro Duque de Caxias, comandou a ação militar imperial contra os farrapos. Hábil negociador, Caxias procurou estabelecer acordos com os líderes farroupilhas, a fim de alcançar a paz. Os fazendeiros gaúchos, para atender ao exército farrapo, incluíram as seguintes exigências:', '[{"letra": "A", "texto": "Liberdade para os escravos e maior participação política da população."}, {"letra": "B", "texto": "A separação do Império do Brasil e a criação de uma República Rio-Grandense."}, {"letra": "C", "texto": "Anistia do imperador aos revoltosos e a incorporação dos militares ao exército imperial."}, {"letra": "D", "texto": "A incorporação dos militares ao exército imperial e a anexação da Província Cisplatina."}, {"letra": "E", "texto": "Liberdade para todos os escravos no Brasil e máxima autonomia para a província de São Pedro do Rio Grande do Sul."}]', 'C', 'As negociações de paz conduzidas por Caxias (Paz de Ponche Verde, 1845) atenderam às principais exigências farroupilhas: anistia plena aos revoltosos, incorporação dos oficiais gaúchos ao Exército Imperial nos mesmos postos e libertação dos escravos que lutaram no exército farrapo.', NULL, NULL, 'resumida', FALSE, FALSE, '0279193cbacce27eeb58527226aa661260df4d4084b6eee23e5f111a1aebdb89', 'esa-2026-geral.txt'),
('ESA', 'Inglês', 'Interpretação de Texto', 2026, 'Prova única', 'Exército Brasileiro', 9, '50', NULL, 'facil', 'LUCKY LANDING IN BRAZIL
It was a lucky escape for the crew and passengers on this jet, as it managed to make an emergency landing in Brasilia on Friday after its front wheels failed to deploy.
None of the 49 passengers or crew of 5 on the Avianca Brazil Fokker 100 jet were injured in the landing, as the pilot managed to land the plane on its rear landing gear before lowering the nose onto the runway.
The pilot had declared the emergency after spotting the fault and then circled the Brazilian capital to shed fuel and reduce the weight of the jet before attempting the landing.
After the plane successfully touched down, airport fire crews sprayed it with foam to prevent it from setting alight.', 'Read the text and mark the wrong statement about it.', '[{"letra": "A", "texto": "The airplane touched down using its back wheels, then lowered its front part."}, {"letra": "B", "texto": "The pilot flew around the city to burn fuel and make the plane lighter before landing."}, {"letra": "C", "texto": "Firefighters covered the jet with foam after it landed to stop a fire from starting."}, {"letra": "D", "texto": "The crew were hurt when the plane landed without its front wheels."}, {"letra": "E", "texto": "The pilot noticed that something was wrong and told the airport before trying to land."}]', 'D', 'A alternativa D apresenta a afirmação incorreta sobre o texto, pois o segundo parágrafo afirma expressamente que "None of the 49 passengers or crew of 5... were injured" (nenhum passageiro ou membro da tripulação ficou ferido).', NULL, NULL, 'resumida', FALSE, FALSE, '260cadd12d08c50204e4b7bdf27cef8cba8dc8b027843aa5cac6f3b43828f3bf', 'esa-2026-geral.txt'),
('ESA', 'Matemática', 'Polinômios', 2026, 'Prova única', 'Exército Brasileiro', 10, '07', NULL, 'medio', NULL, 'As raízes do polinômio p(x) = 2x^3 - mx^2 + 17x - 6 são a, b e 2, com a > b. Nesse caso, é correto afirmar que a^b é igual a:', '[{"letra": "A", "texto": "1"}, {"letra": "B", "texto": "sqrt(2)"}, {"letra": "C", "texto": "2"}, {"letra": "D", "texto": "sqrt(3)"}, {"letra": "E", "texto": "4"}]', 'D', 'Pelas Relações de Girard para p(x) = 2x^3 - mx^2 + 17x - 6 com raízes a, b e 2:
Produto das raízes: a * b * 2 = 6/2 = 3 => a * b = 3/2.
Soma dos produtos dois a dois: a*b + 2a + 2b = 17/2 => 3/2 + 2(a+b) = 17/2 => a+b = 7/2.
Resolvendo t^2 - (7/2)t + 3/2 = 0, temos as raízes 3 e 1/2. Como a > b, a = 3 e b = 1/2. Assim, a^b = 3^(1/2) = sqrt(3).', NULL, '[{"titulo": "Passo 1", "conteudo": "Pelas Relações de Girard para p(x) = 2x^3 - mx^2 + 17x - 6 com raízes a, b e 2:\nProduto das raízes: a * b * 2 = 6/2 = 3 => a * b = 3/2.\nSoma dos produtos dois a dois: a*b + 2a + 2b = 17/2 => 3/2 + 2(a+b) = 17/2 => a+b = 7/2.", "formula": null}, {"titulo": "Fazendo a conta", "conteudo": "Resolvendo t^2 - (7/2)t + 3/2 = 0, temos as raízes 3 e 1/2.", "formula": null}, {"titulo": "O que o enunciado dá", "conteudo": "Como a > b, a = 3 e b = 1/2.", "formula": null}, {"titulo": "Conclusão", "conteudo": "Assim, a^b = 3^(1/2) = sqrt(3).", "formula": null}]', 'automatica', TRUE, FALSE, 'd9bb523a0d7c1a2d33f798b6eb655b148d814fff207d4ba9bba27d047ecd5c7a', 'esa-2026-geral.txt'),
('ESA', 'Português', 'Literatura Portuguesa', 2026, 'Prova única', 'Exército Brasileiro', 10, '26', NULL, 'facil', 'TEXTO X
"As armas e os barões assinalados
Que da ocidental praia Lusitana
Por mares nunca de antes navegados
Passaram ainda além da Taprobana,
Em perigos e guerras esforçados
Mais do que prometia a força humana,
E entre gente remota edificaram
Novo Reino, que tanto sublimaram."
(CAMÕES, Luís Vaz de. Os Lusíadas. Canto I, estrofe 1)', 'O Texto X pertence a uma das obras mais representativas da literatura portuguesa. Considerando as características formais e históricas da arte literária, assinale a alternativa correta:', '[{"letra": "A", "texto": "O excerto é um exemplo típico da lírica medieval portuguesa, que exaltava a fé cristã e os valores teocêntricos, típicos da literatura trovadoresca."}, {"letra": "B", "texto": "Os Lusíadas pertence ao gênero dramático e foi composto para ser encenado em cortes e castelos, conforme a tradição do teatro vicentino renascentista."}, {"letra": "C", "texto": "O texto de Camões é uma epopeia renascentista que pertence ao gênero épico, marcada pela exaltação do povo português e pelo culto ao humanismo e ao heroísmo."}, {"letra": "D", "texto": "A linguagem do trecho demonstra traços típicos do realismo-naturalismo, como a descrição objetiva dos navegadores e a crítica às instituições religiosas da época."}, {"letra": "E", "texto": "A epopeia camoniana inaugurou o barroco em Portugal, ao fundir os valores clássicos com o dilema existencial do homem entre o mundo e Deus."}]', 'C', 'O fragmento pertence ao Canto I de "Os Lusíadas", obra-prima de Luís Vaz de Camões pertencente ao gênero épico (epopeia renascentista), celebrando os feitos e o heroísmo do povo português nas navegações.', NULL, NULL, 'resumida', FALSE, FALSE, 'c7dde8a99ff474c14eb23c16cfea9bef7cc80730e6dda169fbafe2573326749d', 'esa-2026-geral.txt'),
('ESA', 'História', 'História do Brasil - Primeira República', 2026, 'Prova única', 'Exército Brasileiro', 10, '32', NULL, 'medio', NULL, 'Dentre as características da Constituição de 1891, a primeira do Brasil República, podemos assinalar:', '[{"letra": "A", "texto": "O voto censitário foi abolido, sendo estabelecido o direito de voto a todos os homens maiores de 18 anos."}, {"letra": "B", "texto": "A Constituição estabeleceu um sistema de eleições indiretas à Presidência da República pelo Congresso, o que levou os estados mais populosos (São Paulo e Minas Gerais) ao controle da Presidência."}, {"letra": "C", "texto": "Os deputados federais seriam eleitos para um mandato de 4 anos e os senadores para um mandato de 8 anos."}, {"letra": "D", "texto": "A Constituição proibia explicitamente os estados de contrair empréstimos no exterior, sendo esta competência exclusiva da União."}, {"letra": "E", "texto": "A autonomia dos estados ficou consagrada ao lhes serem conferidos os poderes e direitos que não lhes fossem negados por dispositivos do texto constitucional."}]', 'E', 'A Constituição de 1891 adotou o modelo federativo descentralizado de inspiração norte-americana, assegurando ampla autonomia aos estados e conferindo a eles todos os poderes e direitos não expressamente negados pelo texto constitucional federal.', NULL, NULL, 'resumida', FALSE, FALSE, '7a8c23be3831d374320fae4b623f99c50006e78208175ce6af83e70faf87aa09', 'esa-2026-geral.txt'),
('ESA', 'Inglês', 'Vocabulário e Phrasal Verbs', 2026, 'Prova única', 'Exército Brasileiro', 10, '48', NULL, 'facil', '[DESCRIÇÃO DA IMAGEM: Tirinha do Garfield em 6 quadros. Garfield vê uma rosquinha (doughnut). Um anjo-rosquinha e um diabo-rosquinha surgem. O anjo diz "DON''T EAT THAT POOR, DEFENSELESS DOUGHNUT!" e "DO WHAT IS RIGHT! DO WHAT''S IN YOUR HEART!". O diabo diz "DON''T LISTEN TO HIM! CHOW DOWN, PAL!". No último quadro, sobram apenas migalhas na mesa.]', 'Read the comic strip below:
Choose the best meaning of the phrasal verb "to chow down":', '[{"letra": "A", "texto": "To do something evil."}, {"letra": "B", "texto": "To eat quickly and with enthusiasm."}, {"letra": "C", "texto": "To pay attention to someone."}, {"letra": "D", "texto": "To lower something."}, {"letra": "E", "texto": "To reduce intensity."}]', 'B', 'O phrasal verb "to chow down" é uma expressão informal em inglês que significa devorar/comer algo rapidamente e com entusiasmo ("To eat quickly and with enthusiasm").', 'Tirinha do Garfield em 6 quadros. Garfield vê uma rosquinha (doughnut). Um anjo-rosquinha e um diabo-rosquinha surgem. O anjo diz "DON''T EAT THAT POOR, DEFENSELESS DOUGHNUT!" e "DO WHAT IS RIGHT! DO WHAT''S IN YOUR HEART!". O diabo diz "DON''T LISTEN TO HIM! CHOW DOWN, PAL!". No último quadro, sobram apenas migalhas na mesa.', NULL, 'resumida', FALSE, FALSE, '80e8da1f786dbb39efbba540cfe30043633bc442f300a0488af9aa75046ef331', 'esa-2026-geral.txt'),
('ESA', 'Matemática', 'Probabilidade', 2026, 'Prova única', 'Exército Brasileiro', 11, '05', NULL, 'medio', 'Modalidade | Quantidade de alunos
Basquete | 28
Futebol | 48
Vôlei | 32
Basquete e Futebol | 16
Basquete e Vôlei | 14
Futebol e Vôlei | 20
Basquete, Futebol e Vôlei | 6', 'Visando à preparação para a MAREXAER, competição esportiva entre as três escolas de formação de sargentos da Marinha do Brasil, do Exército Brasileiro e da Força Aérea Brasileira, um número x de alunos da ESA foi selecionado para participar de uma pesquisa, visando verificar a preferência deles para três modalidades esportivas. Os resultados foram tabelados abaixo:
A probabilidade de se escolher um aluno que tenha preferência por, no máximo, uma modalidade analisada, entre os x alunos selecionados inicialmente para a pesquisa, é igual a 21/40. Nessas condições, o número de alunos entre os x selecionados inicialmente que não manifestaram interesse por qualquer das modalidades analisadas é:', '[{"letra": "A", "texto": "12"}, {"letra": "B", "texto": "16"}, {"letra": "C", "texto": "24"}, {"letra": "D", "texto": "32"}, {"letra": "E", "texto": "40"}]', 'B', 'Calculando cada conjunto exclusivo:
Apenas Basquete = 4; Apenas Futebol = 18; Apenas Vôlei = 4.
Alunos em exatamente 1 modalidade = 4 + 18 + 4 = 26.
Alunos em 2 ou 3 modalidades = 10 + 8 + 14 + 6 = 38.
Total com preferência = 64. Seja N os sem preferência.
Probabilidade de no máximo uma modalidade (N + 26) / (N + 64) = 21 / 40.
Multiplicando cruzado: 40N + 1040 = 21N + 1344 => 19N = 304 => N = 16.', NULL, '[{"titulo": "Fazendo a conta", "conteudo": "Calculando cada conjunto exclusivo:\nApenas Basquete = 4; Apenas Futebol = 18; Apenas Vôlei = 4.\nAlunos em exatamente 1 modalidade = 4 + 18 + 4 = 26.\nAlunos em 2 ou 3 modalidades = 10 + 8 + 14 + 6 = 38.\nTotal com preferência = 64. Seja N os sem preferência.\nProbabilidade de no máximo uma modalidade (N + 26) / (N + 64) = 21 / 40.", "formula": null}, {"titulo": "Fazendo a conta", "conteudo": "Multiplicando cruzado: 40N + 1040 = 21N + 1344 => 19N = 304 => N = 16.", "formula": null}]', 'automatica', TRUE, FALSE, '646c8c871e26aafe826c5e5630709761a595301ff259ded8173f7eefbad7d224', 'esa-2026-geral.txt'),
('ESA', 'Português', 'Ortografia', 2026, 'Prova única', 'Exército Brasileiro', 11, '16', NULL, 'facil', NULL, 'Assinale a alternativa que apresenta erro de grafia.', '[{"letra": "A", "texto": "Conciliador - adjetivo que indica alguém que busca conciliação."}, {"letra": "B", "texto": "Imprescindível - palavra que significa algo absolutamente necessário."}, {"letra": "C", "texto": "Assintomático - termo usado para indicar ausência de sintomas."}, {"letra": "D", "texto": "Excessão - substantivo que significa ato ou efeito de excluir."}, {"letra": "E", "texto": "Paralelogramo - figura geométrica com dois pares de lados paralelos."}]', 'D', 'A palavra "Excessão" apresenta erro ortográfico. A grafia correta estabelecida pela norma culta da língua portuguesa é "Exceção" (grafada com x e ç).', NULL, NULL, 'resumida', FALSE, FALSE, '8788c348f7215a90ef4b30c46f126fe6c1b6bff290ee3aa9f4eff1478e23bbe5', 'esa-2026-geral.txt'),
('ESA', 'História', 'História do Brasil - Primeira República', 2026, 'Prova única', 'Exército Brasileiro', 11, '33', NULL, 'medio', '"se o Estado não foi um adversário da indústria, esteve longe de promover uma política deliberada de desenvolvimento industrial."
(FAUSTO, Boris. História do Brasil. 14 ed., atual. e ampl., 4. reimpr. São Paulo: Editora da Universidade de São Paulo, 2024. p. 249.)', 'Apesar de o eixo da economia brasileira durante a Primeira República estar orientado pelos negócios do café, este período também foi marcado por um processo incipiente de industrialização. Nesse sentido, Boris Fausto aponta que o Estado brasileiro não foi inimigo da indústria, porém não atuou para estimulá-la.
Sobre a industrialização durante a Primeira República, assinale a afirmativa incorreta:', '[{"letra": "A", "texto": "São Paulo e Minas Gerais eram, desde o final da década de 1900, os principais centros industriais do país - o que se explica pelo controle exercido sobre o poder central a partir da política do \"café com leite\"."}, {"letra": "B", "texto": "Apesar do relativo avanço da produção industrial no período, havia no país uma profunda carência de indústria de base de modo que boa parte do surto industrial dependia de importações."}, {"letra": "C", "texto": "Os imigrantes tiveram importante papel no processo de industrialização, tanto como donos de empresas como operários em São Paulo, por exemplo, os imigrantes respondiam por 70% dos integrantes das empresas manufatureiras da capital."}, {"letra": "D", "texto": "Na primeira década do século XX, o Rio de Janeiro era o principal centro industrial do país, com o Distrito Federal sendo responsável por 1/3 da produção industrial em 1907."}, {"letra": "E", "texto": "O Rio Grande do Sul teve um crescimento industrial importante no período, diferenciando-se de São Paulo, porém, por ter se desenvolvido quase inteiramente em função do mercado interno."}]', 'A', 'A afirmativa A está incorreta. No início do século XX, o Rio de Janeiro (Distrito Federal) era o maior parque industrial do Brasil, concentrando cerca de um terço de toda a produção manufatureira nacional em 1907.', NULL, NULL, 'resumida', FALSE, FALSE, 'bb16add07f35d13df291d989402a02a3649514423817d5d8ae6859a0d05b8da6', 'esa-2026-geral.txt'),
('ESA', 'Matemática', 'Probabilidade', 2026, 'Prova única', 'Exército Brasileiro', 12, '12', NULL, 'facil', NULL, 'Um baralho possui 52 cartas, que são divididas em 4 naipes diferentes (ouros, copas, paus e espadas), cada um destes possui 13 cartas, das quais são: 9 numéricas de "2 a 10", Valete (J), Dama (Q), Rei (K) e Ás (A). A probabilidade de a primeira carta retirada ser um REI e a segunda carta NÃO ser REI nem DAMA é:', '[{"letra": "A", "texto": "44/663"}, {"letra": "B", "texto": "45/663"}, {"letra": "C", "texto": "176/663"}, {"letra": "D", "texto": "48/663"}, {"letra": "E", "texto": "50/663"}]', 'A', 'Probabilidade da 1ª carta ser Rei = 4/52.
Com 1 Rei removido, sobram 51 cartas na mesa. Dessas, restam 3 Reis e 4 Damas (total de 7 cartas que são Rei/Dama). Logo, há 51 - 7 = 44 cartas que não são nem Rei nem Dama.
Probabilidade da 2ª carta = 44/51.
Probabilidade conjunta = (4/52) * (44/51) = (1/13) * (44/51) = 44 / 663.', NULL, '[{"titulo": "Passo 1", "conteudo": "Probabilidade da 1ª carta ser Rei = 4/52.\nCom 1 Rei removido, sobram 51 cartas na mesa. Dessas, restam 3 Reis e 4 Damas (total de 7 cartas que são Rei/Dama).", "formula": null}, {"titulo": "Conclusão", "conteudo": "Logo, há 51 - 7 = 44 cartas que não são nem Rei nem Dama.\nProbabilidade da 2ª carta = 44/51.\nProbabilidade conjunta = (4/52) * (44/51) = (1/13) * (44/51) = 44 / 663.", "formula": null}]', 'automatica', TRUE, FALSE, '642b6119665467877b71c931b0fd60e650d86ef1c19d2db9de05a4301cd7bacd', 'esa-2026-geral.txt'),
('ESA', 'Português', 'Pontuação', 2026, 'Prova única', 'Exército Brasileiro', 12, '15', NULL, 'medio', 'TEXTO I
"Nasceu o sol. E, como ela estava com tempo, sentou-se num banco do jardim. Um homem mastigava chicletes. Outro lia jornal. Uma mulher estava parada, com um saco de pão no colo. A vida era aquilo. Os minutos passavam, como passam em qualquer lugar."
(Becker, A. Armandinho.)', 'Com base no uso da vírgula no último período do Texto I - "Os minutos passavam, como passam em qualquer lugar" - assinale a alternativa correta:', '[{"letra": "A", "texto": "A vírgula está incorreta, pois separa sujeito e predicado, o que fere a norma-padrão."}, {"letra": "B", "texto": "A vírgula separa duas orações coordenadas assindéticas com sujeitos distintos, o que justifica seu uso."}, {"letra": "C", "texto": "A vírgula isola uma oração subordinada adverbial comparativa, o que está de acordo com a norma-padrão."}, {"letra": "D", "texto": "O uso da vírgula é inadequado, pois o advérbio \"como\" não exige isolamento da oração seguinte."}, {"letra": "E", "texto": "A vírgula marca uma enumeração de ações no tempo."}]', 'C', 'No trecho "Os minutos passavam, como passam em qualquer lugar", a conjunção "como" introduz uma oração subordinada adverbial comparativa. A vírgula é utilizada corretamente para isolar a oração subordinada.', NULL, NULL, 'resumida', FALSE, FALSE, '7a265764ef5f75f8f8b22a4250d63faf86503ce4aea491b74c1dbcc1a9e6e753', 'esa-2026-geral.txt'),
('ESA', 'História', 'História do Brasil - Era Vargas e Segunda Guerra', 2026, 'Prova única', 'Exército Brasileiro', 12, '34', NULL, 'facil', '"A conquista de Monte Castelo, ocorrida durante a Segunda Guerra Mundial, foi uma das mais árduas batalhas enfrentadas pela Força Expedicionária Brasileira (FEB) na Campanha da Itália. O dia 21 de fevereiro de 1945 será sempre lembrado pelo admirável exemplo de bravura e sacrifício dos nossos pracinhas. Naquela gélida tarde do inverno europeu, teve sucesso a incursão rumo ao cume do Castelo. Sua conquista, um dos mais gloriosos feitos das Armas nacionais, marcou a história do Exército Brasileiro e contribuiu para acelerar a retirada das tropas alemãs do território italiano. [...] A tomada de Monte Castelo traduz o esforço e o sacrifício dos soldados brasileiros na Segunda Guerra Mundial, consolidando o papel da FEB na libertação da Itália e na luta contra o nazifascismo. Lembrar Monte Castelo é reverenciar nossos heróis!"
(80 anos da tomada de Monte Castelo. Disponível em: https://www.eb.mil.br/.)', 'O trecho acima foi publicado em homenagem aos 80 anos da tomada do Monte Castelo, no contexto da campanha brasileira durante a Segunda Guerra Mundial. Sobre a participação brasileira neste conflito, podemos afirmar corretamente que:', '[{"letra": "A", "texto": "A FEB não foi uma iniciativa imposta pelos Aliados, mas sim uma decisão do governo brasileiro."}, {"letra": "B", "texto": "A população recebeu com apatia e revolta a proclamação da guerra, dado o forte sentimento de simpatia existente na população brasileira para com a Itália."}, {"letra": "C", "texto": "Devido aos regulamentos segregacionistas então vigentes nas Forças Armadas dos EUA, às quais a tropa brasileira estava subordinada, os negros tiveram sua participação vetada na FEB."}, {"letra": "D", "texto": "A entrada do Brasil na guerra foi provocada a partir do desembarque de tropas nazistas no Sul do país, cujo objetivo era o de anexar os estados de Santa Catarina e Rio Grande do Sul ao Reich alemão."}, {"letra": "E", "texto": "Aproximadamente 2 mil homens lutaram na Itália, sob o comando do general Góis Monteiro, até o fim do conflito naquele país, em 2 de maio de 1945."}]', 'A', 'O envio da Força Expedicionária Brasileira (FEB) não decorreu de uma imposição sumária dos Aliados, mas sim de uma decisão soberana e negociada pelo governo de Getúlio Vargas em troca de apoio econômico (como a construção da Usina de Volta Redonda) e militar.', NULL, NULL, 'resumida', FALSE, FALSE, 'b71d3fef620168d8b38cd61c2dbbc66e45f9cd98d11c83d4f3b9e7576d77b387', 'esa-2026-geral.txt'),
('ESA', 'Matemática', 'Progressão Geométrica e Logaritmos', 2026, 'Prova única', 'Exército Brasileiro', 13, '11', NULL, 'dificil', NULL, 'Se log_{root(108)(1/3)} (root(4)(3)), log_{root(18)(3)} (sqrt(3)), log (sqrt(10))^{-6} formam nessa ordem uma PG, qual o valor aproximado da soma dos 8 primeiros termos:', '[{"letra": "A", "texto": "-20,25"}, {"letra": "B", "texto": "20,25"}, {"letra": "C", "texto": "25,25"}, {"letra": "D", "texto": "-25,25"}, {"letra": "E", "texto": "-23,25"}]', 'A', 'Convertendo os logaritmos para a base 3:
a1 = log_{3^(-1/108)} (3^(1/4)) = (1/4) / (-1/108) = -27.
a2 = log_{3^(1/18)} (3^(1/2)) = (1/2) / (1/18) = 9.
a3 = log (10^(-3)) = -3.
A PG é (-27, 9, -3,...), com a1 = -27 e razão q = -1/3.
A soma dos 8 primeiros termos é S8 = -27 * (1 - (-1/3)^8) / (1 - (-1/3)) = -27 * (1 - 1/6561) / (4/3) = -20,2469... aproximadamente -20,25.', NULL, '[{"titulo": "Passo 1", "conteudo": "Convertendo os logaritmos para a base 3:\na1 = log_{3^(-1/108)} (3^(1/4)) = (1/4) / (-1/108) = -27.\na2 = log_{3^(1/18)} (3^(1/2)) = (1/2) / (1/18) = 9.\na3 = log (10^(-3)) = -3. A PG é (-27, 9, -3,...), com a1 = -27 e razão q = -1/3.", "formula": null}, {"titulo": "Conclusão", "conteudo": "A soma dos 8 primeiros termos é S8 = -27 * (1 - (-1/3)^8) / (1 - (-1/3)) = -27 * (1 - 1/6561) / (4/3) = -20,2469... aproximadamente -20,25.", "formula": null}]', 'automatica', TRUE, FALSE, '95cbbd92cade6b330e550570528491f254f6d3a9dc36d88b979a2e1d4caf1988', 'esa-2026-geral.txt'),
('ESA', 'Português', 'Sintaxe e Análise Morfossintática', 2026, 'Prova única', 'Exército Brasileiro', 13, '20', NULL, 'medio', 'TEXTO V
"Mesmo que persista certa desconfiança de familiares e professores sobre o uso de dispositivos eletrônicos móveis na sala de aula, gestores do ensino público e particular começam a correr atrás da adaptação do conteúdo didático para formatos digitais, uma vez que, antes mesmo de largar as fraldas, um número cada vez maior de crianças já tem mais o que fazer com os dedinhos do que roer unhas."
(MING, Celso. Mochila digital. O Estado de S. Paulo, 1º fev.2014.)', 'Com base na estrutura sintática e nas relações semântico-discursivas estabelecidas pelas orações subordinadas adverbiais presentes no Texto V, assinale a alternativa que identifica corretamente, na ordem em que aparecem, os valores lógicos das orações subordinadas:', '[{"letra": "A", "texto": "concessiva - condicional - causal - temporal - comparativa"}, {"letra": "B", "texto": "explicativa - proporcional - consecutiva"}, {"letra": "C", "texto": "concessiva - explicativa - temporal - proporcional"}, {"letra": "D", "texto": "condicional - causal - concessiva - comparativa"}, {"letra": "E", "texto": "concessiva - causal - concessiva - consecutiva"}]', 'A', 'As orações subordinadas adverbiais no texto expressam sequencialmente os seguintes sentidos: "Mesmo que" (concessiva), condição implícita na adaptação, "uma vez que" (causal), "antes mesmo de" (temporal) e "mais... do que" (comparativa).', NULL, NULL, 'resumida', FALSE, FALSE, '9310876fa6d0baf8ebffd6e6bf13cf6f97e93954c607cd5750b7cf4e1dd69e07', 'esa-2026-geral.txt'),
('ESA', 'Matemática', 'Trigonometria', 2026, 'Prova única', 'Exército Brasileiro', 14, '09', NULL, 'medio', '[DESCRIÇÃO DA IMAGEM: Figura plana representando um triângulo ABC com vértices A e B na base e C no topo. O ângulo em A é indicado por alpha e o ângulo em B por beta. A distância entre A e B é igual a ''a''.]', 'O pelotão de obras da Escola de Sargentos das Armas recebeu a missão de reconhecimento topográfico, que consiste em calcular a área de um terreno triangular ABC, ilustrado na figura abaixo.
Os pontos A e B foram acessados normalmente, mas o ponto C estava dentro de uma área minada, portanto, inacessível por questões de segurança. Para cumprir a missão, o comandante do pelotão mediu os ângulos CÂB, CâB e a distância AB, obtendo, respectivamente, alpha, beta e a. Qual a área do triângulo encontrada pelo comandante?', '[{"letra": "A", "texto": "(a^2 * sen(alpha) * sen(beta)) / (2 * sen(alpha + beta))"}, {"letra": "B", "texto": "(a^2 * sen(alpha)) / (sen(alpha) + sen(beta))"}, {"letra": "C", "texto": "(a^2 * sen(beta)) / (sen(alpha) + sen(beta))"}, {"letra": "D", "texto": "(a^2 * sen(alpha + beta)) / (2 * sen(alpha) * sen(beta))"}, {"letra": "E", "texto": "(a^2 * sen(alpha + beta)) / (sen(alpha) * sen(beta))"}]', 'A', 'No triângulo ABC com lado c = AB = a, ângulos A = alpha e B = beta, o ângulo C é 180° - (alpha + beta), logo sen(C) = sen(alpha + beta). Pela Lei dos Senos, o lado AC (b) é b / sen(beta) = a / sen(alpha + beta) => b = (a * sen(beta)) / sen(alpha + beta). A área do triângulo é A = (1/2) * a * b * sen(alpha) = (a^2 * sen(alpha) * sen(beta)) / (2 * sen(alpha + beta)).', 'Figura plana representando um triângulo ABC com vértices A e B na base e C no topo. O ângulo em A é indicado por alpha e o ângulo em B por beta. A distância entre A e B é igual a ''a''.', '[{"titulo": "Passo 1", "conteudo": "No triângulo ABC com lado c = AB = a, ângulos A = alpha e B = beta, o ângulo C é 180° - (alpha + beta), logo sen(C) = sen(alpha + beta).", "formula": null}, {"titulo": "Aplicando a fórmula", "conteudo": "Pela Lei dos Senos, o lado AC (b) é b / sen(beta) = a / sen(alpha + beta) => b = (a * sen(beta)) / sen(alpha + beta). A área do triângulo é A = (1/2) * a * b * sen(alpha) = (a^2 * sen(alpha) * sen(beta)) / (2 * sen(alpha + beta)).", "formula": null}]', 'automatica', TRUE, FALSE, '11a3426432d7a4a58c3522fcff097f93fa2c26409d6960cf65b4515d08c87086', 'esa-2026-geral.txt'),
('ESA', 'Português', 'Sintaxe e Análise Morfossintática', 2026, 'Prova única', 'Exército Brasileiro', 14, '23', NULL, 'medio', 'TEXTO VII
"O Exército pode passar cem anos sem ser usado, mas não pode passar um minuto sem estar preparado."
(BARBOSA, Rui.)', 'Leia o Texto VII e marque a alternativa incorreta em relação à análise morfossintática:', '[{"letra": "A", "texto": "É um período composto, pois observam-se vários componentes verbais."}, {"letra": "B", "texto": "O texto exemplifica um período composto, porque o sujeito é indeterminado."}, {"letra": "C", "texto": "No trecho \"O Exército pode passar cem anos...\" o sujeito é simples."}, {"letra": "D", "texto": "Em \"...mas não pode passar um minuto...\", o \"não\" é adjunto adverbial."}, {"letra": "E", "texto": "No excerto \"...não pode passar um minuto sem...\", o \"pode passar\" é uma locução verbal."}]', 'B', 'A alternativa B é incorreta porque a classificação do trecho como período composto ocorre pela presença de duas orações organizadas por locuções verbais, e o sujeito da primeira oração é simples e determinado ("O Exército").', NULL, NULL, 'resumida', FALSE, FALSE, '3a85e9ae7eb8ff39bc26e7dbbe2dac138021365cb43b895d322619f0218f26a8', 'esa-2026-geral.txt');
-- ─── 1. Garante que as matérias existem ─────────────────────────────
INSERT INTO materias (nome, descricao, icone_emoji)
SELECT DISTINCT s.materia_nome, 'Importada do banco de questões oficial', '📚'
FROM stg_questoes s
WHERE s.materia_nome IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM materias m WHERE m.nome = s.materia_nome);

-- ─── 2. Garante que os assuntos existem ─────────────────────────────
INSERT INTO assuntos (materia_id, nome, ordem)
SELECT DISTINCT m.id, s.assunto_nome, 0
FROM stg_questoes s
JOIN materias m ON m.nome = s.materia_nome
WHERE s.assunto_nome IS NOT NULL
  AND NOT EXISTS (
    SELECT 1 FROM assuntos a
    WHERE a.materia_id = m.id AND a.nome = s.assunto_nome
  );

-- ─── 3. Vincula matéria ao concurso (alimenta os filtros da UI) ─────
INSERT INTO concurso_materias (concurso_id, materia_id)
SELECT DISTINCT c.id, m.id
FROM stg_questoes s
JOIN concursos c ON c.sigla = s.concurso_sigla
JOIN materias  m ON m.nome  = s.materia_nome
WHERE NOT EXISTS (
  SELECT 1 FROM concurso_materias cm
  WHERE cm.concurso_id = c.id AND cm.materia_id = m.id
);

-- ─── 4. Insere as questões ──────────────────────────────────────────
INSERT INTO questoes (
  concurso_id, materia_id, assunto_id,
  enunciado, texto_base, alternativas, resposta_correta, explicacao,
  ano, banca, dificuldade, dia_prova, numero_ordem, numero_original,
  area_conhecimento, figura_descricao, resolucao_passos, resolucao_status,
  precisa_resolucao, anulada, hash_conteudo, arquivo_origem, ativa
)
SELECT
  c.id, m.id, a.id,
  s.enunciado, s.texto_base, s.alternativas, s.resposta_correta, s.explicacao,
  s.ano, s.banca, s.dificuldade::dificuldade_tipo, s.dia_prova,
  s.numero_ordem, s.numero_original, s.area_conhecimento, s.figura_descricao,
  s.resolucao_passos, s.resolucao_status, s.precisa_resolucao, s.anulada,
  s.hash_conteudo, s.arquivo_origem, TRUE
FROM stg_questoes s
JOIN concursos c ON c.sigla = s.concurso_sigla
JOIN materias  m ON m.nome  = s.materia_nome
JOIN assuntos  a ON a.materia_id = m.id AND a.nome = s.assunto_nome
WHERE s.resposta_correta IS NOT NULL
ON CONFLICT (hash_conteudo) DO NOTHING;

-- ─── 5. Registra a importação no armazém ────────────────────────────
INSERT INTO questao_importadas (hash_conteudo, questao_id, arquivo_origem, status)
SELECT s.hash_conteudo, q.id, s.arquivo_origem, 'aceita'::questao_importada_status
FROM stg_questoes s
JOIN questoes q ON q.hash_conteudo = s.hash_conteudo
WHERE NOT EXISTS (
  SELECT 1 FROM questao_importadas qi WHERE qi.hash_conteudo = s.hash_conteudo
);

COMMIT;

SELECT
  'ESA — lote 1/1' AS seed,
  (SELECT COUNT(*) FROM questoes) AS total_questoes_no_banco;
